INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-vs-donkey-kong---mini-land-mayhem!-europe-enfrdeesit-ndsi-enhanced', 'NDS', 'Mario vs. Donkey Kong - Mini-Land Mayhem! (Europe) (En,Fr,De,Es,It) (NDSi Enhanced)', '2010', 'Puzzle', 'Nintendo', '1', 'Action Puzzle', 'Lemmings-style puzzle game with toy robots.', 'Guide Mini-Mario toys to the exit by building paths.', 'Creative puzzle-action game with DSi enhancements.', 'Mario vs. Donkey Kong: Mini-Land Mayhem! te da las herramientas para ser arquitecto. Coloca vigas, tuberías y trampolines para guiar a los juguetes. Incluye un potente editor de niveles para crear y compartir tus propios desafíos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-vs-donkey-kong---totsugeki!-mini-land-japan-ndsi-enhanced', 'NDS', 'Mario vs. Donkey Kong - Totsugeki! Mini-Land (Japan) (NDSi Enhanced)', '2010', 'Puzzle', 'Nintendo', '1', 'Action Puzzle', 'Lemmings-style puzzle game with toy robots.', 'Guide Mini-Mario toys to the exit by building paths.', 'Japanese version of Mini-Land Mayhem!', 'Mario vs. Donkey Kong: Totsugeki! Mini-Land ofrece la misma profundidad táctica. Salva a Pauline de las garras de DK planeando rutas seguras para los Mini-Marios en este juego que mezcla estrategia y reflejos rápidos de forma magistral.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mariowa-sonic---beijing-olympic-korea', 'NDS', 'Mariowa Sonic - Beijing Olympic (Korea)', '2008', 'Sports', 'Sega', '4', 'Olympic Sports', 'Olympic sports mini-game collection.', 'Compete in various Olympic events to win gold medals.', 'Korean version of Mario & Sonic at the Beijing Olympics.', 'Mariowa Sonic: Beijing Olympic une a los dos íconos en Corea. Compite en atletismo, natación y gimnasia usando el stylus y el micrófono, demostrando quién es el personaje más rápido y fuerte de los videojuegos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mariowa-sonic---vancouver-donggye-olympic-korea', 'NDS', 'Mariowa Sonic - Vancouver Donggye-olympic (Korea)', '2010', 'Sports', 'Sega', '4', 'Olympic Sports', 'Winter Olympic sports mini-game collection.', 'Win gold in skiing, skating, and snowboarding events.', 'Korean version of Mario & Sonic at the Winter Games.', 'Mariowa Sonic: Vancouver Donggye-olympic traslada la rivalidad al hielo. Disfruta de emocionantes eventos de invierno y los divertidos "Dream Events" en esta localización coreana perfecta para jugar con amigos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marker-man-adventures-usa', 'NDS', 'Marker Man Adventures (USA)', '2009', 'Action', 'Big Blue Bubble', '1', 'Action Platformer', 'Physics-based drawing and platforming.', 'Help Marker Man find his way by drawing shapes.', 'Creative puzzle-platformer using a drawing mechanic.', 'Marker Man Adventures te permite crear soluciones con el stylus. Dibuja palancas, ruedas y puentes para ayudar al personaje a superar obstáculos. Es un juego que fomenta la creatividad y la resolución de problemas mediante la física.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marl-oukoku-no-ningyou-hime---tenshi-ga-kanaderu-ai-no-uta-japan', 'NDS', 'Marl Oukoku no Ningyou Hime - Tenshi ga Kanaderu Ai no Uta (Japan)', '2006', 'Role-Playing Game', 'Idea Factory', '1', 'Japanese RPG', 'Strategy RPG with musical elements and anime aesthetic.', 'Help Cornet find her prince with the power of singing puppets.', 'DS remake of the classic PS1 "Rhapsody" RPG.', 'Marl Oukoku no Ningyou Hime es un RPG musical encantador. Con batallas tácticas simplificadas y una historia llena de canciones y humor, es una joya oculta de Nippon Ichi Software que brilla por su presentación artística y emocional.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('martin-mystery-europe-enfrdeesit', 'NDS', 'Martin Mystery (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Blast! Entertainment', '1', 'Action Adventure', 'Mystery adventure based on the animated series.', 'Solve supernatural cases using specialized gadgets.', 'Investigative adventure featuring the Martin Mystery cast.', 'Martin Mystery (Europe) te pone al mando del Centro. Investiga fenómenos paranormales junto a Martin, Diana y Java, combinando exploración en 3D con mini-juegos de lógica para desentrañar misterios sobrenaturales.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-goukaku-shikaku-dasshu!---fp-ginou-kentei-shiken-2-kyuu-3-kyuu-japan', 'NDS', 'Maru Goukaku Shikaku Dasshu! - FP Ginou Kentei Shiken 2-kyuu, 3-kyuu (Japan)', '2007', 'Educational', 'Takara Tomy', '1', 'Exam Training', 'Educational study aid with mock exams and drills.', 'Prepare for the Level 2 and 3 Financial Planning exams.', 'Comprehensive FP certification trainer for Japan.', 'Maru Goukaku Shikaku Dasshu! FP Ginou Kentei is a professional study tool for aspiring financial planners. It features a massive database of past exam questions, timed practice tests, and progress tracking to ensure success in the national certification exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-goukaku-shikaku-dasshu!---gyouseishoshi-shiken-japan', 'NDS', 'Maru Goukaku Shikaku Dasshu! - Gyouseishoshi Shiken (Japan)', '2007', 'Educational', 'Takara Tomy', '1', 'Exam Training', 'Educational study aid with mock exams and drills.', 'Study for and pass the Administrative Scrivener exam.', 'Legal certification prep for Japanese scriveners.', 'This entry in the "Maru Goukaku" series focuses on the Gyouseishoshi (Administrative Scrivener) exam. It provides intensive training on Japanese civil law and administrative regulations through structured lessons and simulated testing environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-goukaku-shikaku-dasshu!---hanbaishi-kentei-shiken-2-kyuu-3-kyuu-japan', 'NDS', 'Maru Goukaku Shikaku Dasshu! - Hanbaishi Kentei Shiken 2-kyuu, 3-kyuu (Japan)', '2007', 'Educational', 'Takara Tomy', '1', 'Exam Training', 'Educational study aid with mock exams and drills.', 'Master retail sales skills for Level 2 and 3 certification.', 'Sales and retail management certification trainer.', 'Maru Goukaku Shikaku Dasshu! Hanbaishi Kentei helps users prepare for the "Retail Marketing" exams. It covers inventory management, customer service, and store operations, using the DS stylus for interactive drills and quick-fire quizzes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-goukaku-shikaku-dasshu!---it-passport-shiken-kihon-jouhou-gijutsusha-shiken-ouyou-jouhou-gijutsusha-shiken-japan', 'NDS', 'Maru Goukaku Shikaku Dasshu! - IT Passport Shiken, Kihon Jouhou Gijutsusha Shiken, Ouyou Jouhou Gijutsusha Shiken (Japan)', '2009', 'Educational', 'Takara Tomy', '1', 'IT Exam Training', 'Educational study aid with mock exams and drills.', 'Pass the IT Passport and Information Technology exams.', 'IT certification and technical knowledge trainer.', 'This comprehensive IT study guide covers the IT Passport through Applied Information Technology exams. It is an essential tool for Japanese professionals and students looking to validate their technical skills with official national certifications.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-goukaku-shikaku-dasshu!---tac-koumuin-shiken-japan', 'NDS', 'Maru Goukaku Shikaku Dasshu! - TAC Koumuin Shiken (Japan)', '2008', 'Educational', 'Takara Tomy', '1', 'Civil Service Exam Training', 'Educational study aid for civil service entrance.', 'Prepare for the competitive TAC Civil Service exams.', 'Civil service job entrance exam preparation tool.', 'Developed in collaboration with TAC, this title prepares users for the rigors of the Japanese Civil Service examinations. It focuses on logic, general knowledge, and specialized subjects required for government positions across the country.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-kaite-don-don-oboeru---kyoui-no-tsugawa-shiki-kanji-kiokujutsu---kiso-gakushuu-hen-japan', 'NDS', 'Maru Kaite Don Don Oboeru - Kyoui no Tsugawa Shiki Kanji Kiokujutsu - Kiso Gakushuu Hen (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Kanji Learning', 'Handwriting-based Kanji memorization drills.', 'Learn basic Kanji through the unique Tsugawa method.', 'Innovative Kanji memorization and writing trainer.', 'Maru Kaite Don Don Oboeru focuses on the "Tsugawa Method" to help students memorize Kanji visually and through repetition. The basic version is designed for primary education, focusing on core characters and correct stroke order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maru-kaite-don-don-oboeru---kyoui-no-tsugawa-shiki-kanji-kiokujutsu-japan', 'NDS', 'Maru Kaite Don Don Oboeru - Kyoui no Tsugawa Shiki Kanji Kiokujutsu (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Kanji Learning', 'Handwriting-based Kanji memorization drills.', 'Master advanced Kanji characters using mnemonics.', 'Advanced Kanji learning and writing tool for NDS.', 'This expanded version of the Tsugawa Shiki Kanji series provides more complex characters and advanced memorization techniques. Use the touch screen to practice writing and leverage mnemonic devices to improve long-term retention of difficult Kanji.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maruhan-pachinko-&-pachi-slot-hisshou-guide-kyouryoku---the-pachinko-hall-japan', 'NDS', 'Maruhan Pachinko & Pachi-Slot Hisshou Guide Kyouryoku - The Pachinko Hall (Japan)', '2009', 'Simulation', 'Dorasu', '1', 'Pachinko Simulation', 'Pachinko and Pachi-slot simulation with hall management.', 'Master the machines and manage a virtual parlor.', 'Realistic Pachinko hall simulation and strategy guide.', 'Developed with the Maruhan chain, this title offers realistic simulations of popular Pachinko and Pachi-slot machines. Learn the "hit" patterns, manage your virtual bankroll, and experience the excitement of the parlor floor in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel---ultimate-alliance-2-europe', 'NDS', 'Marvel - Ultimate Alliance 2 (Europe)', '2009', 'Action Role-Playing Game', 'Vicarious Visions', '4', 'Action RPG', 'Isometric action-RPG with squad-based combat.', 'Stop the superhuman Civil War and defeat the Fold.', 'Epic Marvel superhero team-up adventure for DS.', 'Marvel: Ultimate Alliance 2 on NDS allows you to build a team of four heroes. Choose between Pro-Registration or Anti-Registration, unlock Fusion attacks, and battle through a branching storyline inspired by the famous comic book arc.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel---ultimate-alliance-2-usa', 'NDS', 'Marvel - Ultimate Alliance 2 (USA)', '2009', 'Action Role-Playing Game', 'Vicarious Visions', '4', 'Action RPG', 'Isometric action-RPG with squad-based combat.', 'Stop the superhuman Civil War and defeat the Fold.', 'North American release of the superhero RPG sequel.', 'Join the fight in Marvel: Ultimate Alliance 2 (USA). Assemble your dream team from characters like Iron Man, Captain America, and Wolverine. Master touch-screen gestures for special powers and enjoy cooperative-style tactical combat on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-nemesis---rise-of-the-imperfects-europe-enfrde', 'NDS', 'Marvel Nemesis - Rise of the Imperfects (Europe) (En,Fr,De)', '2005', 'Fighting', 'Game Refuge', '2', '3D Fighting', '3D fighting game with a destructible environment.', 'Defeat the Imperfects and save the Marvel Universe.', 'Dark and gritty superhero brawler for the NDS.', 'Marvel Nemesis: Rise of the Imperfects features a unique cast of original villains clashing with Marvel icons. Utilize interactive environments, perform brutal finishing moves, and experience a dark, comic-style narrative in this action-packed fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-nemesis---rise-of-the-imperfects-usa', 'NDS', 'Marvel Nemesis - Rise of the Imperfects (USA)', '2005', 'Fighting', 'Game Refuge', '2', '3D Fighting', '3D fighting game with a destructible environment.', 'Defeat the Imperfects and save the Marvel Universe.', 'North American release of the Marvel Nemesis brawler.', 'Unleash your powers in Marvel Nemesis (USA). Fight as Spider-Man, The Thing, or Venom in 3D arenas. Use the DS dual screens to track health and special meter as you battle to protect Earth from a mysterious alien threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad---the-infinity-gauntlet-europe-deit', 'NDS', 'Marvel Super Hero Squad - The Infinity Gauntlet (Europe) (De,It)', '2010', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with stylized graphics.', 'Stop Thanos from assembling the Infinity Gauntlet.', 'Family-friendly Marvel action with cartoon aesthetics.', 'Marvel Super Hero Squad: The Infinity Gauntlet (Europe) features a "Super Deformed" art style. Control Iron Man, Thor, and Hulk in a series of levels focused on combat and simple puzzles, designed for younger fans of the Marvel universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad---the-infinity-gauntlet-europe-enfr', 'NDS', 'Marvel Super Hero Squad - The Infinity Gauntlet (Europe) (En,Fr)', '2010', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with stylized graphics.', 'Stop Thanos from assembling the Infinity Gauntlet.', 'English/French European edition of the Marvel squad.', 'This version provides a localized experience for English and French speakers. Enjoy the humorous dialogue and fast-paced brawling action as the Squad works together to recover the Infinity Gems before the Mad Titan can use them.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad---the-infinity-gauntlet-usa-enfr', 'NDS', 'Marvel Super Hero Squad - The Infinity Gauntlet (USA) (En,Fr)', '2010', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with stylized graphics.', 'Stop Thanos from assembling the Infinity Gauntlet.', 'North American release of the Infinity Gauntlet saga.', 'Hero up in Marvel Super Hero Squad: The Infinity Gauntlet (USA). With drop-in/drop-out cooperative play and unique character abilities, it’s a fun and accessible action game that captures the charm of the popular toy line and animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad-europe-enfrdenl', 'NDS', 'Marvel Super Hero Squad (Europe) (En,Fr,De,Nl)', '2009', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Action-adventure and brawler with squad mechanics.', 'Defeat Doctor Doom and his Lethal Legion.', 'The first Marvel Super Hero Squad adventure for Europe.', 'Assemble the Squad in this multi-language European release. Navigate through various environments, smash enemies, and use character-specific "Hero Up" moves to save Super Hero City from Doctor Doom''s nefarious plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad-europe-esit', 'NDS', 'Marvel Super Hero Squad (Europe) (Es,It)', '2009', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Action-adventure and brawler with squad mechanics.', 'Defeat Doctor Doom and his Lethal Legion.', 'Spanish/Italian regional release of the Squad game.', 'This regional version brings the high-energy action of Marvel Super Hero Squad to Spanish and Italian players. It features the same colorful graphics and accessible gameplay that makes the series a hit with younger Marvel fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad-korea-enko', 'NDS', 'Marvel Super Hero Squad (Korea) (En,Ko)', '2009', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Action-adventure and brawler with squad mechanics.', 'Defeat Doctor Doom and his Lethal Legion.', 'Korean localized release of the Super Hero Squad.', 'Experience the fun of the Squad in Korea. Featuring localized text and the classic "Hero Up" mechanics, this title allows Korean fans to control their favorite Marvel heroes in a lighthearted and action-filled handheld journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-hero-squad-usa-enfres', 'NDS', 'Marvel Super Hero Squad (USA) (En,Fr,Es)', '2009', 'Action', 'Griptonite Games', '2', 'Beat ''em Up', 'Action-adventure and brawler with squad mechanics.', 'Defeat Doctor Doom and his Lethal Legion.', 'North American release of the Super Hero Squad debut.', 'Marvel Super Hero Squad (USA) turns the DS into a battleground for justice. Switch between heroes on the fly, collect Infinity Fractals, and enjoy a variety of mini-games and combat missions set in the vibrant Marvel universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-trading-card-game-europe-enfrdeesit', 'NDS', 'Marvel Trading Card Game (Europe) (En,Fr,De,Es,It)', '2007', 'Card Game', 'Konami', '2', 'Trading Card Game', 'Strategic card-battling with Marvel characters.', 'Win tactical card duels to progress through the story.', 'Deep and strategic Marvel trading card game.', 'Marvel Trading Card Game (Europe) brings the VS. System to life. Build custom decks from hundreds of Marvel heroes and villains, master the "chain" mechanics, and compete in complex duels in this faithful digital card game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-trading-card-game-usa', 'NDS', 'Marvel Trading Card Game (USA)', '2007', 'Card Game', 'Konami', '2', 'Trading Card Game', 'Strategic card-battling with Marvel characters.', 'Win tactical card duels to progress through the story.', 'North American release of the Marvel card battler.', 'Challenge the multiverse in Marvel Trading Card Game (USA). Featuring a deep single-player campaign and robust deck-building options, this title is perfect for fans of TCGs looking for a strategic experience with their favorite comic characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-kings-riding-school-europe-enfrdeesit', 'NDS', 'Mary King''s Riding School (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Raylight Studios', '1', 'Horse Riding Simulation', 'Equestrian simulation with horse care and riding.', 'Train your horse and win prestigious riding events.', 'Realistic horse riding and management simulation.', 'Mary King''s Riding School offers a professional look at equestrianism. Groom your horse, manage the stables, and compete in cross-country, show jumping, and dressage events under the guidance of world champion Mary King.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-all-classics-europe-enfrdeesit', 'NDS', 'Master All Classics (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Telegames', '1', 'Classic Board Games', 'Multi-game collection of classic board and card games.', 'Master a variety of traditional indoor games.', 'Comprehensive collection of classic parlor games.', 'Master All Classics (Europe) is a digital library of entertainment. Play Chess, Checkers, Backgammon, and various card games against the AI or friends. It''s an ideal "all-in-one" title for casual gamers looking for variety on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-jin-jins-iq-challenge-usa', 'NDS', 'Master Jin Jin''s IQ Challenge (USA)', '2007', 'Puzzle', 'Mastiff', '1', 'Logic Puzzle', 'Logic and brain-teasing puzzle collection.', 'Solve a series of diverse IQ tests and puzzles.', 'Challenging mental workout and IQ training.', 'Master Jin Jin''s IQ Challenge features hundreds of puzzles across different categories including math, logic, and observation. Track your mental progress and see if you have what it takes to earn the title of an IQ Master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-of-illusion-usa', 'NDS', 'Master of Illusion (USA)', '2009', 'Puzzle', 'Nintendo', '1', 'Magic Puzzle', 'Interactive magic kit and digital performance tool.', 'Learn and perform magic tricks using the DS hardware.', 'Innovative magic tutorial and performance game.', 'Master of Illusion (USA) provides all the tools you need to become a magician. Learn professional tricks and use the DS as a magical prop to baffle your audience, featuring special cards and interactive digital illusions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('master-of-the-monster-lair-usa', 'NDS', 'Master of the Monster Lair (USA)', '2008', 'Role-Playing Game', 'PixelJunk', '1', 'Dungeon RPG', 'Dungeon-crawling RPG with town-building elements.', 'Design and explore your own dungeons to lure monsters.', 'Unique "Dungeon Maker" and RPG hybrid.', 'Master of the Monster Lair puts you in the role of a dungeon architect. Construct paths and rooms, bait them with items, and defeat the monsters that move in to protect your town in this creative and addictive RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('match-3-madness-europe-enfrdeesitnl', 'NDS', 'Match 3 Madness (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Puzzle', 'EnjoyUp Games', '1', 'Match-3 Puzzle', 'Tile-matching puzzle collection with multiple modes.', 'Clear boards by matching 3 or more identical items.', 'Fast-paced and addictive match-3 puzzle action.', 'Match 3 Madness (Europe) offers a variety of themes and difficulty levels for match-3 fans. With a colorful interface and dozens of levels, it provides the perfect "pick up and play" experience for casual puzzle lovers on the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matching-maker-ds-japan', 'NDS', 'Matching Maker DS (Japan)', '2009', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Social simulation and match-making mini-games.', 'Match couples based on compatibility and personality.', 'Unique Japanese social puzzle and "love" simulation.', 'Matching Maker DS is a quirky title where you act as a cupid. Analyze character profiles, solve mini-games, and try to create the perfect romantic matches to earn points and progress through the various social scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matchstick-usa-enes', 'NDS', 'Matchstick (USA) (En,Es)', '2008', 'Puzzle', 'ZOO Digital', '1', 'Physics Puzzle', 'Logic-based matchstick puzzle collection.', 'Solve classic puzzles by moving or removing matchsticks.', 'Traditional matchstick brain teasers for NDS.', 'Matchstick (USA) brings the age-old matchstick puzzles to the digital era. Move a single stick to correct an equation or create a shape across hundreds of levels that test your spatial reasoning and logic skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matchstick-puzzle-by-ds-europe-enfrdeesit', 'NDS', 'Matchstick Puzzle by DS (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'ZOO Digital', '1', 'Physics Puzzle', 'Logic-based matchstick puzzle collection.', 'Solve classic puzzles by moving or removing matchsticks.', 'European multi-language matchstick puzzle game.', 'Matchstick Puzzle by DS offers a clean, intuitive interface for solving classic riddles. Whether it''s math equations or geometric challenges, this game provides a relaxing but stimulating mental workout for puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('math-blaster-in-the-prime-adventure-usa', 'NDS', 'Math Blaster in the Prime Adventure (USA)', '2009', 'Educational', 'Knowledge Adventure', '1', 'Educational Adventure', 'Educational math adventure with platforming elements.', 'Use math skills to save the Prime Adventure world.', 'Fun and educational math-based adventure game.', 'Math Blaster in the Prime Adventure (USA) combines learning with action. Solve arithmetic problems to overcome obstacles and defeat enemies, making math practice an exciting part of a larger sci-fi journey for young students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('math-play-usa', 'NDS', 'Math Play (USA)', '2007', 'Educational', 'Destineer', '1', 'Math Training', 'Competitive math-based card and puzzle game.', 'Solve math puzzles faster than your opponents to win.', 'Fast-paced educational math competition.', 'Math Play (USA) offers a variety of modes where quick calculation is key. From "Equation" challenges to "Sudoku" style puzzles, it''s designed to improve mental math speed in a fun, competitive environment for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('math-play-usa-rev-1', 'NDS', 'Math Play (USA) (Rev 1)', '2007', 'Educational', 'Destineer', '1', 'Math Training', 'Competitive math-based card and puzzle game.', 'Solve math puzzles faster than your opponents to win.', 'Revised version of the US math competition game.', 'Math Play (Rev 1) includes minor bug fixes and gameplay adjustments from the original release. It remains a top-tier choice for players looking to sharpen their arithmetic skills through engaging and fast-paced digital gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mathe-buddy---5-klasse-europe-frdeit', 'NDS', 'Mathe Buddy - 5. Klasse (Europe) (Fr,De,It)', '2009', 'Educational', 'Tivola', '1', 'Math Training', 'Educational mathematics exercises and lessons.', 'Master the 5th-grade math curriculum through practice.', 'Math learning aid for 5th-grade students.', 'Mathe Buddy: 5. Klasse is a localized European educational tool designed for students. It covers key concepts like fractions, geometry, and basic arithmetic with interactive exercises and progress tracking to make learning math fun and accessible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mathe-buddy---6-klasse-europe-frdeit', 'NDS', 'Mathe Buddy - 6. Klasse (Europe) (Fr,De,It)', '2009', 'Educational', 'Tivola', '1', 'Math Training', 'Educational mathematics exercises and lessons.', 'Master the 6th-grade math curriculum through practice.', 'Math learning aid for 6th-grade students.', 'Mathe Buddy: 6. Klasse offers advanced lessons for 6th graders. This NDS title focuses on complex problem solving and preparing students for higher-level mathematics through a series of structured modules and feedback-driven mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mathematik-1-4-klasse---fit-fuers-gymnasium-germany', 'NDS', 'Mathematik 1.-4. Klasse - Fit fuers Gymnasium (Germany)', '2008', 'Educational', 'Tivola', '1', 'Math Training', 'Comprehensive math training for elementary school.', 'Prepare for the transition to secondary school (Gymnasium).', 'Intensive German math trainer for grades 1-4.', 'Mathematik 1.-4. Klasse provides a solid foundation for young German students. It features curriculum-aligned tasks that ensure children are "Fit fuers Gymnasium," focusing on mental math speed and logic through engaging handheld activities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maths-made-simple-europe-enfrdeesit', 'NDS', 'Maths Made Simple (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Black Lantern Studios', '1', 'Math Training', 'Daily math drills and educational puzzles.', 'Improve mental arithmetic speed and accuracy.', 'Multi-language mental math trainer for all ages.', 'Maths Made Simple (Europe) turns the NDS into a personal tutor. Featuring hundreds of exercises across various difficulty levels, it helps users of all ages sharpen their calculation skills with a clean, touch-driven interface available in five languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maths-play---have-fun-with-numbers!-europe-enfrdeesitnlsvnoda', 'NDS', 'Maths Play - Have Fun with Numbers! (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Educational', 'Destination Software', '1', 'Math Training', 'Math-based mini-games and competitive challenges.', 'Have fun with numbers while solving arithmetic tasks.', 'Engaging math mini-game collection for Europe.', 'Maths Play: Have Fun with Numbers! (Europe) focuses on the playful side of arithmetic. Solve puzzles, complete timed calculations, and enjoy various number-based games designed to build confidence in math while entertaining the player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matsuda-tadanori-onsen-kyouju-kanshuu---zenkoku-dokodemo-onsen-techou-japan', 'NDS', 'Matsuda Tadanori Onsen Kyouju Kanshuu - Zenkoku Dokodemo Onsen Techou (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Travel Guide', 'Digital encyclopedia and lifestyle guide.', 'Locate and learn about the best hot springs (Onsen) in Japan.', 'Comprehensive Japan Onsen guide for NDS.', 'Matsuda Tadanori Onsen Kyouju Kanshuu is a specialized travel tool. Managed by "Professor Onsen," it provides maps, benefits, and descriptions of hot springs across Japan, allowing users to plan their perfect relaxing getaway using their handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mawashite-koron-japan', 'NDS', 'Mawashite Koron (Japan)', '2006', 'Puzzle', 'Success', '1', 'Touch Puzzle', 'Physics-based puzzle game with stage rotation.', 'Roll the ball to the goal by rotating the environment.', 'Japanese version of Cameltry / On the Ball.', 'Mawashite Koron is a fast-paced physics puzzle game. Use the DS stylus or buttons to rotate the entire stage 360 degrees, guiding a marble through complex mazes filled with obstacles and time bonuses in this arcade-style challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mawashite-tsunageru-touch-panic-japan', 'NDS', 'Mawashite Tsunageru Touch Panic (Japan)', '2007', 'Puzzle', 'Success', '1', 'Action Puzzle', 'Action-puzzle game involving sliding tiles and pathfinding.', 'Create a path for the character by sliding blocks.', 'Unique touch-screen path-building puzzle game.', 'Mawashite Tsunageru Touch Panic tasks you with connecting paths for a ball to reach the exit. Rotate and slide panels in real-time to avoid traps and keep the character moving, requiring quick reflexes and spatial planning on the dual screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mawasundaa!!-japan', 'NDS', 'Mawasundaa!! (Japan)', '2008', 'Action', 'Taito', '1', 'Arcade Action', 'Rhythmic action and mini-game collection.', 'Perform actions in sync with the beat and instructions.', 'Quirky Japanese rhythm and rotation game.', 'Mawasundaa!! is a high-energy rhythm title that utilizes the "spinning" motion of the stylus. Complete various odd and funny tasks by rotating wheels or objects on the touch screen in time with the music to earn high scores and unlock new stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mazes-of-fate-ds-europe-enfrdeesit', 'NDS', 'Mazes of Fate DS (Europe) (En,Fr,De,Es,It)', '2008', 'Role-Playing Game', 'Sabarasa', '1', 'Dungeon RPG', 'First-person dungeon crawler RPG with turn-based combat.', 'Explore vast labyrinths to save the world of Termina.', 'Old-school dungeon-crawling RPG for NDS.', 'Mazes of Fate DS (Europe) is a tribute to classic 90s RPGs. Navigate through dangerous dungeons from a first-person perspective, manage a party of adventurers, and engage in tactical combat while uncovering a deep fantasy narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mazes-of-fate-ds-usa', 'NDS', 'Mazes of Fate DS (USA)', '2008', 'Role-Playing Game', 'Sabarasa', '1', 'Dungeon RPG', 'First-person dungeon crawler RPG with turn-based combat.', 'Explore vast labyrinths to save the world of Termina.', 'The North American release of the fantasy dungeon RPG.', 'Adventure through dark caves and ancient ruins in Mazes of Fate DS (USA). With dozens of quests, a deep character customization system, and real-time navigation of 3D-style labyrinths, it offers a substantial challenge for RPG fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mcdonalds-ecdp:-ecrew-development-program', 'NDS', 'McDonald''s eCDP: eCrew Development Program', '2008', 'Educational', 'McDonald''s', '1', 'Corporate Training', 'Corporate training simulation for McDonald''s employees.', 'Learn the standards of food preparation and service.', 'Extremely rare McDonald''s crew development tool.', 'McDonald''s eCDP (eCrew Development Program) is a professional training software used exclusively for staff in Japan. It features interactive lessons on grill station procedures, customer service, and hygiene, making it a unique piece of software history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('me-de-unou-o-kitaeru---ds-sokudoku-junior-japan', 'NDS', 'Me de Unou o Kitaeru - DS Sokudoku Junior (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Speed Reading', 'Speed-reading training for younger users.', 'Improve reading speed and right-brain comprehension.', 'Educational speed-reading trainer for kids.', 'Me de Unou o Kitaeru: DS Sokudoku Junior uses specialized visual exercises to train the eye and brain. Designed for children, it helps improve reading retention and speed through a series of fun, game-like drills on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('me-de-unou-o-kitaeru---ds-sokudoku-jutsu-japan', 'NDS', 'Me de Unou o Kitaeru - DS Sokudoku Jutsu (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Speed Reading', 'Speed-reading training and brain stimulation.', 'Master the art of speed-reading through daily exercises.', 'Advanced speed-reading tool for adults and students.', 'Me de Unou o Kitaeru: DS Sokudoku Jutsu focuses on "Right Brain" activation. By training the eyes to process text faster without losing comprehension, this Japanese title helps users read books and documents in a fraction of the usual time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechanic-master-europe-enfrdeesit', 'NDS', 'Mechanic Master (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Xbow Software', '1', 'Job Simulation', 'Rube Goldberg-style physics puzzle game.', 'Solve challenges using gears, pulleys, and magnets.', 'Creative engineering puzzle game for Europe.', 'Mechanic Master (Europe) challenges your inner inventor. Use the DS stylus to drag and drop mechanical parts to create chain reactions that solve puzzles, featuring a robust physics engine and over 100 levels of increasing difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechanic-master-usa-enfrdeesit', 'NDS', 'Mechanic Master (USA) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Xbow Software', '1', 'Job Simulation', 'Rube Goldberg-style physics puzzle game.', 'Solve challenges using gears, pulleys, and magnets.', 'US release of the mechanical physics puzzle game.', 'Build complex contraptions in Mechanic Master (USA). This title emphasizes "out-of-the-box" thinking, rewarding players for finding creative solutions to move objects or clear the screen using a massive variety of tools and gadgets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechanic-master-2-usa', 'NDS', 'Mechanic Master 2 (USA)', '2010', 'Simulation', 'Xbow Software', '1', 'Job Simulation', 'Expanded physics-based puzzle solving and creation.', 'Use new tools and mechanics to solve complex levels.', 'The feature-rich sequel to Mechanic Master.', 'Mechanic Master 2 (USA) brings more parts, more levels, and a comprehensive level editor. Challenge yourself with gravity-defying puzzles and share your own mechanical masterpieces in this definitive version of the physics-based series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechassault---phantom-war-europe-enfrde', 'NDS', 'MechAssault - Phantom War (Europe) (En,Fr,De)', '2006', 'Action', 'FASA Studio', '4', 'Mech Shooter', '3D action shooter featuring giant mechs.', 'Stop a rebel uprising by piloting a powerful BattleMech.', 'Portable mech combat in the BattleTech universe.', 'MechAssault: Phantom War (Europe) delivers intense 3D action. Pilot massive mechs through destructible environments, use the touch screen to hack consoles and manage systems, and fight for control of the galaxy in this handheld shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mechassault---phantom-war-usa', 'NDS', 'MechAssault - Phantom War (USA)', '2006', 'Action', 'FASA Studio', '4', 'Mech Shooter', '3D action shooter featuring giant mechs.', 'Stop a rebel uprising by piloting a powerful BattleMech.', 'North American release of the MechAssault title.', 'Take the cockpit in MechAssault: Phantom War (USA). Featuring a deep story campaign and wireless multiplayer, this title brings the explosive combat of the BattleTech series to the NDS, allowing you to customize your mech and dominate the battlefield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medarot-ds---kabuto-ver-japan', 'NDS', 'Medarot DS - Kabuto Ver. (Japan)', '2010', 'Role-Playing Game', 'Natsume', '1', 'Japanese RPG', 'Turn-based RPG with customizable robot battling.', 'Become the top Medarotter by winning the World Championship.', 'The "Kabuto" version featuring Metabee.', 'Medarot DS: Kabuto Ver. brings the classic robot-collecting series to 3D. Collect and swap "Medaparts" to customize your robot''s weapons and armor, engaging in strategic 3-on-3 battles in this long-awaited Japanese handheld entry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medarot-ds---kuwagata-ver-japan', 'NDS', 'Medarot DS - Kuwagata Ver. (Japan)', '2010', 'Role-Playing Game', 'Natsume', '1', 'Japanese RPG', 'Turn-based RPG with customizable robot battling.', 'Become the top Medarotter by winning the World Championship.', 'The "Kuwagata" version featuring Rokusho.', 'Medarot DS: Kuwagata Ver. offers a unique set of parts and a different starting partner. This Japanese RPG focuses on tactical depth and collection, allowing players to trade parts with the Kabuto version to complete their ultimate Medarot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meet-the-robinsons-europe-enfrdeesitnl', 'NDS', 'Meet the Robinsons (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Adventure', 'Climax Studios', '1', 'Action Adventure', 'Action-adventure platformer based on the Disney film.', 'Help Lewis save the future from the Bowler Hat Guy.', 'Futuristic adventure based on Meet the Robinsons.', 'Meet the Robinsons (Europe) takes you on a time-traveling journey. Use gadgets like the Disintegrator and the Scanner to solve puzzles and defeat robotic enemies, all while exploring the vibrant world of the Disney animated movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meet-the-robinsons-usa', 'NDS', 'Meet the Robinsons (USA)', '2007', 'Adventure', 'Climax Studios', '1', 'Action Adventure', 'Action-adventure platformer based on the Disney film.', 'Help Lewis save the future from the Bowler Hat Guy.', 'North American release of the Disney movie game.', 'Experience the future in Meet the Robinsons (USA). This DS title features unique mini-games, including the "Protect the Future" arena, and stays faithful to the film''s charm and sci-fi aesthetic through engaging 3D platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-brain-boost-usa', 'NDS', 'Mega Brain Boost (USA)', '2008', 'Educational', 'Majesco', '1', 'Brain Training', 'Brain training and puzzle collection.', 'Stimulate your mind with memory and logic challenges.', 'Massive collection of brain-boosting mini-games.', 'Mega Brain Boost (USA) combines two previous titles into one ultimate mental workout. With hundreds of puzzles designed to improve focus and memory, it provides a comprehensive tool for anyone looking to keep their brain sharp on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-5---double-team-ds-europe-enfrdeesit', 'NDS', 'Mega Man Battle Network 5 - Double Team DS (Europe) (En,Fr,De,Es,It)', '2005', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Tactical card-based RPG with grid combat.', 'Stop Nebula from controlling the internet.', 'The definitive DS version of Battle Network 5.', 'Mega Man Battle Network 5: Double Team DS (Europe) combines both the Team Protoman and Team Colonel versions. Use the dual screens to manage your BattleChips and explore the Cyberworld in this enhanced port of the classic GBA series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-5---double-team-ds-usa', 'NDS', 'Mega Man Battle Network 5 - Double Team DS (USA)', '2005', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Tactical card-based RPG with grid combat.', 'Stop Nebula from controlling the internet.', 'North American release of the Double Team edition.', 'Unleash your inner NetNavi in Mega Man Battle Network 5 (USA). This NDS version features voice acting, a remastered soundtrack, and the ability to switch between characters during missions, making it the most complete version of the story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force---dragon-europe-enfrdeesit', 'NDS', 'Mega Man Star Force - Dragon (Europe) (En,Fr,De,Es,It)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and social bonding.', 'Fight electromagnetic threats and save the digital world.', 'The first Star Force game featuring the Dragon power.', 'Mega Man Star Force: Dragon (Europe) introduces a new generation of hero. Use the "Star Force" to transform and battle on a 3x3 grid, utilizing a deck of Battle Cards and the "BrotherBand" social system to gain power in this sci-fi RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force---dragon-usa', 'NDS', 'Mega Man Star Force - Dragon (USA)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and social bonding.', 'Fight electromagnetic threats and save the digital world.', 'US release of the Dragon version of Star Force.', 'Become the Shooting Star Rockman in Mega Man Star Force: Dragon (USA). This version features exclusive transformations and Battle Cards, focusing on the story of Geo Stelar as he balances high school life with cosmic superhero duties.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force---leo-europe-enfrdeesit', 'NDS', 'Mega Man Star Force - Leo (Europe) (En,Fr,De,Es,It)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and social bonding.', 'Fight electromagnetic threats and save the digital world.', 'The "Leo" version of the Star Force RPG series.', 'Mega Man Star Force: Leo (Europe) features the fire-based Leo transformation. Battle EM-Wave viruses and bosses in a dynamic perspective, collecting cards and building bonds with friends to strengthen your abilities in this multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force---leo-usa', 'NDS', 'Mega Man Star Force - Leo (USA)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and social bonding.', 'Fight electromagnetic threats and save the digital world.', 'North American release of the Leo version.', 'Experience the heat of battle in Mega Man Star Force: Leo (USA). Master the Leo Kingdom''s unique powers and use the DS touch screen to select cards and plan your attacks in this high-tech successor to the Battle Network franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force---pegasus-europe-enfrdeesit', 'NDS', 'Mega Man Star Force - Pegasus (Europe) (En,Fr,De,Es,It)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and social bonding.', 'Fight electromagnetic threats and save the digital world.', 'The "Pegasus" version of the Star Force RPG series.', 'Mega Man Star Force: Pegasus (Europe) offers ice-themed powers and transformations. Explore the wave-world, solve digital mysteries, and compete in card-based battles in this beautifully animated RPG for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force---pegasus-usa', 'NDS', 'Mega Man Star Force - Pegasus (USA)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and social bonding.', 'Fight electromagnetic threats and save the digital world.', 'North American release of the Pegasus version.', 'Take flight in Mega Man Star Force: Pegasus (USA). Connect with other players via the BrotherBand system to share cards and stat boosts, fighting to protect the planet from the FM-ian invasion in this action-packed handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force-2---zerker-x-ninja-europe-enfrdeesit', 'NDS', 'Mega Man Star Force 2 - Zerker x Ninja (Europe) (En,Fr,De,Es,It)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and transformations.', 'Stop the OOPArt threat and choose between Berserk and Ninja forms.', 'Sequel to Star Force with dual transformations.', 'Mega Man Star Force 2: Zerker x Ninja (Europe) expands the wave-world adventure. Explore new continents, master the "Tribes" system to transform into a thunderous Berserker or a swift Ninja, and use the BrotherBand system to boost your stats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force-2---zerker-x-ninja-usa', 'NDS', 'Mega Man Star Force 2 - Zerker x Ninja (USA)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and transformations.', 'Stop the OOPArt threat and choose between Berserk and Ninja forms.', 'North American release of the second Star Force saga.', 'Master the power of ancient civilizations in Mega Man Star Force 2 (USA). This version features the unique Zerker and Ninja transformations, offering a revamped card battle system and deep RPG exploration for NDS fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force-2---zerker-x-saurian-europe-enfrdeesit', 'NDS', 'Mega Man Star Force 2 - Zerker x Saurian (Europe) (En,Fr,De,Es,It)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and transformations.', 'Master the Saurian or Berserk powers to save the world.', 'Alternate version of Star Force 2 with Saurian power.', 'Mega Man Star Force 2: Zerker x Saurian (Europe) gives players access to the fire-breathing Saurian form. Engage in fast-paced 3D battles, collect rare Battle Cards, and navigate a sprawling story involving ancient technology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force-2---zerker-x-saurian-usa', 'NDS', 'Mega Man Star Force 2 - Zerker x Saurian (USA)', '2007', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with card-based combat and transformations.', 'Master the Saurian or Berserk powers to save the world.', 'North American release featuring the Saurian transformation.', 'Choose your tribe in Mega Man Star Force 2: Zerker x Saurian (USA). Battle against rogue EM waves and bosses using the powerful Saurian transformation, while managing your deck of cards for strategic grid-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force-3---black-ace-usa', 'NDS', 'Mega Man Star Force 3 - Black Ace (USA)', '2009', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with high-speed card combat.', 'Control the Noise and save the world from Meteor G.', 'The final chapter of the Star Force trilogy.', 'Mega Man Star Force 3: Black Ace (USA) introduces the "Noise Change" system. Battle viruses in high-definition 3D grids, achieve the ultimate Black Ace transformation, and enjoy the most refined gameplay in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-star-force-3---red-joker-usa', 'NDS', 'Mega Man Star Force 3 - Red Joker (USA)', '2009', 'Role-Playing Game', 'Capcom', '1', 'Action RPG', 'Action-RPG with high-speed card combat.', 'Control the Noise and save the world from Meteor G.', 'The powerhouse counterpart to Black Ace.', 'Mega Man Star Force 3: Red Joker (USA) emphasizes raw power with the Red Joker transformation. Collect over 500 Battle Cards and utilize the new "Noise" mechanics to gain the upper hand in this epic series finale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-collection-europe', 'NDS', 'Mega Man Zero Collection (Europe)', '2010', 'Action', 'Capcom', '1', 'Action Collection', '2D side-scrolling action platformer collection.', 'Experience all four Mega Man Zero adventures in one cart.', 'Definitive collection of the legendary Zero series.', 'Mega Man Zero Collection (Europe) brings the intense GBA classics to the DS. Play through Zero 1-4 with enhanced features like an "Easy Scenario" mode and a gallery of original concept art in this high-octane action bundle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-collection-usa', 'NDS', 'Mega Man Zero Collection (USA)', '2010', 'Action', 'Capcom', '1', 'Action Collection', '2D side-scrolling action platformer collection.', 'Experience all four Mega Man Zero adventures in one cart.', 'North American release of the Zero saga collection.', 'Relive the legend of the red reploid in Mega Man Zero Collection (USA). Featuring flawless 2D action, challenging boss fights, and updated controls, it’s the perfect way for fans to experience the entire series on a single NDS card.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zx---advent-europe-enjafrdeesit', 'NDS', 'Mega Man ZX - Advent (Europe) (En,Ja,Fr,De,Es,It)', '2007', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling Metroidvania with transformations.', 'Harness the "A-Trans" system to mimic fallen bosses.', 'The acclaimed sequel to the original ZX.', 'Mega Man ZX: Advent (Europe) allows you to copy the forms of 8 different bosses. Explore a vast interconnected world, master unique elemental abilities, and enjoy a fully voiced story in this multi-language action-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zx---advent-usa', 'NDS', 'Mega Man ZX - Advent (USA)', '2007', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling Metroidvania with transformations.', 'Harness the "A-Trans" system to mimic fallen bosses.', 'US release of the boss-copying action platformer.', 'Mega Man ZX: Advent (USA) features two playable protagonists and a deep "Biometal" system. Use the DS touch screen to quickly switch between transformations and uncover the truth behind the mysterious Model A in this epic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zx-europe-enjafrdeesit', 'NDS', 'Mega Man ZX (Europe) (En,Ja,Fr,De,Es,It)', '2006', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling Metroidvania with Biometal powers.', 'Protect the world from Mavericks using legendary powers.', 'The first entry in the ZX series for NDS.', 'Mega Man ZX (Europe) blends the classic Mega Man feel with an open-world map. Collect Biometals like Model X and Model Z to gain the powers of legendary heroes in this challenging and visually stunning 2D action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zx-usa', 'NDS', 'Mega Man ZX (USA)', '2006', 'Action', 'Capcom', '1', 'Action Platformer', '2D side-scrolling Metroidvania with Biometal powers.', 'Protect the world from Mavericks using legendary powers.', 'North American debut of the ZX franchise.', 'Step into the future in Mega Man ZX (USA). Use the "Overdrive" system to unleash devastating attacks, solve environmental puzzles, and battle massive mechanical bosses in this deep and rewarding evolution of the Mega Man series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-mindy-europe-frnl', 'NDS', 'Mega Mindy (Europe) (Fr,Nl)', '2009', 'Educational', 'Avanquest', '1', 'Brain Training', 'Adventure and mini-game collection based on the TV show.', 'Help the superheroine Mega Mindy solve local crimes.', 'Belgian/Dutch superhero adventure for children.', 'Mega Mindy (Europe) brings the popular TV character to the handheld. Join Mieke as her alter ego to solve mysteries, complete mini-games, and protect the community in this charming adventure for French and Dutch speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megami-ibunroku---devil-survivor-japan', 'NDS', 'Megami Ibunroku - Devil Survivor (Japan)', '2009', 'Role-Playing Game', 'Atlus', '1', 'Tactical RPG', 'Tactical turn-based RPG with demon recruitment.', 'Survive a locked-down Tokyo and fight off a demon invasion.', 'The dark and strategic debut of the Devil Survivor series.', 'Megami Ibunroku: Devil Survivor (Japan) combines strategy RPG combat with the Shin Megami Tensei universe. Negotiate with demons, manage your team’s skills, and make difficult moral choices that determine the fate of Tokyo in 7 days.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megamind---the-blue-defender-europe-enfrdeesitnlsvda', 'NDS', 'Megamind - The Blue Defender (Europe) (En,Fr,De,Es,It,Nl,Sv,Da)', '2010', 'Action', 'Griptonite Games', '1', 'Action Adventure', '2D action-adventure based on the DreamWorks film.', 'Use Megamind''s gadgets to defeat the Doom Syndicate.', 'Movie tie-in action game featuring the clever villain.', 'Megamind: The Blue Defender (Europe) lets you play as the world''s most brilliant villain turned hero. Use the De-Gun and other wacky inventions to traverse levels and save Metro City in this fun, family-friendly action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-beautyhotel-fuer-tiere-germany-ende', 'NDS', 'Mein Beautyhotel fuer Tiere (Germany) (En,De)', '2009', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Pet simulation with hotel management.', 'Run a luxury beauty hotel for animals and keep them happy.', 'Animal hotel and grooming simulation for Germany.', 'Mein Beautyhotel fuer Tiere tasks you with pampering pets. From grooming and feeding to decorating the guest rooms, ensure every animal has a five-star stay in this relaxing and creative simulation game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-eigener-tierbaby-zoo-europe-enfrdeesit', 'NDS', 'Mein Eigener Tierbaby-Zoo (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Animal care and zoo management simulation.', 'Raise and nurture a variety of adorable baby animals.', 'Zoo simulation focused on baby animal care.', 'Mein Eigener Tierbaby-Zoo (Europe) allows you to manage a sanctuary for infants. Feed, play with, and monitor the health of lion cubs, panda bears, and more to build the most popular baby zoo in this heartwarming multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-franzoesisch-coach---verbessere-dein-franzoesisch-germany', 'NDS', 'Mein Franzoesisch Coach - Verbessere Dein Franzoesisch (Germany)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Improve your French vocabulary and grammar skills.', 'Educational French language coach for German speakers.', 'Mein Franzoesisch Coach provides a structured path to learning French. Featuring speech recognition and thousands of exercises, it helps German speakers master basic to intermediate French in a fun, interactive way on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-koch-coach---gesund-und-lecker-kochen-germany-ndsi-enhanced', 'NDS', 'Mein Koch-Coach - Gesund und Lecker Kochen (Germany) (NDSi Enhanced)', '2009', 'Educational', 'Tivola', '1', 'Cooking Simulation', 'Cooking simulation and nutritional guide.', 'Learn to cook healthy and delicious meals with guidance.', 'Healthy cooking coach with DSi camera features.', 'Mein Koch-Coach (Germany) is more than just a recipe book. It features a healthy eating guide, a grocery list organizer, and interactive cooking tutorials that utilize the NDSi camera for a more immersive culinary experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-traumjob---kinderaerztin-germany', 'NDS', 'Mein Traumjob - Kinderaerztin (Germany)', '2009', 'Simulation', 'Tivola', '1', 'Career Simulation', 'Career simulation in the medical field.', 'Treat young patients and run a successful pediatric clinic.', 'Pediatrician career simulation for younger players.', 'Mein Traumjob: Kinderaerztin allows you to live the dream of being a doctor. Diagnose illnesses, care for infants, and manage your clinic''s equipment to ensure every child gets healthy in this educational German simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-wortschatz-coach---englisch-lernen-germany', 'NDS', 'Mein Wortschatz-Coach - Englisch Lernen (Germany)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Expand your English vocabulary and pronunciation.', 'Educational English language coach for German speakers.', 'Mein Wortschatz-Coach: Englisch focuses on vocabulary building. Through engaging games and tracking systems, it helps users learn new English words and their usage, making it an excellent tool for students and hobbyists alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mein-wortschatz-coach---verbessere-dein-ausdrucksvermoegen-germany-rev-1', 'NDS', 'Mein Wortschatz-Coach - Verbessere Dein Ausdrucksvermoegen (Germany) (Rev 1)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Vocabulary trainer and language improvement.', 'Improve your German expression and linguistic skills.', 'German language and vocabulary enhancement tool.', 'Mein Wortschatz-Coach (Rev 1) helps native speakers refine their German. It features challenging word games and logic puzzles designed to expand your expressive range and correct common grammatical errors in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierarztpraxis---einsatz-auf-dem-land-germany', 'NDS', 'Meine Tierarztpraxis - Einsatz auf dem Land (Germany)', '2008', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Veterinary simulation with an open-world rural theme.', 'Treat animals in the countryside and manage your clinic.', 'Rural veterinary simulation with exploration.', 'Meine Tierarztpraxis: Einsatz auf dem Land puts you in the boots of a country vet. Ride your horse to reach patients, perform surgeries, and expand your clinic to accommodate farm animals and pets in this deep simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierarztpraxis---sos-am-ozean-europe-ende-ndsi-enhanced', 'NDS', 'Meine Tierarztpraxis - SOS am Ozean (Europe) (En,De) (NDSi Enhanced)', '2009', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Veterinary simulation with a focus on marine life.', 'Rescue and treat sea animals in a coastal clinic.', 'Marine vet simulation with DSi enhancement.', 'Meine Tierarztpraxis: SOS am Ozean focuses on aquatic animals like dolphins and seals. Use the DSi camera for specialized tasks and manage a rescue center to protect the local marine ecosystem in this unique German release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierarztpraxis-germany-ende', 'NDS', 'Meine Tierarztpraxis (Germany) (En,De)', '2007', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Veterinary simulation and clinic management.', 'Care for sick pets and build a world-renowned practice.', 'Classic pet vet simulation for German speakers.', 'Meine Tierarztpraxis is the core experience of animal care. Diagnose various ailments using the touch screen, administer medicine, and upgrade your facilities to become the most trusted veterinarian in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierarztpraxis-in-australien-germany', 'NDS', 'Meine Tierarztpraxis in Australien (Germany)', '2009', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Veterinary simulation set in the Australian outback.', 'Rescue and rehabilitate unique Australian wildlife.', 'Exotic vet simulation featuring kangaroos and koalas.', 'Meine Tierarztpraxis in Australien takes the vet genre to the outback. Learn about and treat exotic species like kangaroos, wombats, and koalas while managing a specialized rehabilitation center in this educational and fun title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierpension---tapsige-tierbabys-germany', 'NDS', 'Meine Tierpension - Tapsige Tierbabys (Germany)', '2008', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Pet hotel simulation focusing on infant animals.', 'Run a boarding house for baby animals and kittens.', 'Baby animal nursery and boarding simulation.', 'Meine Tierpension: Tapsige Tierbabys is all about nurturing. Care for the youngest pets while their owners are away, ensuring they are fed, groomed, and happy in this adorable addition to the "Meine Tierpension" series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierpension-germany-ende', 'NDS', 'Meine Tierpension (Germany) (En,De)', '2007', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Pet hotel management and animal care simulation.', 'Manage a successful animal boarding facility.', 'Comprehensive pet hotel simulation for Germany.', 'Meine Tierpension tasks you with looking after various pets. Customize your pension, learn the specific needs of different breeds, and build a reputation for quality care in this engaging and detailed animal management game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierpension-2-germany-ende', 'NDS', 'Meine Tierpension 2 (Germany) (En,De)', '2009', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Expanded pet hotel management simulation.', 'Manage a larger animal facility with more pets and activities.', 'The feature-rich sequel to the pet hotel hit.', 'Meine Tierpension 2 (Germany) offers more breeds, more rooms, and deeper management options. Balance the budget while ensuring every dog, cat, and horse receives the love and attention they deserve in this polished sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierschule-germany-ende', 'NDS', 'Meine Tierschule (Germany) (En,De)', '2008', 'Simulation', 'Tivola', '1', 'Animal Training Simulation', 'Animal training and educational simulation.', 'Train pets and teach them new tricks and behaviors.', 'Pet school and animal training simulation.', 'Meine Tierschule focuses on the education of animals. As a professional trainer, you must work with various pets to improve their obedience and teach them complex tricks for shows, utilizing the DS touch screen for interactive training.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meitantei-conan---kieta-hakase-to-machigai-sagashi-no-tou-japan', 'NDS', 'Meitantei Conan - Kieta Hakase to Machigai Sagashi no Tou (Japan)', '2009', 'Adventure', 'Banpresto', '1', 'Detective Adventure', 'Puzzle and logic game with a detective theme.', 'Solve "spot the difference" puzzles to find the missing doctor.', 'Detective Conan-themed logic and observation game.', 'Meitantei Conan: Kieta Hakase features the "Spot the Difference" mechanic as a core gameplay element. Work through the "Tower of Differences" to uncover clues and solve the mystery of the missing Dr. Agasa in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meitantei-conan---tantei-ryoku-trainer-japan', 'NDS', 'Meitantei Conan - Tantei Ryoku Trainer (Japan)', '2008', 'Educational', 'Banpresto', '1', 'Detective Training', 'Brain training and detective skill exercises.', 'Sharpen your detective intuition through various drills.', 'Detective training mini-games featuring Conan Edogawa.', 'Meitantei Conan: Tantei Ryoku Trainer is a collection of mental exercises designed to test your observation, memory, and logic. Earn a detective rank and prove your wits are as sharp as Conan''s in this engaging brain trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meitantei-conan-&-kindaichi-shounen-no-jikenbo---meguriau-futari-no-meitantei-japan', 'NDS', 'Meitantei Conan & Kindaichi Shounen no Jikenbo - Meguriau Futari no Meitantei (Japan)', '2009', 'Adventure', 'Banpresto', '1', 'Detective Adventure', 'Crossover mystery adventure and visual novel.', 'Solve a massive conspiracy in a joint investigation.', 'Epic crossover between Conan and Kindaichi.', 'Two of Japan''s greatest detectives join forces in Meitantei Conan & Kindaichi Shounen no Jikenbo. Switch between characters to gather clues, solve high-stakes puzzles, and experience a gripping original story in this dream collaboration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mensch-aergere-dich-nicht---das-beliebte-original-europe-enfrde', 'NDS', 'Mensch Aergere Dich Nicht - Das Beliebte Original (Europe) (En,Fr,De)', '2005', 'Board Game', 'Infogrames', '4', 'Classic Board Game', 'Digital board game based on the classic "Ludo" style.', 'Move all your pieces to the home base before your opponents.', 'The popular German board game in digital format.', 'Mensch Aergere Dich Nicht brings the beloved board game to the NDS. Known globally as Ludo or Pachisi, this digital version allows for local multiplayer and AI matches, featuring the original rules and a clean, colorful presentation for the whole family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mensetsu-no-tatsujin---tenshoku-hen-japan', 'NDS', 'Mensetsu no Tatsujin - Tenshoku Hen (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Job Interview Training', 'Job interview simulation and career guidance.', 'Master the art of the job interview to land a new career.', 'Unique Japanese job interview trainer for career changers.', 'Mensetsu no Tatsujin: Tenshoku Hen is a specialized simulator designed for professionals in Japan. Practice answering difficult interview questions, learn proper business etiquette, and improve your self-presentation through interactive, text-based scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meoriga-joajineun-sudoku-10000-mun-korea', 'NDS', 'Meoriga Joajineun Sudoku 10000 Mun (Korea)', '2008', 'Puzzle', 'NEOWIZ', '1', 'Sudoku Puzzle', 'Logic puzzle game with a massive amount of content.', 'Solve over 10,000 Sudoku puzzles of varying difficulty.', 'The ultimate Sudoku collection for Korean players.', 'Meoriga Joajineun Sudoku 10000 Mun is a dream for puzzle lovers. Featuring a clean interface and ten thousand unique grids, this Korean title offers endless hours of mental stimulation, ranging from beginner levels to expert challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mes-amis-disney-france', 'NDS', 'Mes Amis Disney (France)', '2007', 'Adventure', 'Disney Interactive', '1', 'Casual Adventure', 'Virtual pet and social simulation with Disney characters.', 'Interact and bond with famous Disney friends in a magical world.', 'French version of Disney Friends for the NDS.', 'Mes Amis Disney (France) allows younger players to care for and play with Stitch, Dory, Simba, and Winnie the Pooh. Use the touch screen and microphone to communicate with characters and explore iconic Disney environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-beyblade---cyber-pegasis-korea', 'NDS', 'Metal Beyblade - Cyber Pegasis (Korea)', '2010', 'Action', 'Hudson Soft', '2', 'Arena Action', 'Top-down physics-based spinning top battler.', 'Defeat rival Bladers and customize your Beyblade.', 'Korean version of the Cyber Pegasis Beyblade game.', 'Metal Beyblade: Cyber Pegasis (Korea) brings the high-intensity spinning top battles to the dual screen. Customize your Bey with different parts and master special moves to dominate the stadium in this tactical action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-fight-beyblade---baku-shin-susanoo-shuurai!-japan', 'NDS', 'Metal Fight Beyblade - Baku Shin Susanoo Shuurai! (Japan)', '2011', 'Action', 'Hudson Soft', '2', 'Arena Action', 'Action-adventure with real-time Beyblade battling.', 'Stop the threat of Susanoo and win the championship.', 'Japanese Beyblade RPG featuring the Baku Shin arc.', 'Metal Fight Beyblade: Baku Shin Susanoo Shuurai! features a deep story mode where you control Gingka and his friends. Engage in strategic battles, collect rare parts, and customize your Beyblade for ultimate performance in the arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-fight-beyblade---bakutan!-cyber-pegasis-japan', 'NDS', 'Metal Fight Beyblade - Bakutan! Cyber Pegasis (Japan)', '2010', 'Action', 'Hudson Soft', '2', 'Arena Action', 'Action-adventure and stadium battling.', 'Master the Cyber Pegasis Beyblade and win tournaments.', 'The Japanese debut of the Metal Fight series.', 'Metal Fight Beyblade: Bakutan! Cyber Pegasis introduces the 3D stadium combat system. Using a combination of button inputs and timing, players must knock out opponents while managing their Beyblade''s stamina and special attack energy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-fight-beyblade---choujou-kessen!---big-bang-bladers-japan', 'NDS', 'Metal Fight Beyblade - Choujou Kessen! - Big Bang Bladers (Japan)', '2011', 'Action', 'Hudson Soft', '2', 'Arena Action', '3D arena fighter with a large roster of Bladers.', 'Win the Big Bang Bladers tournament through tactical play.', 'Intense arena-based Beyblade battling.', 'Metal Fight Beyblade: Choujou Kessen! features characters from the Big Bang Bladers arc. It offers fast-paced 3D combat with high-quality animations, focusing on the tactical depth of Beyblade customization and special move execution.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-fight-beyblade-japan', 'NDS', 'Metal Fight Beyblade (Japan)', '2009', 'Action', 'Hudson Soft', '2', 'Arena Action', 'Top-down physics-based spinning top battler.', 'Compete in the Metal Fight tournament and upgrade your Bey.', 'The foundational Metal Fight Beyblade game.', 'Metal Fight Beyblade (Japan) offers a faithful recreation of the anime''s competitive spirit. Build your own Beyblade from various metal wheels and tips, and test your skills against the series'' most famous characters in the handheld arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-2---reloaded-english-v10-final', 'NDS', 'Metal Max 2 - Reloaded (English v1.0 Final)', '2011', 'Role-Playing Game', 'Cattle Call', '1', 'Post-Apocalyptic RPG', 'Open-world post-apocalyptic turn-based RPG.', 'Explore the wasteland and hunt down bounties in tanks.', 'Fan-translated English version of the classic RPG remake.', 'Metal Max 2: Reloaded (English v1.0) is a massive remake of the SNES classic. Customize your tanks with heavy weaponry, recruit a diverse party, and explore a non-linear world full of mutants and high-tech secrets in this fan-translated masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-2---reloaded-japan', 'NDS', 'Metal Max 2 - Reloaded (Japan)', '2011', 'Role-Playing Game', 'Cattle Call', '1', 'Post-Apocalyptic RPG', 'Open-world post-apocalyptic turn-based RPG.', 'Explore the wasteland and hunt down bounties in tanks.', 'The original Japanese remake of Metal Max 2.', 'Metal Max 2: Reloaded (Japan) is an expansive RPG featuring deep vehicle customization and a "Hunter" bounty system. This NDS version adds new sub-jobs, improved graphics, and an orchestral soundtrack to the legendary post-apocalyptic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-3-english-v10', 'NDS', 'Metal Max 3 (English v1.0)', '2010', 'Role-Playing Game', 'Cattle Call', '1', 'Post-Apocalyptic RPG', 'Open-world post-apocalyptic turn-based RPG.', 'Discover the hero''s past in a world of tanks and mutants.', 'Fan-translated English version of the third Metal Max.', 'Metal Max 3 (English v1.0) brings the series into the NDS era with a vast world to explore on foot or in tanks. This fan translation allows English speakers to enjoy the deep customization and quirky humor of this cult-classic Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-3-japan', 'NDS', 'Metal Max 3 (Japan)', '2010', 'Role-Playing Game', 'Cattle Call', '1', 'Post-Apocalyptic RPG', 'Open-world post-apocalyptic turn-based RPG.', 'Discover the hero''s past in a world of tanks and mutants.', 'The Japanese original of the acclaimed Metal Max 3.', 'Metal Max 3 (Japan) revitalizes the franchise with a massive campaign and thousands of tank parts to collect. Navigate the dangerous wasteland, defeat "Wanted" outlaws, and enjoy a unique, non-linear RPG experience that values player freedom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-saga---hagane-no-kisetsu-japan', 'NDS', 'Metal Saga - Hagane no Kisetsu (Japan)', '2010', 'Role-Playing Game', 'Cattle Call', '1', 'Post-Apocalyptic RPG', 'Turn-based RPG set in the Metal Max universe.', 'Survive the "Season of Steel" and hunt dangerous outlaws.', 'The first Metal Max spin-off for the Nintendo DS.', 'Metal Saga: Hagane no Kisetsu features the series'' signature tank customization and bounty hunting in a stylish new setting. Explore ruins, build the ultimate combat vehicle, and take down massive mechanical bosses in this tactical turn-based adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slug-7-europe-enfrdeesit', 'NDS', 'Metal Slug 7 (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'SNK Playmore', '2', 'Run and Gun', '2D side-scrolling run-and-gun action.', 'Defeat General Morden and his future-tech army.', 'The seventh main entry in the legendary action series.', 'Metal Slug 7 (Europe) delivers intense, arcade-style shooting. Choose from seven playable characters, including Clark and Ralf from King of Fighters, and utilize massive new "Slugs" to blast through seven challenging levels of 2D carnage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slug-7-japan', 'NDS', 'Metal Slug 7 (Japan)', '2008', 'Action', 'SNK Playmore', '2', 'Run and Gun', '2D side-scrolling run-and-gun action.', 'Defeat General Morden and his future-tech army.', 'Japanese release of the high-octane action game.', 'Metal Slug 7 (Japan) is the first game in the main series developed exclusively for a handheld. It retains the signature hand-drawn pixel art and frantic gameplay, adding a "Combat School" mode with over 200 missions to test your skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slug-7-korea', 'NDS', 'Metal Slug 7 (Korea)', '2008', 'Action', 'SNK Playmore', '2', 'Run and Gun', '2D side-scrolling run-and-gun action.', 'Defeat General Morden and his future-tech army.', 'Korean localized version of the action hit.', 'Experience the explosive fun of Metal Slug 7 (Korea). This version features the same tight controls and chaotic boss fights as the original, allowing Korean fans to enjoy the definitive handheld version of the run-and-gun classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slug-7-usa', 'NDS', 'Metal Slug 7 (USA)', '2008', 'Action', 'SNK Playmore', '2', 'Run and Gun', '2D side-scrolling run-and-gun action.', 'Defeat General Morden and his future-tech army.', 'North American release of the Slug-filled shooter.', 'Metal Slug 7 (USA) brings the arcade experience to the DS. With a huge variety of weapons, including the new Slug Gigant, and multiple difficulty levels, it offers endless replayability for fans of old-school action and intense platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metcha!-taiko-no-tatsujin-ds---7-tsu-no-shima-no-daibouken-japan', 'NDS', 'Metcha! Taiko no Tatsujin DS - 7-tsu no Shima no Daibouken (Japan)', '2009', 'Music', 'Namco Bandai', '4', 'Rhythm Game', 'Rhythmic music game with Japanese drumming.', 'Beat the drums in time with the music to save the islands.', 'First Taiko adventure for DS with a story mode.', 'Metcha! Taiko no Tatsujin DS features Don-chan in an RPG-style quest. Traverse seven islands, battle enemies through drumming mini-games, and enjoy a massive tracklist including anime themes and classical music in this Japanese rhythm hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meteos---disney-magic-europe-enfrdeesit', 'NDS', 'Meteos - Disney Magic (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Q Entertainment', '2', 'Action Puzzle', 'Falling block puzzle game with Disney themes.', 'Launch blocks into the atmosphere using the touch screen.', 'Disney-themed spin-off of the hit puzzle series.', 'Meteos: Disney Magic (Europe) combines the addictive "launching" gameplay of Meteos with beloved Disney characters. Travel through worlds based on Cinderella, Toy Story, and more, using the stylus to match and blast blocks into space.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meteos---disney-magic-japan', 'NDS', 'Meteos - Disney Magic (Japan)', '2007', 'Puzzle', 'Q Entertainment', '2', 'Action Puzzle', 'Falling block puzzle game with Disney themes.', 'Launch blocks into the atmosphere using the touch screen.', 'Japanese release of the Disney-themed puzzle game.', 'Experience the magic in Meteos: Disney Magic (Japan). This version features unique "Special Magic" moves based on Disney films and a vertical screen layout that perfectly suits the NDS, making it an accessible and visually charming puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meteos---disney-magic-usa', 'NDS', 'Meteos - Disney Magic (USA)', '2007', 'Puzzle', 'Q Entertainment', '2', 'Action Puzzle', 'Falling block puzzle game with Disney themes.', 'Launch blocks into the atmosphere using the touch screen.', 'North American release of the Disney Meteos game.', 'Blast off with Mickey and friends in Meteos: Disney Magic (USA). Match blocks horizontally or vertically to launch them into the air, clearing the screen and enjoying classic Disney soundtracks and beautifully animated backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meteos-europe-enfrdeesit', 'NDS', 'Meteos (Europe) (En,Fr,De,Es,It)', '2005', 'Puzzle', 'Q Entertainment', '2', 'Action Puzzle', 'Innovative falling block puzzle game with physics.', 'Launch blocks into space to prevent planets from being crushed.', 'The legendary Q Entertainment puzzle debut for NDS.', 'Meteos (Europe) is a fast-paced, high-stakes puzzle game. Use the stylus to slide blocks and create vertical or horizontal matches that act as rocket engines, propelling the blocks off the screen in this visually and sonically stunning title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meteos-japan', 'NDS', 'Meteos (Japan)', '2005', 'Puzzle', 'Q Entertainment', '2', 'Action Puzzle', 'Innovative falling block puzzle game with physics.', 'Launch blocks into space to prevent planets from being crushed.', 'The original Japanese masterpiece by Masahiro Sakurai.', 'Meteos (Japan) revolutionized the puzzle genre on DS. With unique gravity mechanics for every planet and a deep "Fusion" system to unlock new content, it offers one of the most intense and rewarding puzzle experiences on any handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meteos-usa', 'NDS', 'Meteos (USA)', '2005', 'Puzzle', 'Q Entertainment', '2', 'Action Puzzle', 'Innovative falling block puzzle game with physics.', 'Launch blocks into space to prevent planets from being crushed.', 'North American release of the acclaimed puzzle game.', 'Master the art of the launch in Meteos (USA). This title features multiple game modes including Star Trip and Time Attack, challenging players to react quickly and strategically to the ever-increasing pile of falling "Meteos" blocks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('methode-boscher---la-journee-des-tout-petits-france', 'NDS', 'Methode Boscher - La Journee des Tout Petits (France)', '2008', 'Educational', 'Mindscape', '1', 'Reading Education', 'Educational mini-games for early childhood.', 'Learn basic reading, writing, and math through play.', 'French educational tool based on the Boscher method.', 'Methode Boscher (France) is designed for young children beginning their education. It features interactive lessons in phonics, counting, and logic, providing a gentle and encouraging digital environment for early childhood development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime---hunters-europe-enfrdeesit', 'NDS', 'Metroid Prime - Hunters (Europe) (En,Fr,De,Es,It)', '2006', 'Shooter', 'Nintendo', '4', 'First-Person Shooter', 'First-person shooter with platforming and exploration.', 'Collect Octoliths and defeat rival bounty hunters.', 'The definitive FPS experience on the Nintendo DS.', 'Metroid Prime: Hunters (Europe) brings the Prime series to the handheld with stunning 3D graphics. Control Samus Aran as she explores the Alimbic Cluster, solving puzzles and engaging in intense combat with six deadly rival hunters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime---hunters-europe-enfrdeesit-rev-1', 'NDS', 'Metroid Prime - Hunters (Europe) (En,Fr,De,Es,It) (Rev 1)', '2006', 'Shooter', 'Nintendo', '4', 'First-Person Shooter', 'First-person shooter with platforming and exploration.', 'Collect Octoliths and defeat rival bounty hunters.', 'Revised European edition with minor bug fixes.', 'This Revision 1 of Metroid Prime: Hunters (Europe) offers the same high-octane action with improved stability. Experience the acclaimed single-player campaign or dive into the deep wireless multiplayer mode that defined the DS''s online era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime---hunters-japan', 'NDS', 'Metroid Prime - Hunters (Japan)', '2006', 'Shooter', 'Nintendo', '4', 'First-Person Shooter', 'First-person shooter with platforming and exploration.', 'Collect Octoliths and defeat rival bounty hunters.', 'Japanese release of the Samus FPS adventure.', 'Metroid Prime: Hunters (Japan) features the same precise stylus-based aiming system that mimics PC mouse controls. Battle through ancient ruins and master Samus''s transformations to uncover the "Ultimate Power" in this technical marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime---hunters-korea', 'NDS', 'Metroid Prime - Hunters (Korea)', '2006', 'Shooter', 'Nintendo', '4', 'First-Person Shooter', 'First-person shooter with platforming and exploration.', 'Collect Octoliths and defeat rival bounty hunters.', 'Korean localized version of the Metroid FPS.', 'Join Samus in Metroid Prime: Hunters (Korea). This version allows Korean players to experience the fast-paced, competitive shooting and atmospheric exploration of the Metroid universe, fully optimized for the dual-screen hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime---hunters-usa', 'NDS', 'Metroid Prime - Hunters (USA)', '2006', 'Shooter', 'Nintendo', '4', 'First-Person Shooter', 'First-person shooter with platforming and exploration.', 'Collect Octoliths and defeat rival bounty hunters.', 'North American debut of the premier DS shooter.', 'Metroid Prime: Hunters (USA) is a technical showcase for the NDS. With its unique stylus-aiming mechanics, diverse cast of hunters each with their own special weapons, and massive 3D boss fights, it remains a high point in the handheld''s library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime-pinball-europe-enfrdeesit', 'NDS', 'Metroid Prime Pinball (Europe) (En,Fr,De,Es,It)', '2007', 'Pinball', 'Nintendo', '2', 'Arcade Pinball', 'Pinball simulation with Metroid themes and boss fights.', 'Score high points and collect artifacts to defeat Metroid Prime.', 'Classic pinball action set in the Metroid universe.', 'Metroid Prime Pinball (Europe) uses the DS dual screens to create a massive vertical table. Fight bosses like Meta Ridley, transform into Morph Ball mode, and enjoy high-intensity arcade gameplay with Rumble Pak support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime-pinball-japan', 'NDS', 'Metroid Prime Pinball (Japan)', '2007', 'Pinball', 'Nintendo', '2', 'Arcade Pinball', 'Pinball simulation with Metroid themes and boss fights.', 'Score high points and collect artifacts to defeat Metroid Prime.', 'The Japanese edition of Samus''s pinball adventure.', 'Experience the fusion of pinball and adventure in Metroid Prime Pinball (Japan). Battle space pirates across multiple tables based on Metroid Prime locations, using the touch screen for precise nudges and weapon fire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-prime-pinball-usa', 'NDS', 'Metroid Prime Pinball (USA)', '2007', 'Pinball', 'Nintendo', '2', 'Arcade Pinball', 'Pinball simulation with Metroid themes and boss fights.', 'Score high points and collect artifacts to defeat Metroid Prime.', 'North American release of the Metroid pinball hit.', 'Metroid Prime Pinball (USA) delivers fast-paced action across tables like Phendrana Drifts and Magmoor Caverns. Collect the 12 artifacts to unlock the final battle in this visually stunning arcade-style game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metropolis-crime$-europe-enfrdeesit', 'NDS', 'Metropolis Crime$ (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Ubisoft', '1', 'Action Adventure', 'Point-and-click investigation and mystery solving.', 'Solve complex crimes in a futuristic metropolis.', 'Stylized detective adventure and hidden object game.', 'Metropolis Crime (Europe) puts you in the shoes of an investigator. Use the DS stylus to gather clues, interrogate suspects, and piece together evidence to solve a series of high-stakes murders in a noir-inspired city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase!-100-giri-golf-ds-japan', 'NDS', 'Mezase! 100 Giri Golf DS (Japan)', '2006', 'Sports', 'Nintendo', '1', 'Golf Simulation', 'Golf simulation with touch-screen swing mechanics.', 'Break 100 on the scorecard and improve your golf rank.', 'Realistic and accessible Japanese golf simulation.', 'Mezase! 100 Giri Golf DS focuses on the fundamentals of the game. Practice your swing on detailed courses, manage your clubs, and learn the physics of the green in this focused and rewarding sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase!-koushien-japan', 'NDS', 'Mezase! Koushien (Japan)', '2006', 'Sports', 'Nintendo', '1', 'Baseball Simulation', 'Baseball management and sports simulation.', 'Lead a high school baseball team to victory at Koushien.', 'High school baseball management and RPG.', 'Mezase! Koushien tasks you with scouting, training, and managing a team of aspiring baseball stars. Experience the drama of Japanese high school sports as you aim for the legendary national championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase!-shoujo-manga-ka!!-ciao-manga-school-japan', 'NDS', 'Mezase! Shoujo Manga Ka!! Ciao Manga School (Japan)', '2006', 'Simulation', 'Konami', '1', 'Manga Creation Simulation', 'Creative simulation and manga drawing training.', 'Learn to draw manga and get published in Ciao magazine.', 'Manga artist career sim based on Ciao magazine.', 'Mezase! Shoujo Manga Ka!! teaches you the art of Shoujo manga. Use the stylus to trace lines, apply screentone, and create layouts while following a story about becoming a professional illustrator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase!-zenkoku-taikai!!---lets!-brass!!---brass-band-renshuu-soft-japan', 'NDS', 'Mezase! Zenkoku Taikai!! - Let''s! Brass!! - Brass Band Renshuu Soft (Japan)', '2007', 'Music', 'Nintendo', '1', 'Brass Band Training', 'Rhythm and music simulation for brass instruments.', 'Conduct and play in a professional brass band.', 'Educational and fun brass band music trainer.', 'Mezase! Zenkoku Taikai!! Let''s! Brass!! is a unique rhythm game. Practice various instruments, follow the conductor''s lead, and perform classical and popular pieces to lead your band to the national competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase!!-tsuri-master-ds-japan', 'NDS', 'Mezase!! Tsuri Master DS (Japan)', '2007', 'Sports', 'Nintendo', '1', 'Fishing Simulation', 'Fishing simulation with various locations and gear.', 'Catch the biggest fish and become a Fishing Master.', 'Engaging and realistic Japanese fishing game.', 'Mezase!! Tsuri Master DS offers a wide variety of fish to catch in rivers, lakes, and oceans. Use the touch screen to cast your line and reel in the big one, upgrading your equipment as you progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mi-experto-en-aleman---mejora-tu-vocabulario-aleman-spain', 'NDS', 'Mi Experto en Aleman - Mejora Tu Vocabulario Aleman (Spain)', '2009', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through drills and mini-games.', 'Improve your German vocabulary and grammar.', 'Spanish version of My German Coach.', 'Mi Experto en Alemán (Spain) provides a structured way to learn German. Featuring thousands of words, pronunciation guides, and interactive games, it''s the perfect companion for Spanish speakers starting their language journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mi-experto-en-cocina---comida-saludable-spain-ndsi-enhanced', 'NDS', 'Mi Experto en Cocina - Comida Saludable (Spain) (NDSi Enhanced)', '2009', 'Educational', 'Tivola', '1', 'Cooking Education', 'Cooking simulation and nutrition guide.', 'Learn healthy recipes and manage your daily diet.', 'DSi enhanced healthy cooking and nutrition coach.', 'Mi Experto en Cocina (Spain) offers a digital cookbook focused on health. Use the NDSi camera to track ingredients and follow step-by-step instructions to prepare delicious, balanced meals for your family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mi-experto-en-frances---mejora-tu-vocabulario-frances-spain', 'NDS', 'Mi Experto en Frances - Mejora Tu Vocabulario Frances (Spain)', '2009', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through drills and mini-games.', 'Master French vocabulary and sentence structure.', 'Spanish version of My French Coach.', 'Mi Experto en Francés (Spain) turns learning into a game. Progress through levels of difficulty, take daily tests, and use the built-in dictionary to expand your French skills effectively on your Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mi-experto-en-ingles---mejora-tu-vocabulario-ingles-spain', 'NDS', 'Mi Experto en Ingles - Mejora Tu Vocabulario Ingles (Spain)', '2009', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through drills and mini-games.', 'Improve your English pronunciation and vocabulary.', 'Spanish version of My English Coach.', 'Mi Experto en Inglés (Spain) is a comprehensive tool for learning English. It tracks your progress and adapts to your skill level, offering speech recognition exercises and fun mini-games to keep you motivated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mi-experto-en-vocabulario-spain', 'NDS', 'Mi Experto en Vocabulario (Spain)', '2009', 'Educational', 'Tivola', '1', 'Vocabulary Training', 'Vocabulary trainer and language improvement.', 'Expand your Spanish vocabulary and linguistic range.', 'Spanish language and expression coach.', 'Mi Experto en Vocabulario (Spain) helps native speakers refine their use of the language. Solve word puzzles, learn rare terms, and improve your daily communication through engaging mental exercises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miami-crisis-europe-enfrdeesit', 'NDS', 'Miami Crisis (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Ubisoft', '1', 'Action Adventure', 'Action-adventure with dual protagonists.', 'Stop a major crime wave in the city of Miami.', 'High-stakes detective action and investigation.', 'Miami Crisis (Europe) features two playable characters: a cop and a female investigator. Switch between action-heavy chases and careful crime scene analysis to solve a massive conspiracy in this gritty adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miami-crisis-japan', 'NDS', 'Miami Crisis (Japan)', '2007', 'Action', 'Ubisoft', '1', 'Action Adventure', 'Action-adventure with dual protagonists.', 'Stop a major crime wave in the city of Miami.', 'Japanese release of the Miami Law action game.', 'Known as Miami Law in other regions, Miami Crisis (Japan) delivers cinematic storytelling. Navigate the dangerous streets of Miami, engage in shootouts, and use forensic tools to bring criminals to justice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miami-law-usa-enfres', 'NDS', 'Miami Law (USA) (En,Fr,Es)', '2009', 'Adventure', 'Ubisoft', '1', 'Police Adventure', 'Action-adventure with dual protagonists.', 'Stop a major crime wave in the city of Miami.', 'North American release of the investigative action game.', 'Miami Law (USA) blends fast-paced action with deep investigation. Choose your path through the story, solving puzzles and engaging in high-speed pursuits to dismantle the city''s criminal underworld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miami-nights---singles-in-the-city-europe-enfrdeesitnl', 'NDS', 'Miami Nights - Singles in the City (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Simulation', 'Gameloft', '1', 'Life Simulation', 'Social simulation and life management.', 'Become the most popular and successful socialite in Miami.', 'Glamorous life and dating simulation.', 'Miami Nights: Singles in the City (Europe) lets you live the high life. Customize your avatar, build relationships, and work your way up the social ladder in a vibrant, open-ended virtual Miami.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miami-nights---singles-in-the-city-usa-enfres', 'NDS', 'Miami Nights - Singles in the City (USA) (En,Fr,Es)', '2007', 'Simulation', 'Gameloft', '1', 'Life Simulation', 'Social simulation and life management.', 'Become the most popular and successful socialite in Miami.', 'North American release of the Miami social sim.', 'Create your dream life in Miami Nights (USA). Manage your health, wealth, and social standing while exploring the city, attending parties, and finding the perfect partner in this addictive simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jackson---the-experience-europe-enfrdeesit', 'NDS', 'Michael Jackson - The Experience (Europe) (En,Fr,De,Es,It)', '2010', 'Music', 'Ubisoft', '1', 'Dance Rhythm', 'Rhythm and dance game with Michael Jackson''s hits.', 'Follow the rhythm and perform the King of Pop''s dance moves.', 'The ultimate Michael Jackson tribute rhythm game.', 'Michael Jackson: The Experience (Europe) features the greatest hits like Billie Jean and Beat It. Use the stylus to follow the on-screen prompts and replicate iconic choreography in this high-energy musical title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jackson---the-experience-usa-enfres', 'NDS', 'Michael Jackson - The Experience (USA) (En,Fr,Es)', '2010', 'Music', 'Ubisoft', '1', 'Dance Rhythm', 'Rhythm and dance game with Michael Jackson''s hits.', 'Follow the rhythm and perform the King of Pop''s dance moves.', 'North American release of the MJ rhythm experience.', 'Dance to the legend in Michael Jackson: The Experience (USA). Master the timing of your taps and swipes to earn high scores and unlock classic music videos and MJ memorabilia in this portable celebration of pop music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-v4-europe-enfrdeesit', 'NDS', 'Micro Machines V4 (Europe) (En,Fr,De,Es,It)', '2006', 'Racing', 'Codemasters', '4', 'Arcade Racing', 'Top-down arcade racing with toy cars.', 'Win races across household environments using power-ups.', 'High-speed toy car racing on a miniature scale.', 'Micro Machines V4 (Europe) features dozens of tracks in kitchens, workshops, and gardens. Use wacky weapons to knock rivals off the track and collect hundreds of vehicle models in this classic racing revival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-v4-usa', 'NDS', 'Micro Machines V4 (USA)', '2006', 'Racing', 'Codemasters', '4', 'Arcade Racing', 'Top-down arcade racing with toy cars.', 'Win races across household environments using power-ups.', 'North American release of the miniature racing hit.', 'Small cars, big fun! Micro Machines V4 (USA) brings intense multiplayer-style racing to the DS. Navigate household obstacles and master the unique handling of each vehicle in this fast-paced arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('midnight-mysteries---the-edgar-allan-poe-conspiracy-europe-frnl', 'NDS', 'Midnight Mysteries - The Edgar Allan Poe Conspiracy (Europe) (Fr,Nl)', '2011', 'Hidden Object', 'MumboJumbo', '1', 'Mystery Puzzle', 'Hidden object adventure based on Poe''s stories.', 'Solve the mystery behind the death of Edgar Allan Poe.', 'Atmospheric hidden object mystery for Europe.', 'Midnight Mysteries (Europe) takes you on a supernatural journey. Search for clues within the haunting world of Poe’s literature, solving puzzles and interacting with ghosts to uncover the truth in this dark adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('midnight-play!-pack-europe-enfrdeesit', 'NDS', 'Midnight Play! Pack (Europe) (En,Fr,De,Es,It)', '2009', 'Party', 'Ubisoft', '4', 'Mini-Game Collection', 'Multi-game collection of adult-themed parlor games.', 'Win at Poker, Solitaire, and other casual games.', 'Collection of casual "midnight" themed games.', 'Midnight Play! Pack (Europe) offers a selection of card and board games with a mature visual style. Perfect for quick sessions, it includes several variations of poker and logic puzzles for the casual player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('midnight-play!-pack-usa-enfres', 'NDS', 'Midnight Play! Pack (USA) (En,Fr,Es)', '2009', 'Party', 'Ubisoft', '4', 'Mini-Game Collection', 'Multi-game collection of adult-themed parlor games.', 'Win at Poker, Solitaire, and other casual games.', 'North American release of the casual game pack.', 'Enjoy a variety of popular parlor games in Midnight Play! Pack (USA). Featuring an easy-to-use touch interface, it provides hours of entertainment for fans of classic card games and light gambling simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-&-magic---clash-of-heroes-europe-enfrdeesit', 'NDS', 'Might & Magic - Clash of Heroes (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Ubisoft', '1', 'Tactical Puzzle', 'Puzzle-RPG with tactical grid combat.', 'Lead five heroes to save the world of Ashan.', 'Critically acclaimed strategy and puzzle hybrid.', 'Might & Magic: Clash of Heroes (Europe) features a unique battle system where you match units to attack. Explore a rich fantasy world, level up your army, and solve strategic puzzles in this deep and beautiful RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('might-&-magic---clash-of-heroes-usa-enfres', 'NDS', 'Might & Magic - Clash of Heroes (USA) (En,Fr,Es)', '2009', 'Puzzle', 'Ubisoft', '1', 'Tactical Puzzle', 'Puzzle-RPG with tactical grid combat.', 'Lead five heroes to save the world of Ashan.', 'North American release of the hit strategy RPG.', 'Experience the perfect blend of strategy and puzzles in Clash of Heroes (USA). With an epic story campaign and intense tactical combat, it''s widely considered one of the best RPGs on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('migungui-gunju-korea', 'NDS', 'Migungui Gunju (Korea)', '2009', 'Role-Playing Game', 'Softmax', '1', 'Fantasy RPG', 'Historical simulation and strategy RPG.', 'Build and manage a kingdom in a fantasy world.', 'Korean strategic kingdom-building simulation.', 'Migungui Gunju (Lord of the Labyrinth) offers deep management and tactical combat. Balance your resources, train your troops, and expand your influence across the land in this complex and engaging Korean strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mijn-dierenpension-netherlands-ennl', 'NDS', 'Mijn Dierenpension (Netherlands) (En,Nl)', '2008', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Pet hotel and animal care simulation.', 'Manage a successful animal boarding facility.', 'Dutch version of My Animal Hotel.', 'Mijn Dierenpension (Netherlands) lets you care for dogs, cats, and more. Ensure every pet is happy and healthy to earn money and expand your facilities in this charming and educational simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mijn-dierenpension-2-netherlands-ennl', 'NDS', 'Mijn Dierenpension 2 (Netherlands) (En,Nl)', '2009', 'Simulation', 'Tivola', '1', 'Animal Care Simulation', 'Expanded pet hotel management simulation.', 'Manage a larger animal facility with more pets.', 'Dutch version of My Animal Hotel 2.', 'Expand your business in Mijn Dierenpension 2 (Netherlands). This sequel features more animal breeds and deeper management options, allowing you to become the best pet caretaker in the region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mijn-dierenpraktijk-netherlands-ennl', 'NDS', 'Mijn Dierenpraktijk (Netherlands) (En,Nl)', '2008', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Veterinary simulation and clinic management.', 'Diagnose and treat sick animals in your own clinic.', 'Dutch version of My Vet Practice.', 'Mijn Dierenpraktijk (Netherlands) puts you in the role of a veterinarian. Use the touch screen to perform check-ups, administer medicine, and care for a wide variety of pets in need of help.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mijn-dierenschool-netherlands-ennl', 'NDS', 'Mijn Dierenschool (Netherlands) (En,Nl)', '2008', 'Simulation', 'Tivola', '1', 'Animal Training Simulation', 'Animal training and educational simulation.', 'Train pets and teach them new tricks and behaviors.', 'Dutch version of My Pet School.', 'Mijn Dierenschool (Netherlands) focuses on teaching animals. Work with dogs and other pets to improve their skills and prepare them for shows in this interactive training simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mijn-droomjob---verpleegster-europe-frnl', 'NDS', 'Mijn Droomjob - Verpleegster (Europe) (Fr,Nl)', '2009', 'Simulation', 'Tivola', '1', 'Career Simulation', 'Career simulation in the medical field.', 'Treat patients and perform nursing duties in a hospital.', 'Dutch/French nursing career simulation.', 'Mijn Droomjob: Verpleegster (My Dream Job: Nurse) allows you to experience the life of a nurse. Help patients, manage hospital tasks, and learn about the medical profession through engaging mini-games and scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('military-history---commander---europe-at-war-europe-enfrdeesit', 'NDS', 'Military History - Commander - Europe at War (Europe) (En,Fr,De,Es,It)', '2009', 'Strategy', 'Slitherine', '1', 'Turn-Based Strategy', 'Turn-based grand strategy on a hexagonal map.', 'Lead your nation to victory during World War II in Europe.', 'Deep WWII strategy and military simulation.', 'Military History - Commander: Europe at War (Europe) offers a high-level strategic look at WWII. Manage resources, research new technologies, and command land, sea, and air units across an expansive map of Europe in this tactical multi-language simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('milon-no-hoshizora-shabon---puzzle-kumikyoku-japan', 'NDS', 'Milon no Hoshizora Shabon - Puzzle Kumikyoku (Japan)', '2008', 'Puzzle', 'Jupiter', '1', 'Art Puzzle', 'Action-puzzle game featuring bubbles and matching.', 'Clear the screen by launching bubbles to create matches.', 'Whimsical bubble-popping puzzle starring Milon.', 'Milon no Hoshizora Shabon is a colorful sequel to Milon''s Secret Castle. Use the stylus to aim and shoot bubbles, solving celestial-themed puzzles and enjoying a relaxing "Puzzle Suite" experience with charming Japanese aesthetics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mimi-de-unou-o-kitaeru---ds-chou-nouryoku-japan', 'NDS', 'Mimi de Unou o Kitaeru - DS Chou-nouryoku (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Audio Brain Training', 'Audio-based brain training and memory exercises.', 'Enhance your right-brain capabilities through sound tests.', 'Unique audio-focused brain training tool.', 'Mimi de Unou o Kitaeru uses the DS speakers and microphone to train your "musical ear" and memory. Listen to sequences, identify tones, and complete rhythmic challenges designed to stimulate the brain''s creative hemisphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minagara-oreru-ds-origami-japan', 'NDS', 'Minagara Oreru DS Origami (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Origami Training', 'Interactive tutorial for paper folding art.', 'Follow step-by-step guides to create 3D origami figures.', 'Digital origami guide with video and diagrams.', 'Minagara Oreru DS Origami makes the ancient art of paper folding accessible. Watch 3D animations and follow clear instructions to fold everything from cranes to complex animals, turning your DS into a portable art class.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-quiz---your-brain-coach-europe-enfrdeesit', 'NDS', 'Mind Quiz - Your Brain Coach (Europe) (En,Fr,De,Es,It)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Brain training and cognitive mini-games.', 'Improve your mental age through daily logic and math tests.', 'Scientific brain training supervised by Dr. Kawashima.', 'Mind Quiz: Your Brain Coach (Europe) features exercises developed to stimulate four key brain areas. Track your progress on a daily graph and compete in "Brain Exams" to keep your mind sharp in this multi-language edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-quiz---your-brain-coach-usa-enfrdeesit', 'NDS', 'Mind Quiz - Your Brain Coach (USA) (En,Fr,De,Es,It)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Brain training and cognitive mini-games.', 'Improve your mental age through daily logic and math tests.', 'North American release of the Sega brain coach.', 'Developed by Sega, Mind Quiz: Your Brain Coach (USA) offers a unique perspective on brain health. Featuring a variety of difficulty settings and 49 different exercises, it’s a comprehensive tool for daily mental maintenance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-your-language---apprends-le-francais!-europe-enfrdeesit', 'NDS', 'Mind Your Language - Apprends le Francais! (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Mindscape', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Learn basic French vocabulary and grammar through play.', 'Fun and interactive French language tutor.', 'Mind Your Language - Apprends le Francais! is designed for beginners. Learn through eight mini-games and a dictionary of over 1,000 words, making the acquisition of the French language engaging for students and travelers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-your-language---aprende-espanol!-europe-enfrdeesit', 'NDS', 'Mind Your Language - Aprende Espanol! (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Mindscape', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Master Spanish vocabulary and sentence structure.', 'Fun and interactive Spanish language tutor.', 'Mind Your Language - Aprende Espanol! turns the DS into a language lab. Practice pronunciation, complete grammar puzzles, and build a solid foundation in Spanish using the touch screen and microphone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-your-language---learn-english!-europe-enfrdeesitpt', 'NDS', 'Mind Your Language - Learn English! (Europe) (En,Fr,De,Es,It,Pt)', '2008', 'Educational', 'Mindscape', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Improve your English skills with interactive exercises.', 'Fun and interactive English language tutor.', 'Mind Your Language - Learn English! offers a localized path for European speakers to master English. With various mini-games focused on spelling, verbs, and common phrases, it’s a perfect portable learning tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-your-language---learn-japanese!-europe-enfrdeesit', 'NDS', 'Mind Your Language - Learn Japanese! (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Mindscape', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Learn basic Japanese characters and common phrases.', 'Fun and interactive Japanese language tutor.', 'Mind Your Language - Learn Japanese! introduces players to Hiragana, Katakana, and basic Kanji. Use the stylus to practice writing characters and play mini-games that teach essential vocabulary for navigating Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-your-language---lern-deutsch!-europe-enfrdeesit', 'NDS', 'Mind Your Language - Lern Deutsch! (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Mindscape', '1', 'Language Learning', 'Language learning through mini-games and lessons.', 'Master German vocabulary and grammar through play.', 'Fun and interactive German language tutor.', 'Mind Your Language - Lern Deutsch! helps you build a strong German vocabulary. Through engaging logic puzzles and memory games, it covers essential categories like shopping, travel, and food for the aspiring linguist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-body-soul---blend-it-europe-enfrdeesit', 'NDS', 'Mind. Body. Soul. - Blend-It (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Mindscape', '1', 'Lifestyle Training', 'Puzzle and sorting game focused on healthy habits.', 'Create balanced blends and sort healthy food items.', 'Wellness-focused puzzle and logic game.', 'Mind. Body. Soul. - Blend-It (Europe) focuses on mental relaxation. Solve sorting and matching puzzles that emphasize a balanced lifestyle, featuring a calm aesthetic and intuitive touch-screen controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-body-soul---nutrition-matters-europe-enfrdeesit', 'NDS', 'Mind. Body. Soul. - Nutrition Matters (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Mindscape', '1', 'Nutrition Education', 'Educational nutrition guide and management tool.', 'Learn about food groups and manage a healthy diet.', 'Digital nutrition coach and healthy eating guide.', 'Nutrition Matters helps you understand what goes into your body. Track your daily intake, learn about calories and vitamins, and play educational mini-games designed to encourage a healthier lifestyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mind-body-soul---spellbound-2-europe-enfrdeesit', 'NDS', 'Mind. Body. Soul. - Spellbound 2 (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Mindscape', '1', 'Word Puzzle', 'Word-based puzzle and spelling challenge.', 'Master complex spelling bees and word search puzzles.', 'Challenging word game and vocabulary builder.', 'Spellbound 2 (Europe) tests your linguistic skills with thousands of words. Compete in high-stakes spelling challenges and word-building puzzles across multiple languages to expand your vocabulary and mental speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mindstorm---train-your-brain-europe-enfrdeesit', 'NDS', 'MinDStorm - Train Your Brain (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'O2D', '1', 'Brain Training', 'Brain training and trivia collection.', 'Train your brain with logic, math, and observation tasks.', 'Diverse mental workout and IQ trainer.', 'MinDStorm: Train Your Brain (Europe) offers a wide variety of "storms" or mental challenges. From Sudoku-style grids to rapid-fire arithmetic, it tracks your performance to help you reach your peak mental potential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mindstorm-2-europe-enfrdeesit', 'NDS', 'MinDStorm 2 (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'O2D', '1', 'Brain Training', 'Advanced brain training and logic puzzles.', 'Tackle more difficult mental challenges and tests.', 'The feature-rich sequel to the original MinDStorm.', 'MinDStorm 2 (Europe) expands on the foundation of the first game with more complex puzzles and new categories. It’s designed for players who have mastered the basics and want to push their cognitive limits even further.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minecraft-steve', 'NDS', 'Minecraft Steve', '2011', 'Action', 'Mojang', '1', 'Sandbox Adventure', 'Homebrew/Mod based on sandbox building.', 'Build and explore in a world made of blocks.', 'Fan-made Minecraft-style experience for DS.', 'Minecraft Steve is a community-driven project that brings the core essence of sandbox building to the Nintendo DS hardware, allowing players to mine resources and place blocks in a portable 3D environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-mario-over-mario', 'NDS', 'Mini Mario over Mario', '2007', 'Action', 'Nintendo', '1', 'Action Platformer', 'Homebrew/Mod of Mario vs. Donkey Kong.', 'Guide Mini-Marios through custom levels and hazards.', 'Fan-created expansion for the Mini-Mario series.', 'Mini Mario over Mario is a modification that adds new layouts and challenges to the classic toy-based puzzle series, focusing on intricate level design and pixel-perfect timing for veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-ninjas-europe-enfrdeesitnl', 'NDS', 'Mini Ninjas (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Action', 'IO Interactive', '1', 'Stealth Action', 'Action-adventure with stealth and magic.', 'Lead a group of young ninjas to defeat the Evil Samurai Warlord.', 'Charming ninja adventure with beautiful art.', 'Mini Ninjas (Europe) allows you to switch between Hiro and his friends. Use Kuji magic and specialized ninja skills to transform enemies back into animals in this vibrant and family-friendly 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-ninjas-usa-enfres', 'NDS', 'Mini Ninjas (USA) (En,Fr,Es)', '2009', 'Action', 'IO Interactive', '1', 'Stealth Action', 'Action-adventure with stealth and magic.', 'Lead a group of young ninjas to defeat the Evil Samurai Warlord.', 'North American release of the Mini Ninjas quest.', 'Experience a big adventure with small heroes in Mini Ninjas (USA). Traverse diverse environments from lush forests to snowy mountains, using stealth and combat to restore balance to the natural world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-rc-rally-usa', 'NDS', 'Mini RC Rally (USA)', '2007', 'Racing', 'Popcorn Arcade', '1', 'RC Racing', 'Arcade RC car racing with power-ups.', 'Win races and upgrade your remote-controlled cars.', 'High-speed RC racing simulation for NDS.', 'Mini RC Rally (USA) features fast-paced racing across indoor and outdoor tracks. Master the unique physics of remote-controlled vehicles and use the touch screen to customize your cars for better performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mini-yonku-ds-japan', 'NDS', 'Mini Yonku DS (Japan)', '2006', 'Racing', 'Nintendo', '1', 'Mini 4WD Racing', 'Pocket racer simulation and customization.', 'Build the fastest Mini 4WD car and win regional races.', 'Tamiya Mini 4WD racing based on the toy line.', 'Mini Yonku DS brings the plastic model car craze to the handheld. Spend hours in the garage customizing your chassis, motor, and tires, then watch your creation fly down the high-speed tracks in tactical races.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-atsumare!---quiz-party-japan', 'NDS', 'Minna Atsumare! - Quiz Party (Japan)', '2009', 'Party', 'Nintendo', '4', 'Quiz Party', 'Local multiplayer quiz and trivia game.', 'Compete against friends in a variety of trivia categories.', 'Party-style quiz game for up to 4 players.', 'Minna Atsumare! Quiz Party is designed for social gaming. Using a single cart, friends can join in via Download Play to answer questions about history, science, and pop culture in this competitive Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-asobou---shanghai-ds-2-japan', 'NDS', 'Minna de Asobou - Shanghai DS 2 (Japan)', '2007', 'Puzzle', 'Sunsoft', '2', 'Shanghai Puzzle', 'Classic Mahjong solitaire with multiplayer modes.', 'Clear the board of tiles in a race against time or friends.', 'Enhanced sequel to the popular Shanghai DS.', 'Minna de Asobou - Shanghai DS 2 offers hundreds of new tile layouts and a robust multiplayer mode. Use the touch screen for fast matching and enjoy a variety of visual themes in this definitive version of the classic puzzle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-dokusho-ds---genji-monogatari-+-chottodake-bungaku-japan', 'NDS', 'Minna de Dokusho DS - Genji Monogatari + Chottodake Bungaku (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Reading Education', 'Digital book collection with literary analysis.', 'Read "The Tale of Genji" and other classic literature.', 'Portable library of Japanese literary masterpieces.', 'This entry in the "Minna de Dokusho" series focuses on the legendary Genji Monogatari. It includes full text, summaries, and historical context, making it a valuable tool for students and lovers of classical Japanese prose.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-dokusho-ds---keetai-shousetsu-desuuu-japan', 'NDS', 'Minna de Dokusho DS - Keetai Shousetsu Desuuu (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Reading Education', 'Digital book collection of popular mobile fiction.', 'Read "Keetai Shousetsu" stories on your handheld.', 'Collection of modern Japanese cell phone novels.', 'Minna de Dokusho: Keetai Shousetsu features a selection of popular web and mobile fiction. This digital reader is optimized for vertical reading on the DS, bringing contemporary romance and drama to the screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-dokusho-ds---naruhodo!-tanoshii-seikatsu-no-urawaza-kakushiwaza-japan', 'NDS', 'Minna de Dokusho DS - Naruhodo! Tanoshii Seikatsu no Urawaza Kakushiwaza (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Reading Education', 'Digital library of life hacks and household tips.', 'Learn "Urawaza" tips for a more efficient lifestyle.', 'Encyclopedia of Japanese household hacks and tricks.', 'This digital guide provides thousands of "hacks" for daily life, from cleaning tips to cooking secrets. It''s an interactive reference book designed to make everyday tasks easier through clever, lesser-known techniques.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-dokusho-ds---torimonochou---hanshichi-&-umon-&-ango-&-agojuurou-&-hatamoto-taikutsu-otoko-japan', 'NDS', 'Minna de Dokusho DS - Torimonochou - Hanshichi & Umon & Ango & Agojuurou & Hatamoto Taikutsu Otoko (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Reading Education', 'Digital collection of classic detective and mystery novels.', 'Read historical Japanese detective stories on the go.', 'Anthology of famous Japanese mystery writers.', 'This title features stories from authors like Hanshichi and Umon. It turns the DS into a specialized e-reader for mystery fans, complete with bookmarking features and historical notes on the Meiji and Edo periods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-flash-anzan-ds-japan', 'NDS', 'Minna de Flash Anzan DS (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Mental Arithmetic', 'Mental arithmetic and speed calculation training.', 'Solve flash-based math problems to improve speed.', 'Rapid-fire mental math trainer for all ages.', 'Minna de Flash Anzan DS focuses on "Flash Anzan," a method of mental calculation where numbers appear briefly on screen. It’s designed to improve concentration and calculation speed through repetitive, high-speed practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-jibun-no-setsumeisho---b-gata-a-gata-ab-gata-o-gata-japan', 'NDS', 'Minna de Jibun no Setsumeisho - B-Gata, A-Gata, AB-Gata, O-Gata (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Personality Quiz', 'Personality test and psychological profile collection.', 'Discover your traits based on the "B-Gata" book series.', 'Social personality analysis and blood type trivia.', 'Based on the best-selling "Instruction Manual" books, this title analyzes your personality through a series of questions. Compare your results with friends and learn about the quirks of different blood types in Japanese culture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-taikan-dokusho-ds---choo-kowaai!---gakkou-no-kaidan-japan', 'NDS', 'Minna de Taikan Dokusho DS - Choo Kowaai! - Gakkou no Kaidan (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Horror Reading', 'Interactive digital horror story and reading.', 'Experience "School Ghost Stories" with spooky effects.', 'Atmospheric Japanese horror reading for kids.', 'Minna de Taikan Dokusho: Choo Kowaai! uses sound effects and timed text to create a scary experience. Read through urban legends and school ghost stories that react to your touch in this unique digital anthology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-de-wai-wai---cocoto-kart-japan', 'NDS', 'Minna de Wai Wai - Cocoto Kart (Japan)', '2006', 'Racing', 'Nintendo', '4', 'Arcade Kart Racing', 'Kart racing with the Cocoto cast.', 'Race through colorful tracks and use power-ups to win.', 'Japanese release of the Cocoto Kart racer.', 'Minna de Wai Wai - Cocoto Kart offers fun, Mario Kart-style racing. Choose from a variety of quirky characters and navigate imaginative tracks filled with traps and shortcuts in this accessible arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-conveni-japan', 'NDS', 'Minna no Conveni (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Shop Management', 'Convenience store management simulation.', 'Run a successful "Konbini" and satisfy your customers.', 'Charming retail management and store sim.', 'Minna no Conveni puts you in charge of your own convenience store. Manage stock, set prices, and decorate your shop to attract more customers, all with an adorable art style and intuitive touch controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-doubutsuen-japan', 'NDS', 'Minna no Doubutsuen (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Zoo Management', 'Zoo management and animal care simulation.', 'Build a world-class zoo and care for exotic animals.', 'Accessible zoo management for the Japanese market.', 'Minna no Doubutsuen allows players to design animal habitats and manage the daily operations of a zoo. Learn about different species and keep both your animals and visitors happy to expand your business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-ds-seminar---kanpeki-eitango-ryoku-japan', 'NDS', 'Minna no DS Seminar - Kanpeki Eitango Ryoku (Japan)', '2007', 'Educational', 'Nintendo', '1', 'English Vocabulary Training', 'Educational English vocabulary drills.', 'Master English words through daily testing and repetition.', 'Comprehensive English vocabulary trainer for Japan.', 'Minna no DS Seminar: Kanpeki Eitango Ryoku is a structured language tool. It focuses on perfect English word retention, offering thousands of terms categorized by difficulty, perfect for students preparing for entrance exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-ds-seminar---kanpeki-kanji-ryoku-japan', 'NDS', 'Minna no DS Seminar - Kanpeki Kanji Ryoku (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Kanji Learning', 'Handwriting-based Kanji practice and testing.', 'Achieve perfect Kanji recognition and writing skills.', 'Intensive Kanji training and examination tool.', 'Minna no DS Seminar: Kanpeki Kanji Ryoku uses the DS touch screen to help users master the stroke order and meaning of thousands of Kanji. It includes mock tests to evaluate your level according to official standards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-ds-seminar---kantan-ongaku-ryoku---kiso-kara-hajimeru-gakufu-nyuumon-japan', 'NDS', 'Minna no DS Seminar - Kantan Ongaku Ryoku - Kiso kara Hajimeru Gakufu Nyuumon (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Music Reading Training', 'Music theory and sheet music reading tutorial.', 'Learn the basics of reading and writing musical notation.', 'Beginner''s guide to music theory and sheet music.', 'This entry in the DS Seminar series simplifies music education. Learn to identify notes, rests, and rhythms on a staff through interactive lessons, making it an ideal "entry level" software for aspiring musicians.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-mahjong-ds-japan-rev-1', 'NDS', 'Minna no Mahjong DS (Japan) (Rev 1)', '2006', 'Board Game', 'Nintendo', '4', 'Japanese Mahjong', 'Traditional Mahjong simulation with AI opponents.', 'Win Mahjong matches and improve your player ranking.', 'Accessible and polished Mahjong sim (Rev 1).', 'Minna no Mahjong DS offers a clean interface for the classic four-player game. This Revision 1 ensures balanced AI and smooth gameplay, featuring various rulesets and a comprehensive tutorial for beginners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-oekakiya-san-japan', 'NDS', 'Minna no Oekakiya-san (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Drawing Simulation', 'Drawing and coloring simulation for children.', 'Run a virtual "Drawing Shop" and create art for customers.', 'Creative digital coloring and drawing studio.', 'Minna no Oekakiya-san allows players to use a variety of digital tools to draw and color. Fulfill requests from in-game characters to create specific artworks and build your reputation as a master artist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minna-no-suizokukan-japan', 'NDS', 'Minna no Suizokukan (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Aquarium Management', 'Aquarium management and fish care simulation.', 'Build and maintain a successful public aquarium.', 'Charming aquarium management simulation.', 'Minna no Suizokukan puts you in charge of a marine park. Collect exotic fish, design beautiful tanks, and ensure the health of your aquatic residents to attract visitors and expand your underwater empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mio-coach-di-cucina-il---prepara-cibi-sani-e-gustosi-italy-ndsi-enhanced', 'NDS', 'Mio Coach di Cucina, Il - Prepara Cibi Sani e Gustosi (Italy) (NDSi Enhanced)', '2009', 'Educational', 'Tivola', '1', 'Cooking Education', 'Cooking simulation and nutritional guide.', 'Learn healthy recipes and manage your diet with NDSi features.', 'Italian version of My Healthy Cooking Coach.', 'Il Mio Coach di Cucina is an interactive guide for healthy living. Use the NDSi camera and touch screen to follow step-by-step recipes, manage shopping lists, and track your nutritional goals in Italian.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mio-coach-il---arricchisco-il-mio-inglese-italy', 'NDS', 'Mio Coach, Il - Arricchisco il Mio Inglese (Italy)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through drills and mini-games.', 'Master English vocabulary and sentence structure.', 'Italian version of My English Coach.', 'Il Mio Coach: Arricchisco il Mio Inglese provides a fun way for Italian speakers to learn English. It adapts to your skill level, offering pronunciation tips and vocabulary games to ensure steady linguistic progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mio-coach-il---arricchisco-il-mio-vocabolario-italy', 'NDS', 'Mio Coach, Il - Arricchisco il Mio Vocabolario (Italy)', '2008', 'Educational', 'Tivola', '1', 'Vocabulary Training', 'Vocabulary trainer and language improvement.', 'Expand your Italian vocabulary and linguistic range.', 'Italian language and expression coach.', 'Il Mio Coach: Arricchisco il Mio Vocabolario helps native speakers refine their language. Discover new words, correct common mistakes, and improve your daily communication through engaging mental challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mirakuru!-mimika-ds-japan', 'NDS', 'Mirakuru! Mimika DS (Japan)', '2008', 'Adventure', 'NHK Enterprises', '1', 'Anime Adventure', 'Cooking-themed mini-games based on the anime.', 'Help Mimika cook delicious dishes through various challenges.', 'Educational cooking adventure for young kids.', 'Mirakuru! Mimika DS brings the popular NHK educational show to the handheld. Play through mini-games that teach basic kitchen skills and healthy eating habits alongside the show''s colorful cast of characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miru-chikara-o-jissen-de-kitaeru---ds-medikara-training-japan', 'NDS', 'Miru Chikara o Jissen de Kitaeru - DS Medikara Training (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Vision Training', 'Visual training and eye-coordination exercises.', 'Improve your "Eye Age" through various visual tests.', 'Unique visual ability and reaction trainer.', 'DS Medikara Training features exercises designed to sharpen your focus, peripheral vision, and hand-eye coordination. Track your daily performance and see how your visual processing improves over time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miss-spiders-sunny-patch-friends---harvest-time-hop-and-fly-europe-enfrdeesitnl', 'NDS', 'Miss Spider''s Sunny Patch Friends - Harvest Time Hop and Fly (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Action', 'Black Lantern Studios', '1', 'Platform Adventure', 'Mini-game collection based on the children''s series.', 'Complete various tasks in Sunny Patch to help Miss Spider.', 'Family-friendly adventure for young players.', 'Miss Spider''s Sunny Patch Friends (Europe) features a variety of simple, touch-driven games. Help the bug community with daily chores and exploration in this vibrant and educational title for children.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miss-spiders-sunny-patch-friends---harvest-time-hop-and-fly-usa-enfres', 'NDS', 'Miss Spider''s Sunny Patch Friends - Harvest Time Hop and Fly (USA) (En,Fr,Es)', '2006', 'Action', 'Black Lantern Studios', '1', 'Platform Adventure', 'Mini-game collection based on the children''s series.', 'Complete various tasks in Sunny Patch to help Miss Spider.', 'North American release of the Miss Spider game.', 'Join the bugs of Sunny Patch in Harvest Time Hop and Fly (USA). This title emphasizes problem-solving and simple coordination through a series of colorful mini-games based on the beloved animated show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mission-hurry-up-mario-bros', 'NDS', 'Mission Hurry Up, Mario Bros.', '2007', 'Action', 'Nintendo', '1', 'Action Platformer', 'Platforming action with timed challenges.', 'Complete levels as quickly as possible with Mario and Luigi.', 'Fan-made or rare Mario Bros. speedrun challenge.', 'Mission Hurry Up, Mario Bros. is a fast-paced take on the classic platforming formula. It challenges players to navigate hazardous environments under tight time limits, rewarding efficiency and precision movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mission-runway-usa', 'NDS', 'Mission Runway (USA)', '2009', 'Simulation', 'Interchannel', '1', 'Fashion Simulation', 'Fashion design and catwalk simulation.', 'Create stunning outfits and win fashion competitions.', 'Fashion designer career and runway simulation.', 'Mission Runway allows you to become a top stylist. Design clothing, choose fabrics, and manage your models on the catwalk. Compete in themed challenges and prove your creativity to become a fashion icon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mister-slime-usa-enfres', 'NDS', 'Mister Slime (USA) (En,Fr,Es)', '2009', 'Adventure', 'Namco Bandai', '1', 'Action Adventure', 'Physics-based platforming and puzzle solving.', 'Guide Mister Slime through levels using his elastic limbs.', 'Innovative stylus-driven action-adventure.', 'Mister Slime (USA) features a unique control scheme where you use the stylus to "stretch" and anchor the character''s four arms. Navigate complex environments and defeat enemies using physics-based movements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mitamekara-yomigaeru---otona-no-kikonashi-training-japan', 'NDS', 'Mitamekara Yomigaeru - Otona no Kikonashi Training (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Fashion Training', 'Fashion and lifestyle guide for adults.', 'Learn how to coordinate outfits and improve your style.', '"Mature" fashion coordination and style trainer.', 'Otona no Kikonashi Training acts as a digital personal stylist. Input your preferences and learn the rules of color coordination and formal dress codes to improve your real-world fashion sense.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miteha-ikenai-japan', 'NDS', 'Miteha Ikenai (Japan)', '2009', 'Adventure', 'D3 Publisher', '1', 'Horror Adventure', 'Horror-themed hidden object and "spot the difference" game.', 'Find the "curse" or anomaly in various scary images.', 'Spooky interactive horror image investigation.', 'Miteha Ikenai (Must Not Look) is a unique horror title. Inspect seemingly normal photographs for ghostly anomalies or hidden terrors, using the stylus to "cleanse" the images and uncover the truth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mitsukete!-keroro-gunsou---machigai-sagashi-daisakusen-de-arimasu!-japan', 'NDS', 'Mitsukete! Keroro Gunsou - Machigai Sagashi Daisakusen de Arimasu! (Japan)', '2007', 'Puzzle', 'Bandai Namco', '1', 'Spot the Difference', '"Spot the difference" puzzles based on the Keroro anime.', 'Find all the differences in images to complete the mission.', 'Fun observation game starring Sergeant Keroro.', 'Mitsukete! Keroro Gunsou features the hilarious cast of the anime in a classic puzzle format. Use the dual screens to compare vibrant scenes and find the hidden discrepancies before time runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miyamoto-sansuu-kyoushitsu-no-kyouzai---kashikoku-naru-puzzle-ds-ban-japan', 'NDS', 'Miyamoto Sansuu Kyoushitsu no Kyouzai - Kashikoku Naru Puzzle DS Ban (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Math Puzzle', 'Advanced mathematical puzzles and logic tests.', 'Solve challenging math problems to become "smarter."', 'Math trainer based on the Miyamoto classroom method.', 'This title offers a series of arithmetic and logic puzzles designed by famous teacher Ken Miyamoto. It focuses on building "Number Sense" and critical thinking through engaging, non-traditional math challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mizuiro-blood-japan', 'NDS', 'Mizuiro Blood (Japan)', '2006', 'Action', 'Namco', '1', 'Action Shooter', 'Rhythmic action and bizarre mini-games.', 'Follow the beat and complete strange tasks with Mizuiro.', 'Quirky and dark-humored rhythm game from Namco.', 'Mizuiro Blood is a visually unique title featuring "Uta" (the blue-blooded main character). Complete rhythm-based challenges and odd mini-games filled with surreal humor and vibrant, paper-craft style graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mlb-power-pros-2008-usa', 'NDS', 'MLB Power Pros 2008 (USA)', '2008', 'Sports', 'Konami', '4', 'Baseball Simulation', 'Arcade baseball with caricatured pro players.', 'Win the World Series with stylized MLB superstars.', 'Fun and accessible MLB-licensed baseball sim.', 'MLB Power Pros 2008 (USA) combines deep management options with easy-to-pick-up arcade gameplay. Featuring real MLB rosters and the unique "Success Mode" RPG, it''s a fan-favorite sports title for the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moe-moe-2-ji-taisenryaku-two---yamato-nadeshiko-japan', 'NDS', 'Moe Moe 2-ji Taisen(ryaku) Two - Yamato Nadeshiko (Japan)', '2009', 'Strategy', 'SystemSoft Alpha', '1', 'Tactical Strategy', 'Tactical turn-based strategy with "Moe" anthropomorphism.', 'Lead anthropomorphized WWII vehicles to victory.', 'World War II strategy with a "Moe" anime twist.', 'Moe Moe 2-ji Taisen features warships and tanks reimagined as anime girls. Manage your units in tactical grid battles and enjoy a visual novel-style story set during a reimagined version of the Great War.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moe-sta---moeru-toudai-eigojuku-japan', 'NDS', 'Moe Sta - Moeru Toudai Eigojuku (Japan)', '2008', 'Educational', 'Nintendo', '1', 'English Training', 'English language learning with anime aesthetics.', 'Study for the Tokyo University English entrance exam.', 'High-level English trainer for Japanese students.', 'Moe Sta focuses on rigorous English training, including grammar, vocabulary, and listening. It uses a "Moe" visual style to make the intensive study process more engaging for college aspirants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moero!-nekketsu-rhythm-damashii---osu!-tatakae!-ouendan-2-japan', 'NDS', 'Moero! Nekketsu Rhythm Damashii - Osu! Tatakae! Ouendan 2 (Japan)', '2007', 'Music', 'Nintendo', '4', 'Rhythm Game', 'Rhythmic action and "cheerleading" simulation.', 'Tap and swipe to the beat to cheer people in need.', 'The legendary sequel to the original Ouendan.', 'Moero! Nekketsu Rhythm Damashii is the pinnacle of DS rhythm games. With an incredible soundtrack of J-pop hits and hilarious comic-strip stories, it challenges your timing and endurance in a way only Ouendan can.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moetan-ds-japan', 'NDS', 'Moetan DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational English learning based on the Moetan series.', 'Learn English vocabulary with "Magic Girl" characters.', 'Visual novel-style English vocabulary trainer.', 'Moetan DS uses the popular Moetan characters to teach English. It features voice acting, handwriting recognition, and a variety of quizzes designed to help otakus and students alike master the language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mogitate-tingle-no-barairo-rupee-land-japan', 'NDS', 'Mogitate Tingle no Barairo Rupee Land (Japan)', '2006', 'Role-Playing Game', 'Nintendo', '1', 'Action RPG', 'Rupee-collecting adventure and barter RPG.', 'Collect enough Rupees to reach the legendary Rupee Land.', 'The first Zelda spin-off starring Tingle.', 'Mogitate Tingle no Barairo Rupee Land is a quirky, greedy adventure. Barter with NPCs, hire bodyguards, and explore a strange world where everything—including Tingle''s health—is tied to how many Rupees you have.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mokjjangiyagi---colobockle-station-korea', 'NDS', 'Mokjjangiyagi - Colobockle Station (Korea)', '2008', 'Simulation', 'Sonokong', '1', 'Life Simulation', 'Farming and life simulation (Harvest Moon).', 'Restore the farm and build relationships with townspeople.', 'Korean version of Harvest Moon: DS.', 'Mokjjangiyagi: Colobockle Station brings the classic farming experience to Korea. Grow crops, raise livestock, and find love in the valley, utilizing the DS touch screen for various farm chores and inventory management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mokjjangiyagi---colobockle-station-for-girl-korea', 'NDS', 'Mokjjangiyagi - Colobockle Station for Girl (Korea)', '2008', 'Simulation', 'Sonokong', '1', 'Life Simulation', 'Farming and life simulation with a female protagonist.', 'Restore the farm and find your dream husband.', 'Korean version of Harvest Moon: DS Cute.', 'This version allows Korean players to experience Harvest Moon as a female lead. Customize your character, manage a flourishing farm, and interact with the bachelors of the valley in this deep and relaxing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mokjjangiyagi---neowa-hamkke-jaraneun-seom-korea', 'NDS', 'Mokjjangiyagi - Neowa hamkke Jaraneun Seom (Korea)', '2009', 'Simulation', 'Sonokong', '1', 'Life Simulation', 'Farming simulation set on a mysterious island.', 'Survive and thrive on a deserted island through farming.', 'Korean version of Harvest Moon: Island of Happiness.', 'Mokjjangiyagi: Neowa hamkke Jaraneun Seom takes the farm life to a new setting. Use the touch screen exclusively for movement and farming, building a community from scratch on a remote island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-dentetsu---20-shuunen-japan', 'NDS', 'Momotarou Dentetsu - 20 Shuunen (Japan)', '2008', 'Board Game', 'Hudson Soft', '4', 'Party Board Game', 'Digital board game based on travel and investment.', 'Travel across Japan and become the wealthiest player.', '20th Anniversary edition of the famous board game.', 'Momotarou Dentetsu: 20 Shuunen celebrates two decades of the series. Compete against AI or friends in a race to buy up properties across Japan, utilizing cards to sabotage rivals and boost your own profits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-dentetsu---world-japan', 'NDS', 'Momotarou Dentetsu - World (Japan)', '2010', 'Board Game', 'Hudson Soft', '4', 'Party Board Game', 'Global-scale digital board game and travel sim.', 'Travel the entire world and build a global business empire.', 'The first Momotarou Dentetsu game to feature a world map.', 'Momotarou Dentetsu: World expands the scope of the classic property-trading game. Visit major cities across all continents, learn about global geography, and try to avoid the "God of Poverty" on a world-wide scale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-dentetsu-ds---tokyo-&-japan-japan', 'NDS', 'Momotarou Dentetsu DS - Tokyo & Japan (Japan)', '2007', 'Board Game', 'Hudson Soft', '4', 'Party Board Game', 'Regional-scale digital board game and travel sim.', 'Dominate the property markets of Tokyo and all of Japan.', 'Handheld entry focusing on Japanese geography.', 'Momotarou Dentetsu DS: Tokyo & Japan offers two distinct maps. Players can focus on the high-stakes property market of Tokyo or take on the entire nation in this classic digital board game experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('momotarou-dentetsu-ds---tokyo-&-japan-japan-rev-1', 'NDS', 'Momotarou Dentetsu DS - Tokyo & Japan (Japan) (Rev 1)', '2007', 'Board Game', 'Hudson Soft', '4', 'Party Board Game', 'Regional-scale digital board game and travel sim.', 'Dominate the property markets of Tokyo and all of Japan.', 'Revised version of the Tokyo & Japan edition.', 'This Revision 1 of Momotarou Dentetsu DS includes minor balance tweaks and bug fixes. It remains the definitive way to play this addictive property-trading and travel game on the go in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mon-coach-personnel---jameliore-mon-anglais-france', 'NDS', 'Mon Coach Personnel - J''Ameliore Mon Anglais (France)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through drills and mini-games.', 'Master English vocabulary and sentence structure.', 'French version of My English Coach.', 'Mon Coach Personnel - J''Ameliore Mon Anglais provides a structured path for French speakers to learn English. Use the touch screen and microphone to practice pronunciation and complete vocabulary games adapted to your level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mon-coach-personnel---jameliore-mon-espagnol-france', 'NDS', 'Mon Coach Personnel - J''Ameliore Mon Espagnol (France)', '2008', 'Educational', 'Tivola', '1', 'Language Learning', 'Language learning through drills and mini-games.', 'Improve your Spanish vocabulary and grammar.', 'French version of My Spanish Coach.', 'This educational tool helps French speakers master Spanish. Featuring thousands of words, clear pronunciation guides, and progress tracking, Mon Coach Personnel makes learning a second language engaging and portable.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mon-coach-personnel---jenrichis-mon-vocabulaire-france', 'NDS', 'Mon Coach Personnel - J''Enrichis Mon Vocabulaire (France)', '2008', 'Educational', 'Tivola', '1', 'Vocabulary Training', 'Vocabulary trainer and language improvement.', 'Expand your French vocabulary and linguistic range.', 'French language and expression coach for native speakers.', 'Mon Coach Personnel - J''Enrichis Mon Vocabulaire helps you refine your use of the French language. Solve word puzzles and complete logic challenges designed to improve your daily communication and spelling skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mon-coach-personnel---mes-recettes-plaisir-et-ligne-france-ndsi-enhanced', 'NDS', 'Mon Coach Personnel - Mes Recettes Plaisir et Ligne (France) (NDSi Enhanced)', '2009', 'Educational', 'Tivola', '1', 'Cooking Education', 'Cooking simulation and nutrition guide.', 'Learn healthy recipes and manage your diet with NDSi features.', 'French version of My Healthy Cooking Coach.', 'Mon Coach Personnel - Mes Recettes Plaisir et Ligne is a digital nutrition assistant. It features balanced recipes, shopping list management, and utilizes the NDSi camera to help you maintain a healthy lifestyle while enjoying great food.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mon-premier-bescherelle-france', 'NDS', 'Mon Premier Bescherelle (France)', '2009', 'Educational', 'Hachette', '1', 'Grammar Learning', 'Educational spelling and grammar trainer.', 'Learn the fundamentals of French grammar and conjugation.', 'Junior edition of the famous Bescherelle guide.', 'Mon Premier Bescherelle is designed for students. It simplifies the complex rules of French grammar through interactive exercises and mini-games, making it an essential digital companion for school-aged children in France.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mondai-na-nihongo-japan', 'NDS', 'Mondai na Nihongo (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Language Quiz', 'Language and trivia game based on common errors.', 'Identify and correct "problematic" Japanese phrases.', 'Educational game about correct Japanese usage.', 'Mondai na Nihongo tests your knowledge of proper Japanese. Based on the popular books, it challenges you to spot common linguistic mistakes and learn the correct forms in various social and formal contexts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monmallineun-3-gongjuwa-hamkkehaneun---geurimyeonsang-yeongdaneo-amgibeop-korea', 'NDS', 'Monmallineun 3-gongjuwa Hamkkehaneun - Geurimyeonsang Yeongdaneo Amgibeop (Korea)', '2009', 'Educational', 'Daewon Media', '1', 'English Vocabulary Training', 'Educational vocabulary drills for children.', 'Memorize English words through visual associations.', 'Korean English learning game for kids.', 'This Korean educational title uses the "Visual Association" method to help young girls learn English. Follow three princesses through stories where drawing and matching help anchor new vocabulary in memory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monokuro-boo-&-baby-boo---kururin-boo-japan', 'NDS', 'Monokuro Boo & Baby Boo - Kururin Boo (Japan)', '2008', 'Simulation', 'Bandai Namco', '1', 'Casual Life Simulation', 'Tile-matching puzzle game with cute mascots.', 'Clear the screen of black and white pigs (Boo).', 'Adorable Japanese puzzle game featuring San-X characters.', 'Monokuro Boo & Baby Boo: Kururin Boo is a charming logic game. Rotate and match the stylish black and white pigs from San-X to clear stages, featuring relaxing music and a minimalist aesthetic typical of the brand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-europe-enfrde', 'NDS', 'Monopoly (Europe) (En,Fr,De)', '2009', 'Board Game', 'Electronic Arts', '4', 'Classic Board Game', 'Digital board game and property management.', 'Bankrupt your opponents by buying and trading properties.', 'Classic Monopoly experience for European players.', 'Monopoly (Europe) brings the world''s favorite board game to the DS. Play with up to four people using a single cart, featuring animated tokens, multiple house rules, and an intuitive touch-screen interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa-enfr', 'NDS', 'Monopoly (USA) (En,Fr)', '2009', 'Board Game', 'Electronic Arts', '4', 'Classic Board Game', 'Digital board game and property management.', 'Bankrupt your opponents by buying and trading properties.', 'North American release of the classic board game.', 'Own it all in Monopoly (USA). This version features the traditional Atlantic City board and allows you to compete against smart AI or friends in local wireless play, making property trading fun anywhere you go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-bomber-europe-enfrdeesit', 'NDS', 'Monster Bomber (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Kemco', '4', 'Bomber Action', 'Action-puzzle game involving bubble-popping.', 'Defeat monsters by launching colored orbs to match them.', 'High-energy arcade puzzle game for Europe.', 'Monster Bomber (Europe) challenges your aim and reflexes. Use the stylus to flick orbs at advancing monsters on the top screen, combining traditional "match-3" logic with fast-paced projectile action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-bomber-japan', 'NDS', 'Monster Bomber (Japan)', '2008', 'Action', 'Kemco', '4', 'Bomber Action', 'Action-puzzle game involving bubble-popping.', 'Defeat monsters by launching colored orbs to match them.', 'Japanese release of the monster-themed puzzle game.', 'Known in Japan for its addictive "flick" mechanics, Monster Bomber tasks you with protecting your base. Strategically match colors to trigger explosive chain reactions and defeat massive screen-filling bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-bomber-usa', 'NDS', 'Monster Bomber (USA)', '2008', 'Action', 'Kemco', '4', 'Bomber Action', 'Action-puzzle game involving bubble-popping.', 'Defeat monsters by launching colored orbs to match them.', 'North American release of the arcade puzzle title.', 'Monster Bomber (USA) turns the DS into a monster-blasting machine. Master the physics of your shots to clear waves of creatures across dozens of levels, featuring multiple difficulty modes for puzzle enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-farm-ds-2---yomigaeru!-master-breeder-densetsu-japan', 'NDS', 'Monster Farm DS 2 - Yomigaeru! Master Breeder Densetsu (Japan)', '2008', 'Simulation', 'Tecmo', '1', 'Monster Breeding Simulation', 'Monster raising and battling simulation.', 'Raise the ultimate monster through training and feeding.', 'The second Monster Rancher title for the NDS.', 'Monster Farm DS 2 (Japan) allows you to "create" monsters by drawing on the screen or using voice inputs. Train your creature, manage its diet, and enter tournaments to become a legendary Master Breeder.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-frenzy-usa-enfres', 'NDS', 'Monster Frenzy (USA) (En,Fr,Es)', '2009', 'Action', 'Ubisoft', '1', 'Action Arcade', 'Hidden object and adventure game with a spooky theme.', 'Find hidden monsters and items in haunted locations.', 'Spooky hidden object mystery for North America.', 'Monster Frenzy (USA) sends you on a quest to find elusive creatures. Search through detailed, atmospheric environments using the stylus to uncover clues and solve puzzles in this family-friendly monster hunt.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-high---13-wishes-europe-enfrdeesitnlsvnodafi', 'NDS', 'Monster High - 13 Wishes (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi)', '2013', 'Adventure', 'Little Orbit', '1', 'Casual Adventure', '3D adventure based on the "13 Wishes" movie.', 'Help the ghouls save Monster High from a magical lamp.', 'Magical adventure featuring the Monster High cast.', 'Monster High: 13 Wishes (Europe) takes you inside the magic lamp. Play as your favorite characters like Frankie Stein and Draculaura, using their unique powers to overcome obstacles and restore order to the school.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-high---13-wishes-usa-enfres', 'NDS', 'Monster High - 13 Wishes (USA) (En,Fr,Es)', '2013', 'Adventure', 'Little Orbit', '1', 'Casual Adventure', '3D adventure based on the "13 Wishes" movie.', 'Help the ghouls save Monster High from a magical lamp.', 'North American release of the magical adventure.', 'Journey through 10 different levels in Monster High: 13 Wishes (USA). Combine the ghouls'' skills to solve puzzles and defeat enemies in this stylish action-platformer designed for fans of the popular franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-high---ghoul-spirit-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Monster High - Ghoul Spirit (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2011', 'Adventure', 'Little Orbit', '1', 'Casual Adventure', 'Social simulation and school life adventure.', 'Create your own ghoul and become the most popular student.', 'NDSi enhanced social sim set in Monster High.', 'Monster High: Ghoul Spirit (Europe) lets you enroll as a new student. Customize your look, join clubs, and build relationships with iconic characters while utilizing NDSi camera features for personalized "scary" photos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-high---ghoul-spirit-usa-enfr-ndsi-enhanced', 'NDS', 'Monster High - Ghoul Spirit (USA) (En,Fr) (NDSi Enhanced)', '2011', 'Adventure', 'Little Orbit', '1', 'Casual Adventure', 'Social simulation and school life adventure.', 'Create your own ghoul and become the most popular student.', 'North American release of the Monster High social sim.', 'Experience life as a ghoul in Monster High: Ghoul Spirit (USA). Earn a reputation by completing tasks for teachers and classmates, and participate in "freaky-fab" mini-games to unlock new outfits and accessories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-high---skultimate-roller-maze-europe-enfrdeesitnlsvnodafi', 'NDS', 'Monster High - Skultimate Roller Maze (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi)', '2012', 'Sports', 'Little Orbit', '1', 'Roller Sports', 'Racing and combat on roller skates.', 'Win the Roller Maze championship by outrunning rivals.', 'Fast-paced racing game with Monster High characters.', 'Monster High: Skultimate Roller Maze (Europe) is an arcade racer on wheels. Choose your favorite team of ghouls, navigate trap-filled tracks, and use unique power-ups to cross the finish line first in this high-energy competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-high---skultimate-roller-maze-usa-enfres', 'NDS', 'Monster High - Skultimate Roller Maze (USA) (En,Fr,Es)', '2012', 'Sports', 'Little Orbit', '1', 'Roller Sports', 'Racing and combat on roller skates.', 'Win the Roller Maze championship by outrunning rivals.', 'North American release of the roller racing game.', 'Skateline through the halls of Monster High and beyond in Skultimate Roller Maze (USA). Featuring various difficulty levels and unlockable characters, it''s a "frightfully" fun racing experience for players of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-house-europe', 'NDS', 'Monster House (Europe)', '2006', 'Action', 'Artificial Mind & Movement', '1', 'Action Adventure', 'Top-down action-adventure based on the film.', 'Navigate a haunted house and defeat its mechanical traps.', 'European release of the movie tie-in adventure.', 'Monster House (Europe) tasks three kids with exploring a living, breathing house. Switch between characters to utilize their unique weapons and solve puzzles to stop the house before it eats the neighborhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-house-europe-enfrdeesitsvda', 'NDS', 'Monster House (Europe) (En,Fr,De,Es,It,Sv,Da)', '2006', 'Action', 'Artificial Mind & Movement', '1', 'Action Adventure', 'Top-down action-adventure based on the film.', 'Navigate a haunted house and defeat its mechanical traps.', 'Multi-language European edition of the movie game.', 'This version of Monster House provides a spooky experience in multiple languages. Explore the eerie corridors, fight off "furniture" enemies, and experience the story of the animated film in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-house-japan', 'NDS', 'Monster House (Japan)', '2006', 'Action', 'Artificial Mind & Movement', '1', 'Action Adventure', 'Top-down action-adventure based on the film.', 'Navigate a haunted house and defeat its mechanical traps.', 'Japanese release of the Monster House adventure.', 'Monster House (Japan) brings the atmospheric tension of the movie to the NDS. Use the dual-screen setup to keep track of the house''s layout as you fight to survive its supernatural interior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-house-usa-enfr', 'NDS', 'Monster House (USA) (En,Fr)', '2006', 'Action', 'Artificial Mind & Movement', '1', 'Action Adventure', 'Top-down action-adventure based on the film.', 'Navigate a haunted house and defeat its mechanical traps.', 'North American release of the haunted house game.', 'Battle the house in Monster House (USA). Armed with water guns and clever gadgets, you must explore the dark secrets of Nebbercracker''s home in this action-packed title featuring 3D environments and cinematic cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam---path-of-destruction-europe-enfrdeitnl', 'NDS', 'Monster Jam - Path of Destruction (Europe) (En,Fr,De,It,Nl)', '2008', 'Racing', 'Virtuos', '1', 'Monster Truck Racing', 'Monster truck racing and destruction.', 'Complete challenges and win races to customize your truck.', 'High-octane monster truck action for Europe.', 'Monster Jam: Path of Destruction (Europe) features real trucks like Grave Digger. Engage in stadium races and freestyle events where destruction is encouraged, using the stylus to design your own custom monster machine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam---path-of-destruction-usa', 'NDS', 'Monster Jam - Path of Destruction (USA)', '2008', 'Racing', 'Virtuos', '1', 'Monster Truck Racing', 'Monster truck racing and destruction.', 'Complete challenges and win races to customize your truck.', 'North American release of the monster truck hit.', 'Path of Destruction (USA) lets you live the life of a Monster Jam driver. Experience realistic physics and massive jumps, featuring authentic stadium layouts and a deep customization mode to build the ultimate 12,000-pound beast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam---urban-assault-europe-enfrdeesit', 'NDS', 'Monster Jam - Urban Assault (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'Torus Games', '1', 'Monster Truck Racing', 'Arcade monster truck racing in urban environments.', 'Smash through city streets and win high-speed races.', 'Urban-themed monster truck racing for Europe.', 'Monster Jam: Urban Assault (Europe) takes the trucks out of the stadium. Race through cityscapes and docks, smashing everything in your path to earn points and unlock new vehicles in this chaotic arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam---urban-assault-usa-enfr', 'NDS', 'Monster Jam - Urban Assault (USA) (En,Fr)', '2007', 'Racing', 'Torus Games', '1', 'Monster Truck Racing', 'Arcade monster truck racing in urban environments.', 'Smash through city streets and win high-speed races.', 'North American release of the Urban Assault racer.', 'Destruction goes city-wide in Monster Jam: Urban Assault (USA). Compete in "Devastator" and "Eliminator" modes across 12 different urban tracks, featuring a diverse roster of authentic Monster Jam trucks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam-europe', 'NDS', 'Monster Jam (Europe)', '2007', 'Racing', 'Torus Games', '1', 'Monster Truck Racing', 'Monster truck simulation and arena events.', 'Compete in various stadium events and freestyle heats.', 'The first Monster Jam title for the Nintendo DS.', 'Monster Jam (Europe) delivers the core monster truck experience. Balance your truck during massive air-time, perform stunts, and compete in authentic racing circuits to prove you are the king of the dirt.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam-europe-frdeesit', 'NDS', 'Monster Jam (Europe) (Fr,De,Es,It)', '2007', 'Racing', 'Torus Games', '1', 'Monster Truck Racing', 'Monster truck simulation and arena events.', 'Compete in various stadium events and freestyle heats.', 'Multi-language European release of the first game.', 'This edition of Monster Jam provides localized text for French, German, Spanish, and Italian players. Experience the roar of the engines and the crunch of metal in this portable recreation of the world''s premier monster truck series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam-usa', 'NDS', 'Monster Jam (USA)', '2007', 'Racing', 'Torus Games', '1', 'Monster Truck Racing', 'Monster truck simulation and arena events.', 'Compete in various stadium events and freestyle heats.', 'North American release of the original Monster Jam.', 'Monster Jam (USA) brings the stadium excitement to your pocket. Master the controls of 20 different trucks across multiple tracks and events, focusing on both high-speed racing and acrobatic freestyle performances.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-lab-europe-enfrdeesit', 'NDS', 'Monster Lab (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Eidos Interactive', '1', 'Action Adventure', 'Monster-building RPG with turn-based combat.', 'Create your own monster and defeat the evil Baron.', 'Inventive monster-creation RPG for Europe.', 'Monster Lab (Europe) combines Mad Scientist experimentation with tactical RPG combat. Use the stylus to assemble parts and create thousands of unique monsters to explore the Uncanny Valley and defeat rival mad scientists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-lab-usa-enfrdeesit', 'NDS', 'Monster Lab (USA) (En,Fr,De,Es,It)', '2008', 'Action', 'Eidos Interactive', '1', 'Action Adventure', 'Monster-building RPG with turn-based combat.', 'Create your own monster and defeat the evil Baron.', 'North American release of the monster lab RPG.', 'Build and customize your beast in Monster Lab (USA). Experiment with alchemy and engineering to craft limbs and torsos, then test your creations in turn-based strategic battles across a quirky, stylized world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-mayhem---build-and-battle-usa', 'NDS', 'Monster Mayhem - Build and Battle (USA)', '2009', 'Action', 'Destineer', '2', 'Arena Action', 'Strategy and defense with monster battling.', 'Build a team of monsters to defend your territory.', 'Tower defense and monster battle hybrid.', 'Monster Mayhem: Build and Battle (USA) tasks you with protecting your base from invading waves. Strategically place your monsters and upgrade their abilities to ensure your survival in this action-packed defense title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-puzzle-europe', 'NDS', 'Monster Puzzle (Europe)', '2006', 'Puzzle', 'Take-Two Interactive', '1', 'Logic Puzzle', 'Grid-based matching puzzle game.', 'Clear the screen of colorful monsters by matching tiles.', 'Simple and addictive monster-themed puzzle game.', 'Monster Puzzle (Europe) offers a classic match-3 experience with a spooky twist. Perfect for casual gaming, it features dozens of levels with increasing difficulty and fun monster designs for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-racers-japan', 'NDS', 'Monster Racers (Japan)', '2006', 'Role-Playing Game', 'Kemco', '1', 'Monster RPG', 'Monster-collecting and racing hybrid.', 'Collect monsters and use them to win high-speed races.', 'Japanese racing RPG with monster collection.', 'Monster Racers (Japan) is a unique blend of platforming and racing. Capture wild monsters, train them, and use their special abilities to outrun opponents in various environments to become the ultimate racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-racers-usa-enfres', 'NDS', 'Monster Racers (USA) (En,Fr,Es)', '2006', 'Role-Playing Game', 'Kemco', '1', 'Monster RPG', 'Monster-collecting and racing hybrid.', 'Collect monsters and use them to win high-speed races.', 'North American release of the monster racing RPG.', 'Race to the top in Monster Racers (USA). Build your stable of creatures, each with unique elemental stats, and compete in frenetic 2D side-scrolling races across a vibrant world full of challenges and rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-rancher-ds-usa', 'NDS', 'Monster Rancher DS (USA)', '2008', 'Simulation', 'Tecmo', '1', 'Monster Breeding Simulation', 'Monster raising and turn-based battling.', 'Raise powerful monsters and win world tournaments.', 'North American debut of the Monster Rancher series.', 'Monster Rancher DS (USA) lets you generate monsters by drawing symbols on the screen. Feed, train, and manage your creature’s daily life to prepare for high-stakes arena battles in this deep simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-trucks-ds-europe-enfrde', 'NDS', 'Monster Trucks DS (Europe) (En,Fr,De)', '2007', 'Racing', 'Data Design Interactive', '1', 'Truck Racing', 'Off-road monster truck racing.', 'Win races and upgrade your trucks to dominate the mud.', 'Rough-and-tumble monster truck racer for Europe.', 'Monster Trucks DS (Europe) features intense off-road competition. Navigate muddy tracks, perform stunts, and use the money earned from victories to customize your truck''s engine and tires for better performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-trucks-ds-usa', 'NDS', 'Monster Trucks DS (USA)', '2007', 'Racing', 'Data Design Interactive', '1', 'Truck Racing', 'Off-road monster truck racing.', 'Win races and upgrade your trucks to dominate the mud.', 'North American release of the monster truck racer.', 'Take the wheel in Monster Trucks DS (USA). Experience arcade-style racing with massive jumps and destructible environments as you compete against a roster of aggressive rivals across multiple championship circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monsters-vs-aliens-europe-enfrnlsv', 'NDS', 'Monsters vs Aliens (Europe) (En,Fr,Nl,Sv)', '2009', 'Action', 'Beenox', '1', 'Action Adventure', '2D platforming and action-adventure based on the film.', 'Help the monsters defeat the alien invasion.', 'Movie tie-in adventure featuring Susan and friends.', 'Monsters vs Aliens (Europe) lets you play as B.O.B., Ginormica, and The Missing Link. Use their unique abilities to navigate puzzles and combat alien robots in this fun and faithful adaptation of the DreamWorks movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monsters-vs-aliens-europe-esit', 'NDS', 'Monsters vs Aliens (Europe) (Es,It)', '2009', 'Action', 'Beenox', '1', 'Action Adventure', '2D platforming and action-adventure based on the film.', 'Help the monsters defeat the alien invasion.', 'Spanish/Italian regional release of the movie game.', 'This regional version brings the humor and action of Monsters vs Aliens to Spanish and Italian players. Switch between characters to solve environmental challenges and save Earth from Gallaxhar''s plan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monsters-vs-aliens-germany', 'NDS', 'Monsters vs Aliens (Germany)', '2009', 'Action', 'Beenox', '1', 'Action Adventure', '2D platforming and action-adventure based on the film.', 'Help the monsters defeat the alien invasion.', 'German localized release of the animated movie game.', 'Experience the blockbuster adventure in Monsters vs Aliens (Germany). With fully translated text and gameplay optimized for the NDS, it''s a perfect choice for younger fans of the monstrous heroic team.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monsters-vs-aliens-usa-enfr', 'NDS', 'Monsters vs Aliens (USA) (En,Fr)', '2009', 'Action', 'Beenox', '1', 'Action Adventure', '2D platforming and action-adventure based on the film.', 'Help the monsters defeat the alien invasion.', 'North American release of the movie tie-in.', 'Monster up in Monsters vs Aliens (USA). Featuring several unique gameplay styles for each character, from Ginormica''s skating missions to B.O.B.''s puzzle-platforming, it offers a varied and engaging experience for kids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moomin-dani-no-okurimono-japan', 'NDS', 'Moomin-dani no Okurimono (Japan)', '2005', 'Adventure', 'AlphaDream', '1', 'Storybook Adventure', 'Life simulation and mini-game collection.', 'Explore Moominvalley and interact with its residents.', 'Charming adventure based on the Moomin series.', 'Moomin-dani no Okurimono is a relaxing exploration game. Follow Moomintroll and his friends through seasonal stories, solving gentle puzzles and enjoying the beautiful, storybook-style world of Tove Jansson''s characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moon-europe-enfrdeesit', 'NDS', 'Moon (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Phoenix Games', '1', 'Casual Adventure', 'First-person psychological sci-fi shooter.', 'Uncover the mystery of an abandoned lunar base.', 'Atmospheric FPS with a deep sci-fi narrative.', 'Moon (Europe) is a technical masterpiece for the DS. Experience smooth 60FPS gameplay as you explore the lunar surface and subterranean tunnels, using high-tech gadgets to solve puzzles and fight an alien threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moon-usa', 'NDS', 'Moon (USA)', '2009', 'Adventure', 'Phoenix Games', '1', 'Casual Adventure', 'First-person psychological sci-fi shooter.', 'Uncover the mystery of an abandoned lunar base.', 'North American release of the acclaimed FPS Moon.', 'Dive into the silence of space in Moon (USA). This first-person adventure emphasizes exploration and atmosphere, featuring a gripping story about a hidden conspiracy on the lunar surface that will keep you on edge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moorhuhn---jewel-of-darkness-europe-enfrde', 'NDS', 'Moorhuhn - Jewel of Darkness (Europe) (En,Fr,De)', '2008', 'Action', 'Phenomedia', '1', 'Action Shooter', 'Match-3 puzzle game with a treasure hunt theme.', 'Match jewels to unlock the secrets of the dark ruins.', 'Addictive puzzle game featuring the Moorhuhn cast.', 'Moorhuhn: Jewel of Darkness (Europe) takes the famous chicken on a puzzle adventure. Clear ancient chambers by matching gems in this fast-paced logic title that rewards quick thinking and explosive combos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moorhuhn---star-karts-europe-enfrdeesit', 'NDS', 'Moorhuhn - Star Karts (Europe) (En,Fr,De,Es,It)', '2008', 'Racing', 'Phenomedia', '1', 'Arcade Kart Racing', 'Kart racing with the Moorhuhn characters.', 'Win races across cosmic tracks to become the star racer.', 'Galactic kart racing with quirky chicken characters.', 'Moorhuhn: Star Karts (Europe) brings the frantic fun of kart racing to space. Use power-ups, master the drifts, and outpace your feathered rivals in this colorful and accessible multi-language racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moorhuhn-adventure---the-pharaohs-treasure-europe-enfrdeesit', 'NDS', 'Moorhuhn Adventure - The Pharaoh''s Treasure (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Phenomedia', '1', 'Action Adventure', 'Point-and-click adventure and puzzle solving.', 'Find the lost treasure of the Pharaoh in ancient Egypt.', 'Egyptian-themed adventure starring the Moorhuhn.', 'Moorhuhn Adventure: The Pharaoh''s Treasure sends the iconic chicken on an archeological quest. Solve intricate puzzles and interact with funny characters to uncover a legendary treasure in this charming European title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moorhuhn-ds-europe-enfrdeesitnl', 'NDS', 'Moorhuhn DS (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Action', 'Phenomedia', '1', 'Action Shooter', 'Mini-game collection and shooting gallery.', 'Shoot the chickens and complete various score challenges.', 'The core Moorhuhn experience for Nintendo DS.', 'Moorhuhn DS brings the classic shooting gallery gameplay to the touch screen. Aim and tap to shoot the flying chickens and discover hidden bonuses in this simple yet highly addictive arcade-style collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moorhuhn-jumpn-run---atlantis-europe-enfrdeesit', 'NDS', 'Moorhuhn Jump''n Run - Atlantis (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Phenomedia', '1', 'Platform Action', '2D side-scrolling platformer.', 'Guide Moorhuhn through the underwater city of Atlantis.', 'Platforming adventure set in the sunken city.', 'Moorhuhn Jump''n Run: Atlantis features challenging levels filled with traps and enemies. Collect treasures and navigate complex environments as you help the famous chicken explore the wonders of the deep.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('more-brain-training-from-dr-kawashima---how-old-is-your-brain-europe-enfrdeesitnl', 'NDS', 'More Brain Training from Dr Kawashima - How Old Is Your Brain (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Educational', 'Nintendo', '1', 'Brain Training', 'Brain training and cognitive exercises.', 'Keep your brain young with daily mental challenges.', 'The popular sequel to Dr. Kawashima''s Brain Training.', 'More Brain Training (Europe) features all-new exercises like Rock-Paper-Scissors and Serial Subtraction. Use the touch screen and microphone to lower your "Brain Age" in this multi-language daily trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('more-super-mario-bras', 'NDS', 'More Super Mario Bras.', '2006', 'Action', 'Fan Made', '1', 'Platform Action', '2D platforming hack and custom levels.', 'Complete new and challenging Mario levels.', 'Fan-made modification of New Super Mario Bros.', 'More Super Mario Bras. is a creative romhack that provides veteran players with a higher level of difficulty and redesigned stages, offering a fresh perspective on the classic DS platforming engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('more-super-mario-bras-2', 'NDS', 'More Super Mario Bras. 2', '2007', 'Action', 'Fan Made', '1', 'Platform Action', '2D platforming hack and custom levels.', 'Complete new and challenging Mario levels.', 'The second installment of the fan-made Mario hack.', 'Expanding on the first hack, More Super Mario Bras. 2 adds even more custom assets and complex level designs, pushing the player''s platforming skills to the limit in this unofficial expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('more-super-mario-bros-hack-domain-infusion', 'NDS', 'More Super Mario Bros. Hack Domain Infusion', '2008', 'Action', 'Fan Made', '1', 'Platform Action', '2D platforming hack with experimental features.', 'Explore a "hacked" domain with unique Mario mechanics.', 'Advanced fan-made modification for Mario fans.', 'This "Hack Domain Infusion" version features experimental level design and technical tweaks, offering a unique and often surreal experience for fans of the New Super Mario Bros. homebrew scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('more-touchmaster-europe-enfrdeesit', 'NDS', 'More TouchMaster (Europe) (En,Fr,De,Es,It)', '2008', 'Party', 'Midway', '4', 'Mini-Game Collection', 'Multi-game collection of card and puzzle games.', 'Master dozens of mini-games to earn high scores.', 'The second collection of the popular TouchMaster series.', 'More TouchMaster (Europe) brings another round of addictive arcade titles. From card games like Solitaire to fast-paced puzzle and action games, it''s the perfect "pick-up-and-play" title for short sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mori-no-cafeteria-ds---oshare-na-cafe-recipe-japan', 'NDS', 'Mori no Cafeteria DS - Oshare na Cafe Recipe (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Cafe Management', 'Cooking and cafeteria management simulation.', 'Manage a stylish forest cafe and collect recipes.', 'Charming cafe management and cooking sim.', 'Mori no Cafeteria DS allows you to design your own cafe and serve forest animals. Learn stylish recipes, decorate your shop, and build a relaxing environment in this adorable Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('morinaga-takurou-kanshuu---okane-no-shin-joushiki-ds-training-japan', 'NDS', 'Morinaga Takurou Kanshuu - Okane no Shin Joushiki DS Training (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Financial Training', 'Financial education and management trainer.', 'Learn "new common sense" about money and economics.', 'Educational tool for personal finance and economy.', 'Managed by economist Takurou Morinaga, this title teaches Japanese players about savings, investment, and economic history through interactive quizzes and daily financial drills for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moshimo!-kinen-surunara-japan', 'NDS', 'Moshimo! Kinen Surunara... (Japan)', '2008', 'Adventure', 'D3 Publisher', '1', 'Interactive Story', 'Life simulation and anniversary planning.', 'Plan the perfect celebration for various life events.', 'Unique simulation focused on anniversaries and gifts.', 'Moshimo! Kinen Surunara... is a specialized planner and sim. Learn the etiquette for weddings, birthdays, and holidays in Japan, managing budgets and choosing gifts to create the perfect commemorative event.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moshimo!-saibanin-ni-erabaretara-japan', 'NDS', 'Moshimo! Saibanin ni Erabaretara... (Japan)', '2009', 'Adventure', 'D3 Publisher', '1', 'Legal Simulation', 'Legal simulation and court drama.', 'Serve as a juror and determine the verdict in various cases.', 'Realistic lay judge (Saiban-in) system simulator.', 'Moshimo! Saibanin ni Erabaretara... prepares players for the Japanese jury system. Listen to testimonies, analyze evidence, and deliberate with other jurors to reach a fair verdict in this educational drama.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moto-racer-ds---moto-gp-traffic-super-cross-freestyle-europe-enfrdeesit', 'NDS', 'Moto Racer DS - Moto GP, Traffic, Super Cross, Freestyle (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'Digital Reality', '1', 'Motorcycle Racing', 'Multi-discipline motorcycle racing simulation.', 'Compete in Moto GP, Super Cross, and Freestyle events.', 'Comprehensive motorcycle racing game for Europe.', 'Moto Racer DS offers four distinct racing styles in one package. Master the tight corners of Moto GP or the stunts of Freestyle, featuring a deep career mode and local wireless multiplayer for up to 8 players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mots-croises-france', 'NDS', 'Mots Croises (France)', '2006', 'Puzzle', 'Mindscape', '1', 'Crossword Puzzle', 'Classic crossword puzzles in French.', 'Solve hundreds of crossword grids using the stylus.', 'Portable French crossword collection.', 'Mots Croises provides a clean and intuitive interface for crossword fans. With various difficulty levels and a huge database of words, it''s a great way to improve your French vocabulary and keep your mind sharp.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mots-croises-2-france', 'NDS', 'Mots Croises 2 (France)', '2007', 'Puzzle', 'Mindscape', '1', 'Crossword Puzzle', 'Classic crossword puzzles in French.', 'Solve an expanded collection of crossword grids.', 'The second volume of the French crossword series.', 'Mots Croises 2 (France) adds even more puzzles and improved handwriting recognition. It''s the perfect sequel for word game enthusiasts looking for a portable and challenging mental workout on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motto-hayaku!-seikaku-ni!---kazu-sense-keisanryoku-up-training---suutore-japan', 'NDS', 'Motto Hayaku! Seikaku ni! - Kazu Sense, Keisanryoku Up Training - Suutore (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Math Training', 'Arithmetic drills and mental math training.', 'Improve calculation speed and "number sense" (Kazu Sense).', 'Fast-paced math and calculation trainer for Japan.', 'Motto Hayaku! Seikaku ni! focuses on precision and speed. It offers a series of daily mathematical challenges designed to sharpen the user''s mental arithmetic and logical thinking through repetitive, timed exercises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motto-me-de-unou-o-kitaeru---ds-sokudoku-jutsu-japan', 'NDS', 'Motto Me de Unou o Kitaeru - DS Sokudoku Jutsu (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Speed Reading Training', 'Speed-reading training and brain stimulation.', 'Master advanced speed-reading techniques.', 'Advanced speed-reading and right-brain trainer.', 'Motto Me de Unou o Kitaeru is the sequel to the popular speed-reading tool. It features new methods to increase reading comprehension and visual processing speed, helping users consume information faster and more effectively.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motto-toeic-test-ds-training-japan', 'NDS', 'Motto TOEIC Test DS Training (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Language Test Training', 'Educational English language testing.', 'Prepare for the TOEIC exam with mock tests and drills.', 'Specialized TOEIC test preparation tool for Japan.', 'Motto TOEIC Test DS Training offers a comprehensive curriculum for the Test of English for International Communication. It includes thousands of practice questions, listening exercises, and a vocabulary builder for Japanese professionals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motto!-stitch!-ds---rhythm-de-rakugaki-daisakusen-japan', 'NDS', 'Motto! Stitch! DS - Rhythm de Rakugaki Daisakusen (Japan)', '2009', 'Music', 'Disney Interactive', '1', 'Rhythm Drawing', 'Rhythmic action and drawing mini-games.', 'Follow the rhythm to draw and paint with Stitch.', 'Disney-themed rhythm and creativity game for Japan.', 'Motto! Stitch! DS combines music and art. Use the stylus to follow rhythmic prompts and create "rakugaki" (doodles) while interacting with characters from the popular Lilo & Stitch series in a vibrant Japanese setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motto!-stitch!-ds---rhythm-de-rakugaki-daisakusen-japan-t-en-by-prayashland-v051', 'NDS', 'Motto! Stitch! DS - Rhythm de Rakugaki Daisakusen (Japan) [T-En by PrayashLand v0.5.1]', '2009', 'Music', 'Disney Interactive', '1', 'Rhythm Drawing', 'Rhythmic action and drawing mini-games.', 'Follow the rhythm to draw and paint with Stitch.', 'English fan-translated version of the Stitch rhythm game.', 'Motto! Stitch! DS [T-En] allows English-speaking fans to enjoy this rhythmic adventure. Master the beat-based drawing challenges and follow the charming story of Stitch''s antics in Japan with fully translated menus and dialogue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mouse-ds-europe-enfrdeesit', 'NDS', 'Mouse DS (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Oxygen Studios', '1', 'Platform Adventure', 'Puzzle and logic game with a mouse theme.', 'Guide the mouse through mazes to find the cheese.', 'Casual logic and maze navigation puzzle.', 'Mouse DS (Europe) is a family-friendly puzzle game. Use the touch screen to manipulate environmental elements and clear a path for the hungry mouse, featuring dozens of levels that test your spatial reasoning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moyashimon-ds---tales-of-agriculture-japan', 'NDS', 'Moyashimon DS - Tales of Agriculture (Japan)', '2010', 'Adventure', 'Takara Tomy', '1', 'Life Simulation', 'Life simulation and biology-based RPG.', 'Study and collect microbes while managing a farm.', 'Unique agricultural simulation based on the anime.', 'Moyashimon DS: Tales of Agriculture brings the world of microscopic fungi to life. Interact with cute microbes, manage a fermentation lab, and explore the agricultural university in this quirky and educational Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-bean-europe-enfrdeesitnlptsvnodafi', 'NDS', 'Mr Bean (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da,Fi)', '2007', 'Action', 'Tiger Aspect', '1', 'Action Adventure', 'Adventure and mini-game collection.', 'Help Mr. Bean through a series of comedic mishaps.', 'Humorous mini-game collection based on the TV show.', 'Mr Bean (Europe) captures the slapstick humor of Rowan Atkinson’s character. Complete a variety of wacky tasks and puzzles across diverse locations, using the stylus for interactive physical comedy on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller---drill-spirits-europe', 'NDS', 'Mr. Driller - Drill Spirits (Europe)', '2004', 'Puzzle', 'Namco', '1', 'Arcade Puzzle', 'Fast-paced vertical digging action.', 'Drill deep into the earth while managing oxygen levels.', 'Classic arcade-style digging and puzzle action.', 'Mr. Driller: Drill Spirits (Europe) brings the intense puzzle series to the dual screen. Dig through colored blocks to reach the goal, collect air capsules, and unlock new characters in this addictive high-stakes arcade game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller---drill-spirits-japan', 'NDS', 'Mr. Driller - Drill Spirits (Japan)', '2004', 'Puzzle', 'Namco', '1', 'Arcade Puzzle', 'Fast-paced vertical digging action.', 'Drill deep into the earth while managing oxygen levels.', 'Japanese release of the frantic Driller puzzle game.', 'Experience the original Japanese version of Mr. Driller: Drill Spirits. Featuring competitive multiplayer and several distinct game modes, it challenges your reflexes and planning as you dig through crumbling subterranean layers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller---drill-spirits-usa', 'NDS', 'Mr. Driller - Drill Spirits (USA)', '2004', 'Puzzle', 'Namco', '1', 'Arcade Puzzle', 'Fast-paced vertical digging action.', 'Drill deep into the earth while managing oxygen levels.', 'North American release of the classic digging hit.', 'Dig for your life in Mr. Driller: Drill Spirits (USA). This version utilizes the DS dual screens to show the depth of your descent, offering a pulse-pounding experience where every block you break could lead to victory or a crushing defeat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-incredible---kyouteki-underminer-toujou-japan', 'NDS', 'Mr. Incredible - Kyouteki Underminer Toujou (Japan)', '2006', 'Action', 'Heavy Iron Studios', '1', 'Action Adventure', '2D side-scrolling action-adventure.', 'Defeat the Underminer and save the city as the Incredibles.', 'Action-packed sequel to The Incredibles movie.', 'Mr. Incredible - Kyouteki Underminer Toujou (Japan) allows players to control Mr. Incredible and Frozone. Fight through robot armies and solve environmental puzzles to stop a subterranean threat in this high-energy movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-slime-jr-europe-enfrdeesitnlsvnoda', 'NDS', 'Mr. Slime Jr. (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2006', 'Action', 'Kemco', '1', 'Action Platformer', 'Physics-based platforming and puzzle solving.', 'Stretch and anchor Mr. Slime''s limbs to reach the goal.', 'Innovative stylus-based action-adventure.', 'Mr. Slime Jr. (Europe) features a unique "grab and pull" mechanic. Use the stylus to manipulate the character''s elastic arms, swinging through levels and avoiding hazards in a world governed by fun and stretchy physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-slime-jr-germany', 'NDS', 'Mr. Slime Jr. (Germany)', '2006', 'Action', 'Kemco', '1', 'Action Platformer', 'Physics-based platforming and puzzle solving.', 'Stretch and anchor Mr. Slime''s limbs to reach the goal.', 'German localized edition of the physics platformer.', 'Guide the bouncy protagonist through challenging environments in Mr. Slime Jr. (Germany). Master the unique touch-screen controls to navigate vertical mazes and overcome enemies in this creative handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mtv-fan-attack-europe-enfrdeesit', 'NDS', 'MTV Fan Attack (Europe) (En,Fr,De,Es,It)', '2008', 'Party', 'Harmonix', '4', 'Music Trivia', 'Music trivia and fan-culture mini-games.', 'Prove you are the ultimate fan in various music challenges.', 'MTV-licensed trivia and music fan simulation.', 'MTV Fan Attack (Europe) tests your knowledge of pop culture and music history. Complete mini-games, answer difficult trivia, and manage your "fandom" to climb the ranks of music super-fans in this stylish NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mtv-fan-attack-europe-ennlsvnoda', 'NDS', 'MTV Fan Attack (Europe) (En,Nl,Sv,No,Da)', '2008', 'Party', 'Harmonix', '4', 'Music Trivia', 'Music trivia and fan-culture mini-games.', 'Prove you are the ultimate fan in various music challenges.', 'Northern European/Benelux edition of the MTV game.', 'This regional version of MTV Fan Attack provides localized content for fans in Sweden, Norway, Denmark, and the Netherlands. Show off your music expertise and conquer the leaderboards in this multi-language trivia experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mugen-kouro-japan', 'NDS', 'Mugen Kouro (Japan)', '2009', 'Puzzle', 'Success', '1', 'Maze Puzzle', 'Grand strategy and space-exploration RPG.', 'Command a fleet and explore the galaxy to find the "Flux."', 'Epic sci-fi space opera RPG for the NDS.', 'Mugen Kouro (Infinite Space) is a deep simulation RPG. Customize dozens of starships, manage a massive crew, and engage in tactical fleet battles while uncovering a sprawling narrative that spans years and galaxies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mugen-no-frontier---super-robot-taisen-og-saga-japan', 'NDS', 'Mugen no Frontier - Super Robot Taisen OG Saga (Japan)', '2008', 'Role-Playing Game', 'Monolith Soft', '1', 'Tactical RPG', 'Turn-based tactical RPG crossover.', 'Lead a team of heroes across different dimensions.', 'High-octane RPG crossover from the Super Robot series.', 'Mugen no Frontier: Super Robot Taisen OG Saga features a unique real-time combo battle system. Control Haken Browning and his allies in a world blending sci-fi and fantasy, featuring dynamic animations and fanservice-heavy combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mugen-no-frontier-exceed---super-robot-taisen-og-saga-japan', 'NDS', 'Mugen no Frontier Exceed - Super Robot Taisen OG Saga (Japan)', '2010', 'Role-Playing Game', 'Monolith Soft', '1', 'Tactical RPG', 'Turn-based tactical RPG crossover.', 'Fight through the "Multiverse" and stop a new threat.', 'The expanded and refined sequel to Mugen no Frontier.', 'Mugen no Frontier Exceed offers even more characters, longer combos, and improved graphics. This Japanese RPG is known for its fast-paced, rhythmic combat system and deep crossover story involving multiple legendary franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mummi-og-de-mystiske-hylene-europe-svnodafi', 'NDS', 'Mummi og de Mystiske Hylene (Europe) (Sv,No,Da,Fi)', '2008', 'Adventure', 'Right Stuff', '1', 'Storybook Adventure', 'Educational adventure and mini-games.', 'Explore Moominvalley and solve the mystery of the cries.', 'Scandinavian adventure based on the Moomin series.', 'Mummi og de Mystiske Hylene (Northern Europe) is a charming story-based game for kids. Help Moomintroll and Sniff investigate strange noises in the valley through gentle puzzles and exploration in multiple Nordic languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mummi-og-den-store-hoestfesten-europe-svnodafi', 'NDS', 'Mummi og den Store Hoestfesten (Europe) (Sv,No,Da,Fi)', '2009', 'Adventure', 'Right Stuff', '1', 'Storybook Adventure', 'Educational adventure and mini-game collection.', 'Prepare the valley for the Great Autumn Festival.', 'Seasonal Moomin adventure for Northern Europe.', 'Join the Moomins in their harvest preparations. This title features a variety of mini-games focused on coordination and simple logic, all wrapped in the beautiful and calming art style of the classic Moomin books.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mummy-the---tomb-of-the-dragon-emperor-europe-enfrdeesit', 'NDS', 'Mummy, The - Tomb of the Dragon Emperor (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Amaze Entertainment', '1', 'Action Adventure', '2D side-scrolling action platformer.', 'Find the Dragon Emperor and stop his terracotta army.', 'Action-adventure based on the third Mummy film.', 'The Mummy: Tomb of the Dragon Emperor (Europe) puts you in the shoes of Rick and Alex O''Connell. Use guns, torches, and hand-to-hand combat to fight through ancient Chinese tombs and snowy peaks in this movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mummy-the---tomb-of-the-dragon-emperor-usa-enfrdeesit', 'NDS', 'Mummy, The - Tomb of the Dragon Emperor (USA) (En,Fr,De,Es,It)', '2008', 'Action', 'Amaze Entertainment', '1', 'Action Adventure', '2D side-scrolling action platformer.', 'Find the Dragon Emperor and stop his terracotta army.', 'North American release of the movie action game.', 'Experience the cinematic thrills in The Mummy (USA). Navigate dangerous ruins, solve environmental puzzles, and engage in epic boss battles against the immortal Emperor in this action-packed handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mushi---machi-no-konchuu-monogatari-japan', 'NDS', 'Mushi - Machi no Konchuu Monogatari (Japan)', '2006', 'Simulation', 'Spike', '1', 'Insect Life Simulation', 'Insect collecting and battling simulation.', 'Collect and train urban insects to win battles.', 'Suburban bug-collecting and training game for Japan.', 'Mushi: Machi no Konchuu Monogatari allows players to find various beetles and bugs in a Japanese town setting. Train your insects and compete in "Sumo" style matches, learning about real-life bug behavior along the way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mushishi---ame-furu-sato-japan', 'NDS', 'Mushishi - Ame Furu Sato (Japan)', '2008', 'Adventure', 'Compile Heart', '1', 'Visual Novel Adventure', 'Exploration and supernatural adventure.', 'Help the Mushishi Ginko solve mysterious "Mushi" cases.', 'Atmospheric adventure based on the Mushishi manga.', 'Mushishi: Ame Furu Sato is a visually stunning title that captures the zen-like mood of the series. Travel through rural Japan, gather information about supernatural occurrences, and solve puzzles to heal people affected by the Mushi.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mushroom-men---rise-of-the-fungi-europe-enfrdeesit', 'NDS', 'Mushroom Men - Rise of the Fungi (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Red Fly Studio', '1', 'Action Platformer', '2D action platformer with creative crafting.', 'Lead the Mushroom Men to victory against the warring fungi.', 'Stylized and creative action-platformer.', 'Mushroom Men: Rise of the Fungi (Europe) features a unique perspective on a world of tiny combatants. Use household items to craft weapons and explore a giant-scale world from the viewpoint of a mushroom warrior.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mushroom-men---rise-of-the-fungi-usa-enfrdeesit', 'NDS', 'Mushroom Men - Rise of the Fungi (USA) (En,Fr,De,Es,It)', '2008', 'Action', 'Red Fly Studio', '1', 'Action Platformer', '2D action platformer with creative crafting.', 'Lead the Mushroom Men to victory against the warring fungi.', 'North American release of the Mushroom Men saga.', 'Battle for survival in Mushroom Men (USA). Choose your character class, scavenge for parts to build powerful weapons, and fight through diverse environments in this imaginative prequel to the Wii version of the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('music---music-for-everyone-europe-enfrdeesit', 'NDS', 'Music - Music for Everyone (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Tivola', '1', 'Music Education', 'Music creation and digital instrument tool.', 'Compose original music using a variety of digital tools.', 'Accessible music composition software for the NDS.', 'Music for Everyone (Europe) turns the handheld into a studio. It features easy-to-use interfaces for creating melodies and rhythms, designed for beginners who want to explore the basics of songwriting without complex equipment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('music-monstars---the-ultimate-music-machine-europe-enfrdeesit', 'NDS', 'Music Monstars - The Ultimate Music Machine (Europe) (En,Fr,De,Es,It)', '2009', 'Music', 'Destination Software', '1', 'Music Creation', 'Rhythm action and band management.', 'Form a band and rise to the top of the music charts.', 'Rhythmic adventure and pop-star simulation.', 'Music Monstars: The Ultimate Music Machine (Europe) combines touch-screen rhythm gameplay with career management. Choose your instruments, customize your band''s look, and perform hits to win over the crowd in this musical quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('music-star---i-wanna-be-a-popstar-europe-enfrdeesitnl', 'NDS', 'Music Star - I Wanna Be a Popstar (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Music', 'Destination Software', '1', 'Music Career Simulation', 'Career simulation and rhythm mini-games.', 'Train your voice and perform to become a pop sensation.', 'Popstar career simulation for young music fans.', 'Music Star: I Wanna Be a Popstar (Europe) takes you through the life of a rising artist. Practice singing, master dance moves, and manage your social calendar to build a fan base and reach the top of the charts in this multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mx-vs-atv-reflex-europe-enfrdeesit', 'NDS', 'MX vs ATV Reflex (Europe) (En,Fr,De,Es,It)', '2009', 'Racing', 'Rainbow Studios', '1', 'Off-Road Racing', 'Off-road racing and stunt competition.', 'Win races and perform stunts across varied terrains.', 'High-speed motocross and ATV racing for Europe.', 'MX vs ATV Reflex (Europe) features the "Rider Reflex" system, allowing for independent control of the rider and vehicle. Navigate mud, snow, and dirt while performing gravity-defying tricks in this intense off-road sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mx-vs-atv-reflex-usa-enfr', 'NDS', 'MX vs ATV Reflex (USA) (En,Fr)', '2009', 'Racing', 'Rainbow Studios', '1', 'Off-Road Racing', 'Off-road racing and stunt competition.', 'Win races and perform stunts across varied terrains.', 'North American release of the MX vs ATV hit.', 'Feel the dirt in MX vs ATV Reflex (USA). With a variety of vehicles including bikes and quads, this title offers realistic physics, a deep career mode, and frantic multiplayer races that emphasize skill and timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mx-vs-atv-extreme-limite-france', 'NDS', 'MX vs. ATV Extreme Limite (France)', '2010', 'Racing', 'Rainbow Studios', '1', 'Off-Road Racing', 'Off-road racing and stunt competition.', 'Master the extreme limits of motocross and ATV racing.', 'French edition of the MX vs ATV racing series.', 'MX vs. ATV Extreme Limite brings high-octane racing to the French market. Featuring localized tracks and riders, it focuses on the thrill of extreme jumps and tight cornering in a variety of off-road environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mx-vs-atv-untamed-europe', 'NDS', 'MX vs. ATV Untamed (Europe)', '2007', 'Racing', 'Rainbow Studios', '1', 'Off-Road Racing', 'Off-road racing and stunt competition.', 'Survive the most untamed tracks and win the championship.', 'European release of the "Untamed" racing edition.', 'MX vs. ATV Untamed (Europe) challenges you to master various racing disciplines, from Supercross to Opencross. Battle for the lead against aggressive AI and use the touch screen for quick bike adjustments during the race.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mx-vs-atv-untamed-usa', 'NDS', 'MX vs. ATV Untamed (USA)', '2007', 'Racing', 'Rainbow Studios', '1', 'Off-Road Racing', 'Off-road racing and stunt competition.', 'Survive the most untamed tracks and win the championship.', 'North American release of MX vs ATV Untamed.', 'Take the competition outdoors in MX vs. ATV Untamed (USA). Featuring a huge roster of licensed vehicles and challenging "Waypoint" races, it’s a comprehensive off-road experience that rewards daring stunts and precise driving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-animal-centre---baby-animals-europe-enfrdeesit', 'NDS', 'My Animal Centre - Baby Animals (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Pet simulation and veterinary care.', 'Nurture and treat adorable baby animals to health.', 'Baby animal rescue and care simulation.', 'My Animal Centre: Baby Animals (Europe) lets you care for the smallest patients. From polar bear cubs to kittens, use the stylus to feed, play with, and administer medical treatment to infants in this heartwarming multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-animal-centre-europe-enfrdeesitnl', 'NDS', 'My Animal Centre (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Animal care and clinic management.', 'Run a successful veterinary practice and heal pets.', 'Professional veterinary simulation for Europe.', 'My Animal Centre (Europe) puts you in the shoes of a vet. Diagnose illnesses, perform check-ups, and manage your clinic’s expansion while looking after dogs, cats, birds, and horses in a detailed 3D environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-animal-centre-in-africa-europe-enfrdeesit', 'NDS', 'My Animal Centre in Africa (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Wildlife rescue and sanctuary management.', 'Rescue and rehabilitate wild African animals.', 'Exotic wildlife vet simulation in Africa.', 'My Animal Centre in Africa (Europe) takes the vet genre to the savanna. Treat lions, rhinos, and zebras, ensuring they are healthy enough to be released back into the wild while managing your own rescue outpost.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-animal-centre-in-africa-europe-svnodafi', 'NDS', 'My Animal Centre in Africa (Europe) (Sv,No,Da,Fi)', '2008', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Wildlife rescue and sanctuary management.', 'Rescue and rehabilitate wild African animals.', 'Nordic edition of the African wildlife sim.', 'This version of My Animal Centre in Africa provides localized text for Swedish, Norwegian, Danish, and Finnish players. Experience the same deep animal care mechanics and ecological missions in the African wild.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-animal-centre-in-australia-europe-enfrdeesitnl', 'NDS', 'My Animal Centre in Australia (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Wildlife rescue and sanctuary management.', 'Care for unique Australian animals in the outback.', 'Exotic wildlife vet simulation in Australia.', 'My Animal Centre in Australia (Europe) focuses on species like kangaroos and koalas. Learn about the unique needs of Australian wildlife while managing a specialized hospital in the heart of the outback.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby---boy-europe-enfrdeesitnlpt', 'NDS', 'My Baby - Boy (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a baby boy and guide his early development.', 'Realistic parenting and baby care simulation.', 'My Baby - Boy (Europe) allows you to experience the joys of motherhood or fatherhood. Feed, bathe, and dress your baby boy, and use the microphone and touch screen to interact with him as he grows and learns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby---boy-usa-enfres', 'NDS', 'My Baby - Boy (USA) (En,Fr,Es)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a baby boy and guide his early development.', 'North American release of the baby boy sim.', 'Nurture your virtual infant in My Baby - Boy (USA). This title features realistic baby reactions and a progression system that tracks your child''s growth from birth to his first steps, requiring careful attention and love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby---first-steps-usa-enfres', 'NDS', 'My Baby - First Steps (USA) (En,Fr,Es)', '2009', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Toddler simulation and developmental activities.', 'Help your baby take their first steps and learn to talk.', 'Parenting simulation focused on toddlerhood.', 'My Baby - First Steps (USA) expands the parenting experience. Focus on the crucial developmental phase where your child begins to walk, talk, and interact more with the world through fun, educational mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby---girl-europe-enfrdeesitnlpt', 'NDS', 'My Baby - Girl (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a baby girl and guide her early development.', 'Realistic parenting and baby girl simulation.', 'My Baby - Girl (Europe) offers a heartwarming look at a child''s first year. Use the stylus to rock her to sleep and the microphone to teach her her first words in this detailed, multi-language nurturing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby---girl-usa-enfres', 'NDS', 'My Baby - Girl (USA) (En,Fr,Es)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a baby girl and guide her early development.', 'North American release of the baby girl sim.', 'Experience the milestones of a baby''s life in My Baby - Girl (USA). Customize her nursery, choose her outfits, and ensure she stays happy and healthy through responsive and intuitive touch-screen interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby-2---boy-&-girl-europe-enfrdeesitnl', 'NDS', 'My Baby 2 - Boy & Girl (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for your babies and manage a growing family.', 'The expanded sequel to the My Baby series.', 'My Baby 2 - Boy & Girl (Europe) allows you to care for both genders. It features improved graphics, more clothing options, and deeper social interactions, making it a more comprehensive parenting simulator for DS fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-baby-3-&-friends-europe-enfrdeesitnlpt', 'NDS', 'My Baby 3 & Friends (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2010', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Toddler simulation and social play.', 'Raise your child and interact with other "baby" friends.', 'Third entry in the My Baby series with social features.', 'My Baby 3 & Friends (Europe) adds a social dimension to parenting. Take your child to the park to meet other toddlers, unlock new activities, and watch your baby develop a unique personality through play and education.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-best-friends---cats-&-dogs-europe-enfrdeesit', 'NDS', 'My Best Friends - Cats & Dogs (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Pet simulation and grooming.', 'Care for and train various breeds of cats and dogs.', 'Comprehensive pet ownership and training sim.', 'My Best Friends - Cats & Dogs (Europe) is a dual pet simulation. Choose your favorite breed, manage their diet and exercise, and teach them tricks to compete in pet shows, all while building a lasting bond with your furry friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-boyfriend---der-sommer-meines-lebens-germany', 'NDS', 'My Boyfriend - Der Sommer Meines Lebens (Germany)', '2009', 'Adventure', 'Broken Rules', '1', 'Visual Novel', 'Social simulation and dating.', 'Navigate the drama of high school and find your first love.', 'German-language teen romance and life sim.', 'My Boyfriend - Der Sommer Meines Lebens focuses on summer romance. Manage your social life, choose your outfits, and navigate the emotional highs and lows of a teen girl''s summer vacation in this German exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-boyfriend---verliebt-in-einen-star-germany', 'NDS', 'My Boyfriend - Verliebt in einen Star (Germany)', '2009', 'Adventure', 'Broken Rules', '1', 'Visual Novel', 'Social simulation and dating.', 'Date a famous celebrity and manage your social status.', 'German-language celebrity romance simulation.', 'In My Boyfriend - Verliebt in einen Star, you get to live every fan''s dream. Balance your normal life with the glamour of dating a celebrity, managing your popularity and avoiding paparazzi in this engaging German title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-boyfriend-europe-enfrdeesit', 'NDS', 'My Boyfriend (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Broken Rules', '1', 'Visual Novel', 'Social simulation and dating.', 'Build relationships and manage your social life in a city.', 'Multi-language European teen romance sim.', 'My Boyfriend (Europe) allows players to create an avatar and navigate a vibrant social world. Work mini-games to earn money for fashion, interact with diverse characters, and find the perfect virtual partner.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-boyfriend-germany-ende', 'NDS', 'My Boyfriend (Germany) (En,De)', '2009', 'Adventure', 'Broken Rules', '1', 'Visual Novel', 'Social simulation and dating.', 'Build relationships and manage your social life.', 'German localized version of the teen dating sim.', 'This German version of My Boyfriend offers the complete social simulation experience. Focus on your character''s personality and style to attract the best matches while enjoying a story-driven campaign about young love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-boyfriend-summer-of-my-life-usa-enfrdeesit', 'NDS', 'My Boyfriend (Summer of My Life) (USA) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Broken Rules', '1', 'Visual Novel', 'Social simulation and dating.', 'Navigate a summer of romance and social activities.', 'North American release of the summer romance sim.', 'My Boyfriend (Summer of My Life) takes you on a seasonal adventure. Customize your character''s look and personality to find "the one" while participating in summer activities and managing your daily schedule.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-chinese-coach---learn-a-new-language-usa', 'NDS', 'My Chinese Coach - Learn a New Language (USA)', '2008', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and drills.', 'Learn Chinese (Mandarin) vocabulary and grammar.', 'Comprehensive Chinese language coach for the USA.', 'My Chinese Coach (USA) provides a structured path to learning Mandarin. Featuring over 10,000 words, handwriting recognition for characters, and speech comparison, it''s a powerful tool for students and travelers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-chinese-coach---learn-to-speak-chinese-europe-enfrdeesit', 'NDS', 'My Chinese Coach - Learn to Speak Chinese (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and drills.', 'Learn Chinese (Mandarin) vocabulary and grammar.', 'European edition of the Chinese language tutor.', 'Master the basics of Chinese with My Chinese Coach (Europe). This version includes localized instruction in multiple languages to help European speakers grasp the tones and characters of Mandarin through interactive games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-cooking-coach---prepare-healthy-recipes-europe-ndsi-enhanced', 'NDS', 'My Cooking Coach - Prepare Healthy Recipes (Europe) (NDSi Enhanced)', '2009', 'Simulation', 'Nintendo', '1', 'Cooking Simulation', 'Cooking simulation and nutritional guide.', 'Learn healthy recipes and manage your daily diet.', 'DSi enhanced healthy cooking coach for Europe.', 'My Cooking Coach (Europe) features over 240 healthy recipes. Use the NDSi camera to personalize your kitchen experience and follow step-by-step instructions from a virtual chef to improve your culinary skills and health.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-dangerous-pet---snake-europe-enfrdeesit', 'NDS', 'My Dangerous Pet - Snake (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Creat Studios', '1', 'Casual Simulation', 'Exotic pet simulation and care.', 'Learn to care for and maintain a pet snake.', 'Unique reptile care and habitat simulation.', 'My Dangerous Pet - Snake (Europe) is for fans of exotic animals. Learn about different snake species, manage their terrarium''s temperature and humidity, and handle your pet carefully using the DS touch screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-dangerous-pet---spider-europe-enfrdeesit', 'NDS', 'My Dangerous Pet - Spider (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Creat Studios', '1', 'Casual Simulation', 'Exotic pet simulation and care.', 'Learn to care for and maintain a pet spider.', 'Unique arachnid care and habitat simulation.', 'My Dangerous Pet - Spider (Europe) allows you to keep virtual tarantulas and other spiders. Build their environment, feed them insects, and learn fascinating facts about these misunderstood creatures in a safe, digital format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-dog-coach---understand-your-dog-with-cesar-millan-europe-enfres', 'NDS', 'My Dog Coach - Understand Your Dog with Cesar Millan (Europe) (En,Fr,Es)', '2010', 'Simulation', 'Behaviour Interactive', '1', 'Pet Simulation', 'Dog training and behavioral coaching.', 'Train your dog using the "Cesar Millan" method.', 'Professional dog training simulation based on the TV show.', 'My Dog Coach (Europe) features the world-renowned "Dog Whisperer." Learn to understand your dog''s psychology, correct bad behaviors, and complete training exercises designed to create a balanced relationship with your pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-dogs-paradise-europe-enfrdeesitnl', 'NDS', 'My Dogs Paradise (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Neko Entertainment', '1', 'Pet Simulation', 'Pet boarding and kennel management.', 'Manage a luxury boarding facility for dogs.', 'Dog hotel and care simulation for Europe.', 'My Dogs Paradise (Europe) tasks you with running the perfect retreat for dogs. Groom, feed, and play with different breeds to ensure they have a great stay, earning funds to upgrade your facility and decor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-doitall-usa-enfres', 'NDS', 'My DoItAll (USA) (En,Fr,Es)', '2009', 'Simulation', 'Behaviour Interactive', '1', 'Casual Simulation', 'Personal organizer and mini-game suite.', 'Organize your life and share content with friends.', 'Comprehensive organizer and utility tool for NDS.', 'My DoItAll (USA) is the ultimate digital planner. It includes a calendar, voice memos, a contact list, and even a "tracker" feature, alongside various mini-games and customization options to keep your DS functional and fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-dress-up-europe-enfrdeesitsvnodafi', 'NDS', 'My Dress-Up (Europe) (En,Fr,De,Es,It,Sv,No,Da,Fi)', '2009', 'Simulation', 'Broken Rules', '1', 'Fashion Simulation', 'Fashion design and avatar customization.', 'Create unique outfits and style your own models.', 'Creative fashion and dress-up simulation.', 'My Dress-Up (Europe) allows for endless creative expression. Choose from hundreds of clothing items, accessories, and hairstyles to dress your avatar, then participate in fashion contests to show off your style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-dress-up-usa', 'NDS', 'My Dress-Up (USA)', '2009', 'Simulation', 'Broken Rules', '1', 'Fashion Simulation', 'Fashion design and avatar customization.', 'Create unique outfits and style your own models.', 'North American release of the dress-up game.', 'Become a fashion icon in My Dress-Up (USA). Use the stylus to design your look, manage your wardrobe, and share your best outfits with friends via local wireless connection in this vibrant and stylish simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-english-coach-europe-frdeesit', 'NDS', 'My English Coach (Europe) (Fr,De,Es,It)', '2007', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and drills.', 'Improve your English vocabulary and pronunciation.', 'Multi-language English coach for European speakers.', 'My English Coach (Europe) is designed for non-native speakers. It tracks your progress through hundreds of lessons and uses the DS microphone to help you perfect your English speaking skills in a fun, interactive way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-english-coach-para-hispanoparlantes---ingles-a-tu-alcance!-usa-es', 'NDS', 'My English Coach para Hispanoparlantes - Ingles a Tu Alcance! (USA) (Es)', '2008', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning for Spanish speakers.', 'Master English through a specialized curriculum for Hispanics.', 'English learning coach for Spanish speakers (USA).', 'My English Coach para Hispanoparlantes is tailored specifically for the linguistic needs of Spanish speakers. Focus on common grammatical hurdles and pronunciation differences to achieve English fluency on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-farm-around-the-world-europe-enfrdeesitpt', 'NDS', 'My Farm Around the World (Europe) (En,Fr,De,Es,It,Pt)', '2009', 'Simulation', 'Independent Arts', '1', 'Farming Simulation', 'Global farming simulation and management.', 'Manage farms in different climates and countries.', 'Worldwide farming and agriculture simulation.', 'My Farm Around the World (Europe) takes agriculture to a global scale. Manage an American ranch, a European farm, or an African plantation, dealing with different livestock and crops in this diverse management title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-farm-around-the-world-usa-enfr', 'NDS', 'My Farm Around the World (USA) (En,Fr)', '2009', 'Simulation', 'Independent Arts', '1', 'Farming Simulation', 'Global farming simulation and management.', 'Manage farms in different climates and countries.', 'North American release of the global farming sim.', 'Experience life on the farm in My Farm Around the World (USA). Balance your budget, care for animals like camels or cows depending on the region, and expand your agricultural empire across multiple continents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-fashion-studio-usa-enfres', 'NDS', 'My Fashion Studio (USA) (En,Fr,Es)', '2009', 'Simulation', 'Visual Impact', '1', 'Fashion Simulation', 'Fashion design and boutique management.', 'Design your own clothes and run a fashion studio.', 'Comprehensive fashion designer simulation for USA.', 'My Fashion Studio (USA) allows you to become a professional designer. Select fabrics, cut patterns, and sew garments using the touch screen, then display your creations on the runway to build your brand’s reputation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-french-coach---learn-a-new-language-usa', 'NDS', 'My French Coach - Learn a New Language (USA)', '2008', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and mini-games.', 'Master French vocabulary and sentence structure.', 'Comprehensive French language tutor for North America.', 'My French Coach (USA) offers a structured curriculum with over 1,000 lessons. Use the touch screen to practice writing and the microphone to compare your pronunciation with native speakers in this award-winning educational tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-french-coach---level-1---learn-to-speak-french-europe', 'NDS', 'My French Coach - Level 1 - Learn to Speak French (Europe)', '2009', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning for beginners.', 'Learn basic French words and common phrases.', 'Introductory French language coach for Europe.', 'My French Coach - Level 1 (Europe) is designed for those with no prior knowledge of the language. Progress through fun mini-games that teach essential vocabulary for travel, dining, and daily conversation in France.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-french-coach---level-2---improve-your-french-europe', 'NDS', 'My French Coach - Level 2 - Improve Your French (Europe)', '2010', 'Educational', 'Nintendo', '1', 'Language Learning', 'Advanced language learning and drills.', 'Reach an intermediate level of French fluency.', 'Advanced French language coach for Europe.', 'My French Coach - Level 2 (Europe) builds upon the basics. Focus on complex grammar, verb conjugations, and expanded vocabulary to improve your conversational skills and reading comprehension on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-friends-europe-enfrdeesit', 'NDS', 'My Friends (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Social simulation and pet care.', 'Build a network of friends and care for various pets.', 'Social and animal care simulation for Europe.', 'My Friends (Europe) combines the joy of friendship with pet ownership. Interact with in-game characters, share gifts, and care for dogs and cats in a vibrant, friendly digital neighborhood suitable for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-friends-usa-enfres', 'NDS', 'My Friends (USA) (En,Fr,Es)', '2008', 'Simulation', 'Independent Arts', '1', 'Casual Simulation', 'Social simulation and pet care.', 'Build a network of friends and care for various pets.', 'North American release of the friendship simulation.', 'In My Friends (USA), players can create their own avatar and explore a world filled with friendly NPCs. Complete tasks, play mini-games, and manage your pets'' needs to unlock new outfits and decorations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-frogger---toy-trials-europe-enfrdeesit', 'NDS', 'My Frogger - Toy Trials (Europe) (En,Fr,De,Es,It)', '2010', 'Action', 'Voltex', '1', 'Arcade Action', 'Puzzle-platformer with pet mechanics.', 'Guide your Frogger toy through obstacle-filled levels.', 'Frogger-themed puzzle adventure with a twist.', 'My Frogger: Toy Trials (Europe) tasks you with training your toy frog for a grand competition. Use the stylus to navigate grids, solve environmental puzzles, and participate in racing trials in this unique take on the classic franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-frogger---toy-trials-usa', 'NDS', 'My Frogger - Toy Trials (USA)', '2010', 'Action', 'Voltex', '1', 'Arcade Action', 'Puzzle-platformer with pet mechanics.', 'Guide your Frogger toy through obstacle-filled levels.', 'North American release of Toy Trials.', 'Navigate hazardous levels and outsmart rivals in My Frogger: Toy Trials (USA). Customize your frog''s abilities and master the touch-screen controls to solve physics-based puzzles and win the championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-fun-facts-coach---facts-for-your-daily-life-usa-enfr', 'NDS', 'My Fun Facts Coach - Facts for Your Daily Life (USA) (En,Fr)', '2009', 'Educational', 'Nintendo', '1', 'General Knowledge', 'Trivia and educational mini-games.', 'Learn interesting facts about science, history, and culture.', 'Daily trivia and general knowledge coach.', 'My Fun Facts Coach (USA) provides a daily dose of information. Test your knowledge across multiple categories and learn fascinating "did you know" facts that you can share with friends and family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-happy-kitchen-europe-enfrdeesit', 'NDS', 'My Happy Kitchen (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Visual Impact', '1', 'Cooking Simulation', 'Cooking simulation and kitchen management.', 'Cook various recipes and run a successful kitchen.', 'Casual cooking and recipe simulation for Europe.', 'My Happy Kitchen (Europe) focuses on the fun of food preparation. Use the stylus to chop, stir, and sauté a wide variety of international dishes in a colorful and accessible kitchen environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-health-coach---manage-your-weight-europe-enfrdeesitnl', 'NDS', 'My Health Coach - Manage Your Weight (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Nintendo', '1', 'Health Management', 'Health management and calorie tracking.', 'Track your food intake and exercise to reach weight goals.', 'Weight management and wellness coach for Europe.', 'My Health Coach: Manage Your Weight (Europe) acts as a digital health diary. Developed with nutritionists, it helps you set realistic goals, track calories, and offers healthy lifestyle tips to keep you motivated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-health-coach---manage-your-weight-europe-enfrdeesitnl-rev-1', 'NDS', 'My Health Coach - Manage Your Weight (Europe) (En,Fr,De,Es,It,Nl) (Rev 1)', '2009', 'Simulation', 'Nintendo', '1', 'Health Management', 'Health management and calorie tracking.', 'Track your food intake and exercise to reach weight goals.', 'Revised European edition of the weight coach.', 'This Revision 1 of Manage Your Weight includes updated data and UI tweaks. It remains a comprehensive tool for those looking to improve their physical health through steady, tracked progress on their NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-health-coach---stop-smoking-with-allen-carr-europe-enfrdeesitnl', 'NDS', 'My Health Coach - Stop Smoking with Allen Carr (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Simulation', 'Nintendo', '1', 'Health Management', 'Interactive behavioral therapy and cessation guide.', 'Quit smoking using the famous Allen Carr method.', 'Digital guide to help players stop smoking.', 'My Health Coach: Stop Smoking with Allen Carr (Europe) uses the interactive nature of the DS to deliver the "Easyway" method. It challenges your perceptions of smoking and provides support through mini-games and progress tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-healthy-cooking-coach---easy-way-to-cook-healthy-usa-ndsi-enhanced', 'NDS', 'My Healthy Cooking Coach - Easy Way to Cook Healthy (USA) (NDSi Enhanced)', '2010', 'Simulation', 'Nintendo', '1', 'Cooking Simulation', 'Cooking simulation and nutrition guide.', 'Learn to cook healthy meals with NDSi camera support.', 'DSi enhanced healthy cooking tutor for the USA.', 'My Healthy Cooking Coach (USA) features over 240 recipes. Use the NDSi camera to personalize your experience and follow step-by-step instructions to create nutritious, chef-quality meals at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-hero---doctor-usa', 'NDS', 'My Hero - Doctor (USA)', '2009', 'Simulation', 'Independent Arts', '1', 'Role-Playing Simulation', 'Medical career simulation.', 'Diagnose and treat patients as a dedicated doctor.', 'Professional medical simulation for North America.', 'My Hero: Doctor (USA) lets you live the life of a physician. Perform check-ups, manage emergency room situations, and use the stylus to carry out surgical procedures in this educational career sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-hero---firefighter-usa', 'NDS', 'My Hero - Firefighter (USA)', '2009', 'Simulation', 'Independent Arts', '1', 'Role-Playing Simulation', 'Emergency service career simulation.', 'Put out fires and rescue citizens from dangerous situations.', 'Heroic firefighter simulation for North America.', 'My Hero: Firefighter (USA) puts you on the front lines. Drive the fire truck to the scene, navigate burning buildings, and use various tools to save lives in this action-packed career simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-horse-&-me---riding-for-gold-usa-enfres', 'NDS', 'My Horse & Me - Riding for Gold (USA) (En,Fr,Es)', '2008', 'Simulation', 'Tate Interactive', '1', 'Equestrian Simulation', 'Equestrian sports and horse care simulation.', 'Train your horse and win professional jumping events.', 'Competitive horse riding and care for USA.', 'My Horse & Me: Riding for Gold (USA) features officially licensed content. Experience realistic horse behaviors, deep grooming mechanics, and challenging jumping courses as you aim for the gold medal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-horse-&-me-europe-enfrdeesitnlsvda', 'NDS', 'My Horse & Me (Europe) (En,Fr,De,Es,It,Nl,Sv,Da)', '2007', 'Simulation', 'Tate Interactive', '1', 'Equestrian Simulation', 'Equestrian sports and horse care simulation.', 'Manage your own horse and compete in world tournaments.', 'The first entry in the acclaimed horse racing series.', 'My Horse & Me (Europe) is known for its high level of realism. Groom your horse, choose your riding gear, and compete in various international championships across diverse weather conditions and terrains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-horse-&-me-usa-enfres', 'NDS', 'My Horse & Me (USA) (En,Fr,Es)', '2008', 'Simulation', 'Tate Interactive', '1', 'Equestrian Simulation', 'Equestrian sports and horse care simulation.', 'Manage your own horse and compete in world tournaments.', 'North American release of the realistic horse sim.', 'Bond with your horse in My Horse & Me (USA). Featuring beautiful graphics and precise controls, it allows players to experience the daily life of a rider, from stable management to the thrill of the stadium.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-horse-&-me-2-europe-enfrdeesitnlsvnodafi', 'NDS', 'My Horse & Me 2 (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi)', '2009', 'Simulation', 'Tate Interactive', '1', 'Equestrian Simulation', 'Equestrian sports and horse care simulation.', 'Lead your horse to victory in world championships.', 'Feature-rich sequel with enhanced horse mechanics.', 'My Horse & Me 2 (Europe) introduces more breeds and deeper customization. Experience a more personal connection with your horse through an expanded grooming system and new competitive disciplines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-horse-club-europe-endeesitnl', 'NDS', 'My Horse Club (Europe) (En,De,Es,It,Nl)', '2011', 'Simulation', 'Tate Interactive', '1', 'Equestrian Simulation', 'Horse care and social simulation.', 'Manage a horse club and build relationships with members.', 'Social-focused horse boarding and care sim.', 'My Horse Club (Europe) combines animal care with a teen drama narrative. Manage your stables, train your favorite horses, and navigate the social life of the equestrian club in this multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-japanese-coach---learn-a-new-language-usa', 'NDS', 'My Japanese Coach - Learn a New Language (USA)', '2009', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and drills.', 'Master Japanese Hiragana, Katakana, and basic Kanji.', 'Comprehensive Japanese language coach for USA.', 'My Japanese Coach (USA) is the gold standard for learning Japanese on the DS. It features a stroke-order guide for characters, a massive dictionary, and voice recognition to help you master pronunciation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-japanese-coach---learn-to-speak-japanese-europe', 'NDS', 'My Japanese Coach - Learn to Speak Japanese (Europe)', '2008', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and drills.', 'Learn essential Japanese vocabulary and phrases.', 'European edition of the Japanese language tutor.', 'Start your journey into Japanese culture with My Japanese Coach (Europe). Through engaging mini-games and a structured curriculum, it helps European speakers learn the fundamentals of the language in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-little-baby-europe-enfrdeesitsvnoda', 'NDS', 'My Little Baby (Europe) (En,Fr,De,Es,It,Sv,No,Da)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a virtual baby from birth through their first year.', 'Heartwarming baby care simulation for Europe.', 'My Little Baby (Europe) features realistic 3D babies that react to your touch and voice. Feed, bathe, and play with your infant to see them reach milestones like crawling and laughing in this multi-language sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-little-baby-europe-enfrdees', 'NDS', 'My Little Baby (Europe) (En,Fr,De,Es)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a virtual baby and guide their growth.', 'Regional European release with focused languages.', 'This version of My Little Baby offers the same deep nurturing gameplay for French, German, Spanish, and English speakers. Focus on the delicate tasks of early parenting and watch your digital child thrive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-little-baby-germany-ende', 'NDS', 'My Little Baby (Germany) (En,De)', '2008', 'Simulation', 'Sinister Games', '1', 'Life Simulation', 'Infant simulation and parenting.', 'Care for a virtual baby and guide their growth.', 'German localized version of the baby sim.', 'Manage your baby''s schedule in My Little Baby (Germany). From choosing the cutest outfits to monitoring their health and happiness, this title provides a realistic and rewarding parenting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-little-flufties-europe-enfrdeesit', 'NDS', 'My Little Flufties (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Neko Entertainment', '1', 'Pet Simulation', 'Virtual pet simulation with fantasy creatures.', 'Raise and play with "Flufties" in a magical world.', 'Adorable fantasy pet care and mini-games.', 'My Little Flufties (Europe) features cute, cloud-like creatures. Interact with them using the touch screen, complete various puzzles, and help them grow in their whimsical environment in this charming title for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-little-pony---pinkie-pies-party-usa', 'NDS', 'My Little Pony - Pinkie Pie''s Party (USA)', '2008', 'Simulation', 'Gaming Minds', '1', 'Party Game', 'Party game with mini-games and puzzles.', 'Help Pinkie Pie plan the best birthday party ever.', 'Vibrant and kid-friendly My Little Pony game.', 'My Little Pony: Pinkie Pie''s Party (USA) is filled with colorful activities. Complete puzzles, find hidden items, and help the ponies of Ponyville prepare for a massive celebration in this cheerful adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-make-up-europe-enfrdeesitsvnodafi', 'NDS', 'My Make-Up (Europe) (En,Fr,De,Es,It,Sv,No,Da,Fi)', '2009', 'Simulation', 'Broken Rules', '1', 'Fashion Simulation', 'Beauty and makeup simulation.', 'Apply makeup and style hair for different clients.', 'Creative beauty salon and styling simulator.', 'My Make-Up (Europe) allows you to run your own beauty studio. Use the stylus to apply lipstick, eyeshadow, and blush, creating unique looks for various characters and fashion events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-make-up-usa', 'NDS', 'My Make-Up (USA)', '2009', 'Simulation', 'Broken Rules', '1', 'Fashion Simulation', 'Beauty and makeup simulation.', 'Apply makeup and style hair for different clients.', 'North American release of the makeup sim.', 'Unleash your inner makeup artist in My Make-Up (USA). Experiment with thousands of color combinations and accessories to create the perfect look for your models in this fun and creative simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-melody-angel-book---denshi-techou-&-enjoy-game-japan', 'NDS', 'My Melody Angel Book - Denshi Techou & Enjoy Game (Japan)', '2008', 'Utility', 'Sanrio', '1', 'Digital Diary', 'Digital organizer and casual mini-games.', 'Manage your schedule with the help of My Melody.', 'Sanrio-themed electronic planner and game book.', 'My Melody Angel Book is a multi-functional digital diary. Featuring the popular Sanrio character, it includes a calendar, memo pad, and various cute mini-games designed to make daily organization fun for Japanese fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-own-pet-shelter-europe-enfrdenl', 'NDS', 'My Own Pet Shelter (Europe) (En,Fr,De,Nl)', '2009', 'Simulation', 'Independent Arts', '1', 'Pet Management', 'Animal rescue and shelter management.', 'Care for abandoned pets and find them new homes.', 'Heartwarming animal shelter simulation for Europe.', 'My Own Pet Shelter (Europe) puts you in charge of a rescue center. Rehabilitate sick or lonely pets, manage the facility''s resources, and carefully vet potential owners to ensure every animal finds a "forever home."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-paris-fashion-house-europe-enfrdeesitnlsvnoda', 'NDS', 'My Paris Fashion House (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Simulation', 'Visual Impact', '1', 'Fashion Simulation', 'Fashion design and boutique management.', 'Design high-fashion outfits and run a Paris studio.', 'Chic fashion designer simulation set in Paris.', 'My Paris Fashion House (Europe) focuses on the world of haute couture. Choose fabrics, create patterns, and manage your own boutique in the fashion capital of the world, aiming to become a renowned designer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-beauty-salon-europe-enfrdeesit', 'NDS', 'My Pet Beauty Salon (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Pet grooming and beauty salon simulation.', 'Run a successful salon for dogs, cats, and rabbits.', 'Professional pet styling and grooming sim.', 'My Pet Beauty Salon (Europe) allows you to pamper various pets. From washing and brushing to accessorizing with cute ribbons, ensure every pet looks their best to keep your customers coming back.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-chimp-usa', 'NDS', 'My Pet Chimp (USA)', '2009', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Exotic pet simulation and training.', 'Raise and train a clever chimpanzee.', 'Unique primate care and interaction sim.', 'My Pet Chimp (USA) offers a deep bond with a virtual primate. Teach your chimp tricks using the microphone and stylus, manage their diet and play, and watch them learn and grow in this engaging simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-dolphin-europe-enfrdeesit', 'NDS', 'My Pet Dolphin (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Aquatic pet simulation and training.', 'Care for a dolphin and perform spectacular shows.', 'Unique underwater pet simulation for Europe.', 'My Pet Dolphin (Europe) allows you to bond with a virtual dolphin. Use the touch screen to teach tricks, swim together, and manage the health of your aquatic friend while preparing for live performances in a tropical aquarium.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-dolphin-2-europe-enfrdeesit', 'NDS', 'My Pet Dolphin 2 (Europe) (En,Fr,De,Es,It)', '2010', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Aquatic pet simulation and training.', 'Explore the ocean and train new species of dolphins.', 'The expanded sequel to the dolphin care sim.', 'My Pet Dolphin 2 (Europe) features more environments and species. Discover hidden treasures in the sea, interact with whales, and master complex synchronized routines in this relaxing and educational marine adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-hotel-2-europe-enit', 'NDS', 'My Pet Hotel 2 (Europe) (En,It)', '2010', 'Simulation', 'Tivola', '1', 'Management Simulation', 'Pet boarding and management simulation.', 'Manage a holiday resort for various domestic pets.', 'Pet hotel management for English/Italian players.', 'My Pet Hotel 2 (Europe) tasks you with caring for dogs, cats, and horses while their owners are away. Expand your facilities and ensure every guest is pampered to earn a 5-star rating in this management title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-hotel-2-europe-ensvnoda', 'NDS', 'My Pet Hotel 2 (Europe) (En,Sv,No,Da)', '2010', 'Simulation', 'Tivola', '1', 'Management Simulation', 'Pet boarding and management simulation.', 'Manage a holiday resort for various domestic pets.', 'Nordic edition of the pet boarding simulation.', 'This version of My Pet Hotel 2 brings the animal care experience to Northern Europe. Focus on grooming, feeding, and playing with pets to keep them happy in this multi-language hotel management sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-hotel-2-europe-fres', 'NDS', 'My Pet Hotel 2 (Europe) (Fr,Es)', '2010', 'Simulation', 'Tivola', '1', 'Management Simulation', 'Pet boarding and management simulation.', 'Manage a holiday resort for various domestic pets.', 'French/Spanish edition of the pet hotel sim.', 'Manage your virtual kennel in this localized edition of My Pet Hotel 2. Use the stylus to clean enclosures and perform daily check-ups on your furry guests to build a reputable business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-kitten-europe-enfrdeesit', 'NDS', 'My Pet Kitten (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Kitten care and training simulation.', 'Raise a tiny kitten into a healthy, happy adult cat.', 'Adorable feline nurturing simulation for Europe.', 'My Pet Kitten (Europe) focuses on the bond between owner and cat. Feed your kitten, play with yarn, and teach them house rules using the touch screen and microphone in this charming pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-parrot-europe-enfrdeesit', 'NDS', 'My Pet Parrot (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Bird care and mimicry simulation.', 'Train your parrot to talk and perform colorful tricks.', 'Unique avian pet simulation for Europe.', 'My Pet Parrot (Europe) offers a rare look at bird ownership. Use the DS microphone to teach your parrot phrases and the stylus to groom its feathers, ensuring your feathered friend stays healthy and entertained.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-pony-europe-enfrdeesit', 'NDS', 'My Pet Pony (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Horse care and riding simulation.', 'Care for your pony and win local jumping events.', 'Charming pony care and equestrian simulation.', 'My Pet Pony (Europe) is designed for younger horse lovers. Learn the basics of grooming, stable management, and riding as you build a relationship with your own pony in a beautiful country setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-puppy-europe-enfrdeesit', 'NDS', 'My Pet Puppy (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Pet Simulation', 'Puppy care and training simulation.', 'Raise a puppy and teach them various obedience tricks.', 'Classic puppy nurturing simulation for Europe.', 'My Pet Puppy (Europe) features multiple breeds to choose from. Spend your days training, feeding, and walking your dog, utilizing the NDS features to build a deep connection with your virtual pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-school-europe-enfresit', 'NDS', 'My Pet School (Europe) (En,Fr,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Pet Management', 'Animal training and educational simulation.', 'Train pets to behave and learn new skills for shows.', 'Specialized pet training school simulation.', 'My Pet School (Europe) puts you in the role of an animal trainer. Work with different species to improve their behavior and prepare them for public demonstrations in this interactive educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-shop-europe-enfrdeesit', 'NDS', 'My Pet Shop (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Shop Management', 'Retail management and pet care.', 'Manage a successful pet shop and find homes for animals.', 'Pet store simulation and animal care hybrid.', 'My Pet Shop (Europe) tasks you with running a boutique for animal lovers. Match the right pet with the right owner, manage your inventory, and care for the animals in your shop to grow your business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-shop-usa-enfrdeesit', 'NDS', 'My Pet Shop (USA) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Independent Arts', '1', 'Shop Management', 'Retail management and pet care.', 'Manage a successful pet shop and find homes for animals.', 'North American release of the pet store sim.', 'Run the best pet boutique in town in My Pet Shop (USA). Explore the town to find rare animals, groom them to perfection, and build a reputation as the most caring shop owner in the region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-zoo-vet-europe-enfrdeesit', 'NDS', 'My Pet Zoo Vet (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Veterinary Simulation', 'Veterinary simulation in a zoo setting.', 'Treat exotic zoo animals and ensure their health.', 'Wild animal veterinary and care simulation.', 'My Pet Zoo Vet (Europe) takes medical care to the wild. From giraffes to lions, use the touch screen to perform surgeries and check-ups on the zoo''s residents in this challenging medical career sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-puppy-shop-europe-enfrdeesitnlsvda', 'NDS', 'My Puppy Shop (Europe) (En,Fr,De,Es,It,Nl,Sv,Da)', '2009', 'Simulation', 'Independent Arts', '1', 'Shop Management', 'Puppy retail and grooming simulation.', 'Manage a specialized shop for puppies and accessories.', 'Dedicated puppy store management for Europe.', 'My Puppy Shop (Europe) focuses on the business of selling and grooming young dogs. Help customers choose their perfect companion and keep your shop stocked with the latest pet fashion and toys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-sat-coach-with-the-princeton-review---crack-the-sat-usa', 'NDS', 'My SAT Coach with the Princeton Review - Crack the SAT (USA)', '2009', 'Educational', 'The Princeton Review', '1', 'Test Preparation', 'Educational SAT test preparation.', 'Improve your SAT scores through drills and mock exams.', 'Official SAT prep tool with Princeton Review.', 'My SAT Coach (USA) provides a personalized study plan for the college entrance exam. It includes thousands of practice questions, timed tests, and mini-games designed to make studying more engaging and effective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-secret-diary-europe-enfrdeesitsvnodafi', 'NDS', 'My Secret Diary (Europe) (En,Fr,De,Es,It,Sv,No,Da,Fi)', '2009', 'Simulation', 'Broken Rules', '1', 'Diary Simulation', 'Digital organizer and private diary.', 'Keep your secrets safe and manage your daily life.', 'Personal diary and organizer for girls in Europe.', 'My Secret Diary (Europe) is a password-protected tool for the NDS. It includes a mood tracker, contact list, and mini-games, allowing you to store your thoughts and organize your schedule in a cute digital format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-secret-world-by-imagine-europe-enfrdeesitnlptsvnoda', 'NDS', 'My Secret World by Imagine (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da)', '2009', 'Simulation', 'Broken Rules', '1', 'Life Simulation', 'Social simulation and secret diary.', 'Customize your world and share secrets with friends.', 'Imagine-branded social sim and organizer for Europe.', 'My Secret World by Imagine (Europe) offers a safe space for personal expression. Customize your avatar, play mini-games to unlock fashion, and use the wireless connection to share secrets with other players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-secret-world-by-imagine-usa-enfrespt', 'NDS', 'My Secret World by Imagine (USA) (En,Fr,Es,Pt)', '2009', 'Simulation', 'Broken Rules', '1', 'Life Simulation', 'Social simulation and secret diary.', 'Customize your world and share secrets with friends.', 'North American release of the Imagine social sim.', 'Create your own digital sanctuary in My Secret World by Imagine (USA). This title combines life simulation with organizational tools like a calendar and diary, all wrapped in a stylish and customizable interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-spanish-coach---learn-a-new-language-usa', 'NDS', 'My Spanish Coach - Learn a New Language (USA)', '2008', 'Educational', 'Nintendo', '1', 'Language Learning', 'Language learning through lessons and drills.', 'Master Spanish vocabulary, grammar, and pronunciation.', 'Comprehensive Spanish language coach for USA.', 'My Spanish Coach (USA) is an award-winning tool for learning a new language. It features over 1,000 lessons that adapt to your progress, using mini-games to keep you motivated and a built-in dictionary for quick reference.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-spanish-coach---level-2---improve-your-spanish-europe', 'NDS', 'My Spanish Coach - Level 2 - Improve Your Spanish (Europe)', '2009', 'Educational', 'Nintendo', '1', 'Language Learning', 'Advanced language learning and drills.', 'Reach an intermediate level of Spanish fluency.', 'Advanced Spanish language coach for Europe.', 'My Spanish Coach - Level 2 (Europe) builds on the basics of Level 1. Focus on complex verb conjugations, regional slang, and expanded vocabulary to help you communicate more effectively in Spanish-speaking countries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-stop-smoking-coach-with-allen-carr-easyway---quit-for-good-usa-enfres', 'NDS', 'My Stop Smoking Coach with Allen Carr Easyway - Quit for Good (USA) (En,Fr,Es)', '2009', 'Simulation', 'Nintendo', '1', 'Health Management', 'Interactive behavioral therapy and cessation guide.', 'Quit smoking using the Allen Carr Easyway method.', 'Digital cessation tool for the North American market.', 'My Stop Smoking Coach (USA) provides a supportive environment to help you quit for good. It uses the DS''s interactive nature to deliver lessons, track your progress, and provide tips for managing cravings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-vet-practice---in-australia-europe-enfrdeesit', 'NDS', 'My Vet Practice - In Australia (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Veterinary Simulation', 'Veterinary simulation in an Australian setting.', 'Treat native Australian wildlife and domestic animals.', 'Australian-themed veterinary career simulation.', 'My Vet Practice - In Australia (Europe) tasks you with caring for kangaroos and koalas alongside dogs and cats. Manage your clinic and respond to emergencies in the outback in this unique medical sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-vet-practice---in-the-country-europe-enfrdeesit', 'NDS', 'My Vet Practice - In the Country (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Veterinary Simulation', 'Veterinary simulation in a rural setting.', 'Manage a country vet clinic and treat farm animals.', 'Countryside veterinary career simulation.', 'My Vet Practice - In the Country (Europe) focuses on the life of a rural veterinarian. Treat horses, cows, and pets while managing your reputation and the financial health of your growing practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-weight-loss-coach---improve-your-health-usa-enfres', 'NDS', 'My Weight Loss Coach - Improve Your Health (USA) (En,Fr,Es)', '2009', 'Simulation', 'Nintendo', '1', 'Health Management', 'Health management and fitness tracking.', 'Reach your weight loss goals through tracking and advice.', 'Comprehensive weight loss and wellness coach.', 'My Weight Loss Coach (USA) helps you manage your physical health. Use the included pedometer (in original retail versions) to track steps, log your meals, and follow a personalized fitness plan on your DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-word-coach---develop-your-vocabulary-europe', 'NDS', 'My Word Coach - Develop Your Vocabulary (Europe)', '2008', 'Educational', 'Nintendo', '1', 'Vocabulary Training', 'Vocabulary and spelling training.', 'Expand your vocabulary through fun word games.', 'Linguistic trainer and word game collection.', 'My Word Coach (Europe) is designed to improve your command of the language. Solve anagrams and word puzzles that challenge your speed and accuracy, helping you become a better communicator through daily practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-word-coach---improve-your-vocabulary-usa', 'NDS', 'My Word Coach - Improve Your Vocabulary (USA)', '2008', 'Educational', 'Nintendo', '1', 'Vocabulary Training', 'Vocabulary and spelling training.', 'Expand your vocabulary through fun word games.', 'North American release of the word-building coach.', 'Master the English language in My Word Coach (USA). Developed with linguists, it offers a scientific approach to learning new words, tracking your "Expression Potential" as you play through addictive mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-word-coach---verbeter-je-woordenschat-netherlands', 'NDS', 'My Word Coach - Verbeter Je Woordenschat (Netherlands)', '2009', 'Educational', 'Nintendo', '1', 'Vocabulary Training', 'Vocabulary and spelling training.', 'Improve your Dutch vocabulary through word games.', 'Dutch localized version of the word coach.', 'Verbeter Je Woordenschat (Netherlands) provides a fun way for Dutch speakers to refine their language. Complete word-based challenges and track your progress as your vocabulary grows in this educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-word-coach-junior---woordjes-leren-netherlands', 'NDS', 'My Word Coach Junior - Woordjes Leren (Netherlands)', '2009', 'Educational', 'Nintendo', '1', 'Vocabulary Training', 'Educational word games for children.', 'Learn new words and improve spelling through play.', 'Dutch junior edition of the word coach.', 'My Word Coach Junior: Woordjes Leren is tailored for younger students. It uses colorful graphics and simple mini-games to help children build a solid foundation in their native Dutch language and spelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-world-my-way-usa', 'NDS', 'My World, My Way (USA)', '2009', 'Simulation', 'Broken Rules', '1', 'Life Simulation', 'Turn-based RPG with a "spoiled princess" theme.', 'Reach the ends of the earth by "complaining" to change reality.', 'Quirky and unique RPG with world-shaping mechanics.', 'My World, My Way (USA) stars Princess Elise. In this creative RPG, you can use "Power of Pout" points to alter enemy stats, change world environments, and skip quests, offering a humorous take on traditional genre tropes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---agents-europe-enfrdeesitnlptsvnoda', 'NDS', 'MySims - Agents (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da)', '2009', 'Simulation', 'Maxis', '1', 'Adventure Simulation', 'Social simulation and mystery solving.', 'Solve mysteries and stop a criminal organization as an agent.', 'Secret agent-themed spin-off of the MySims series.', 'MySims Agents (Europe) takes the building mechanics of MySims and adds a layer of detective work. Interrogate suspects, search for clues, and recruit a team of agents to stop the evil Morcubus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---agents-usa-enfres', 'NDS', 'MySims - Agents (USA) (En,Fr,Es)', '2009', 'Simulation', 'Maxis', '1', 'Adventure Simulation', 'Social simulation and mystery solving.', 'Solve mysteries and stop a criminal organization as an agent.', 'North American release of the MySims agent game.', 'Become a special agent in MySims Agents (USA). Use high-tech gadgets to solve puzzles, customize your headquarters, and explore a variety of locations while uncovering a massive mystery in this charming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---kingdom-europe-enfrdeesitnlptsvplcshu', 'NDS', 'MySims - Kingdom (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,Pl,Cs,Hu)', '2008', 'Simulation', 'Maxis', '1', 'Adventure Simulation', 'Construction and social simulation in a medieval setting.', 'Help King Roland rebuild his kingdom through creative building.', 'Medieval-themed building adventure for Europe.', 'MySims Kingdom (Europe) invites you to a land of knights and magic. Use the "Essence" system to build houses and furniture, solve puzzles for quirky citizens, and restore the glory of the kingdom in this charming multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---kingdom-usa-enfres', 'NDS', 'MySims - Kingdom (USA) (En,Fr,Es)', '2008', 'Simulation', 'Maxis', '1', 'Adventure Simulation', 'Construction and social simulation in a medieval setting.', 'Help King Roland rebuild his kingdom through creative building.', 'North American release of the MySims medieval sim.', 'Embark on a royal quest in MySims Kingdom (USA). Unlike the Wii version, the DS edition features a unique storyline and exclusive mini-games, allowing you to travel to various islands and help local Sims with your construction skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---party-europe-enfrdeesitnlpt', 'NDS', 'MySims - Party (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2009', 'Party', 'Maxis', '1', 'Party Mini-Games', 'Minigame collection and party simulation.', 'Compete in over 50 mini-games to win the festival.', 'Fast-paced party game starring the MySims cast.', 'MySims Party (Europe) brings the festival to your handheld. Compete in diverse challenges that test your speed and coordination, managing your team of Sims to unlock new characters and decorations in this fun social title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---party-usa-enfres', 'NDS', 'MySims - Party (USA) (En,Fr,Es)', '2009', 'Party', 'Maxis', '1', 'Party Mini-Games', 'Minigame collection and party simulation.', 'Compete in over 50 mini-games to win the festival.', 'North American release of the MySims party game.', 'Join the celebration in MySims Party (USA). Each Sim has unique stats that affect their performance in mini-games, requiring strategic team-building to conquer the competition and bring life back to the town''s festivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---racing-europe-enfrdeesitnl', 'NDS', 'MySims - Racing (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Racing', 'Maxis', '1', 'Arcade Racing', 'Kart racing and vehicle customization.', 'Win races and customize your car to defeat rivals.', 'High-speed racing adventure in the MySims world.', 'MySims Racing (Europe) combines arcade racing with deep customization. Build your car from the ground up, use wacky power-ups to gain an advantage, and compete in a story-driven campaign to become the best racer in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---racing-usa-enfres', 'NDS', 'MySims - Racing (USA) (En,Fr,Es)', '2009', 'Racing', 'Maxis', '1', 'Arcade Racing', 'Kart racing and vehicle customization.', 'Win races and customize your car to defeat rivals.', 'North American release of the MySims racer.', 'Speed through vibrant tracks in MySims Racing (USA). Face off against Morcubus and his cronies, upgrading your vehicle''s engine and body to handle increasingly difficult tracks in this creative take on the kart racing genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---simdeurui-wangguk-korea', 'NDS', 'MySims - Simdeurui Wangguk (Korea)', '2008', 'Simulation', 'Maxis', '1', 'Adventure Simulation', 'Construction and social simulation in a medieval setting.', 'Help King Roland rebuild his kingdom through creative building.', 'Korean version of MySims Kingdom.', 'Experience the medieval building adventure in Korean. MySims Kingdom (Korea) features the same engaging story and touch-screen building mechanics, allowing players to revitalize a fantasy world and interact with a cast of colorful Sims.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---skyheroes-europe-enfrdeesitnl', 'NDS', 'MySims - SkyHeroes (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action', 'Maxis', '1', 'Aerial Combat', 'Aerial combat and flight simulation.', 'Defeat Morcubus in epic sky battles to save the world.', 'Action-packed flight combat starring MySims.', 'MySims SkyHeroes (Europe) takes the series to the clouds. Customize your plane with powerful weapons and wings, engaging in both high-speed dogfights and precision racing missions across beautifully designed airborne environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims---skyheroes-usa-enfrdeesitnl', 'NDS', 'MySims - SkyHeroes (USA) (En,Fr,De,Es,It,Nl)', '2010', 'Action', 'Maxis', '1', 'Aerial Combat', 'Aerial combat and flight simulation.', 'Defeat Morcubus in epic sky battles to save the world.', 'North American release of the MySims flight game.', 'Take flight in MySims SkyHeroes (USA). As a resistance pilot, you must master the skies to stop an evil empire, featuring a robust campaign and local wireless multiplayer for intense aerial combat with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims-europe-enfrdeesitnl', 'NDS', 'MySims (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Construction and social simulation.', 'Rebuild a dilapidated town and attract new residents.', 'The original MySims experience for Europe.', 'MySims (Europe) puts you in charge of a struggling town. Use the touch screen to build houses and furniture, satisfy the creative requests of your neighbors, and unlock new areas as the town''s "Star Level" increases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims-korea', 'NDS', 'MySims (Korea)', '2008', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Construction and social simulation.', 'Rebuild a dilapidated town and attract new residents.', 'Korean version of the original MySims.', 'Build the town of your dreams in Korean. MySims (Korea) offers the full creative experience, allowing players to design everything from roofs to chairs in a vibrant, chibi-style world optimized for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysims-usa-enfres', 'NDS', 'MySims (USA) (En,Fr,Es)', '2008', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Construction and social simulation.', 'Rebuild a dilapidated town and attract new residents.', 'North American release of the first MySims game.', 'Unleash your creativity in MySims (USA). By collecting "Essences" from the environment, you can build unique structures and items, turning a quiet village into a bustling city filled with interesting and diverse characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('myst-europe-enfrde', 'NDS', 'Myst (Europe) (En,Fr,De)', '2007', 'Adventure', 'Cyan Worlds', '1', 'Point-and-Click', 'Point-and-click puzzle adventure.', 'Uncover the mystery of the ages and escape the island.', 'The classic PC adventure adapted for Europe.', 'Myst (Europe) brings the legendary island to the DS. Navigate static 3D environments, solve complex mechanical puzzles, and piece together the story of Atrus and his sons in this portable version of the iconic mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('myst-usa-enfr', 'NDS', 'Myst (USA) (En,Fr)', '2007', 'Adventure', 'Cyan Worlds', '1', 'Point-and-Click', 'Point-and-click puzzle adventure.', 'Uncover the mystery of the ages and escape the island.', 'North American release of the legendary puzzle game.', 'Experience the atmosphere of the Ages in Myst (USA). Use the stylus to interact with the environment and solve the cryptic puzzles that made this game a global phenomenon, now playable in the palm of your hand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('myst-usa-enfr-rev-1', 'NDS', 'Myst (USA) (En,Fr) (Rev 1)', '2007', 'Adventure', 'Cyan Worlds', '1', 'Point-and-Click', 'Point-and-click puzzle adventure.', 'Uncover the mystery of the ages and escape the island.', 'Improved revision of the DS puzzle classic.', 'Myst (USA) Rev 1 includes minor bug fixes and technical optimizations over the original release. It offers a more stable experience as you explore the surreal landscapes and intricate lore of the Myst universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysterious-adventures-in-the-caribbean-europe-endenl', 'NDS', 'Mysterious Adventures in the Caribbean (Europe) (En,De,Nl)', '2008', 'Adventure', 'Revistronic', '1', 'Hidden Object', 'Hidden object adventure with a pirate theme.', 'Find hidden treasures and solve puzzles in the Caribbean.', 'Atmospheric hidden object mystery for Europe.', 'Mysterious Adventures in the Caribbean takes you on a high-seas journey. Search detailed scenes for clues and artifacts to break an ancient curse in this relaxing and visually engaging puzzle title for European players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysterious-case-of-dr-jekyll-&-mr-hyde-the-europe', 'NDS', 'Mysterious Case of Dr. Jekyll & Mr. Hyde, The (Europe)', '2008', 'Adventure', 'Oxygen Games', '1', 'Detective Adventure', 'Hidden object and puzzle adventure.', 'Solve the dual mystery of the doctor and his alter ego.', 'Atmospheric Victorian mystery for Europe.', 'The Mysterious Case of Dr. Jekyll & Mr. Hyde puts you in the role of an investigator in London. Search for hidden objects and solve logic puzzles to uncover the truth behind the famous literary tragedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysterious-case-of-dr-jekyll-&-mr-hyde-the-europe-frde', 'NDS', 'Mysterious Case of Dr. Jekyll & Mr. Hyde, The (Europe) (Fr,De)', '2008', 'Adventure', 'Oxygen Games', '1', 'Detective Adventure', 'Hidden object and puzzle adventure.', 'Solve the dual mystery of the doctor and his alter ego.', 'German/French edition of the Jekyll & Hyde mystery.', 'Explore the dark streets of London in this localized edition. Featuring haunting environments and challenging puzzles, it brings the classic Gothic tale to life through engaging hidden object gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mysterious-case-of-dr-jekyll-&-mr-hyde-the-europe-frnl', 'NDS', 'Mysterious Case of Dr. Jekyll & Mr. Hyde, The (Europe) (Fr,Nl)', '2008', 'Adventure', 'Oxygen Games', '1', 'Detective Adventure', 'Hidden object and puzzle adventure.', 'Solve the dual mystery of the doctor and his alter ego.', 'French/Dutch edition of the Jekyll & Hyde mystery.', 'Uncover the secrets of the laboratory in this multi-language version. Use your observation skills to find clues and solve the mystery of the man with two faces in this portable investigative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-case-files---millionheir-europe-enfrdeesit', 'NDS', 'Mystery Case Files - MillionHeir (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Big Fish Games', '1', 'Hidden Object', 'Hidden object investigation with a royal twist.', 'Find the rightful heir to a massive fortune.', 'High-stakes hidden object mystery for Europe.', 'Mystery Case Files: MillionHeir (Europe) features interactive crime scenes. Use the stylus to poke, prod, and investigate environments to find hundreds of hidden items and solve the case of the missing millionaire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-case-files---millionheir-usa-enfres', 'NDS', 'Mystery Case Files - MillionHeir (USA) (En,Fr,Es)', '2008', 'Adventure', 'Big Fish Games', '1', 'Hidden Object', 'Hidden object investigation with a royal twist.', 'Find the rightful heir to a massive fortune.', 'North American release of the hit hidden object game.', 'Become a Master Detective in Mystery Case Files: MillionHeir (USA). With dozens of detailed locations and clever mini-games, it offers a deep and engaging mystery that utilizes the DS hardware in unique ways.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-detective-europe', 'NDS', 'Mystery Detective (Europe)', '2007', 'Adventure', 'Blue Giraffe', '1', 'Detective Adventure', 'Point-and-click adventure with a spooky theme.', 'Solve the bizarre mysteries of Oslow with Mackenzie.', 'Quirky and stylized detective adventure for Europe.', 'Known as "Touch Detective" in other regions, Mystery Detective (Europe) features beautiful hand-drawn art. Help the young detective solve strange cases involving dreams and shadows in this charmingly odd title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-detective-italy', 'NDS', 'Mystery Detective (Italy)', '2007', 'Adventure', 'Blue Giraffe', '1', 'Detective Adventure', 'Point-and-click adventure with a spooky theme.', 'Solve the bizarre mysteries of Oslow with Mackenzie.', 'Italian localized version of the detective game.', 'Experience the surreal world of Mackenzie in Italian. Mystery Detective combines traditional adventure gameplay with a unique aesthetic, tasking players with finding clues and talking to eccentric characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-detective-ii-italy', 'NDS', 'Mystery Detective II (Italy)', '2008', 'Adventure', 'Blue Giraffe', '1', 'Detective Adventure', 'Point-and-click adventure with a spooky theme.', 'Solve even more bizarre cases with Mackenzie and Funghi.', 'Italian version of the detective sequel.', 'Mystery Detective II (Italy) returns with more surreal mysteries. Use Mackenzie''s "touch" to investigate scenes and solve puzzles with the help of her loyal mushroom sidekick in this atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-dungeon---shiren-the-wanderer-europe', 'NDS', 'Mystery Dungeon - Shiren the Wanderer (Europe)', '2008', 'RPG', 'Chunsoft', '1', 'Roguelike RPG', 'Roguelike turn-based dungeon crawler.', 'Reach the top of Table Mountain to find the Golden Condor.', 'Challenging and deep roguelike for Europe.', 'Mystery Dungeon: Shiren the Wanderer (Europe) is a remake of the SNES classic. Navigate randomly generated floors, manage your hunger, and survive deadly monsters in this punishing but rewarding tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-dungeon---shiren-the-wanderer-usa', 'NDS', 'Mystery Dungeon - Shiren the Wanderer (USA)', '2008', 'RPG', 'Chunsoft', '1', 'Roguelike RPG', 'Roguelike turn-based dungeon crawler.', 'Reach the top of Table Mountain to find the Golden Condor.', 'North American release of the hardcore roguelike.', 'Every death is a new beginning in Shiren the Wanderer (USA). Master the complex item system and learn enemy patterns to conquer the dungeon, featuring updated graphics and new content for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-mansion-europe-enfrdeesit', 'NDS', 'Mystery Mansion (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Broken Rules', '1', 'Mystery Adventure', 'Hidden object mystery in a spooky manor.', 'Solve the secrets of the mansion and find the truth.', 'Classic hidden object game set in a haunted house.', 'Mystery Mansion (Europe) challenges your observation skills. Search through eerie rooms filled with clutter to find specific items, solving puzzles to unlock new areas and progress through the manor''s dark history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-pi---portrait-of-a-thief-usa', 'NDS', 'Mystery P.I. - Portrait of a Thief (USA)', '2009', 'Adventure', 'Big Fish Games', '1', 'Hidden Object', 'Hidden object investigation and crime solving.', 'Recover stolen art and catch a master thief.', 'Professional investigative hidden object game.', 'Mystery P.I. - Portrait of a Thief (USA) puts you on the trail of a sophisticated criminal. Search diverse locations across the city, finding thousands of cleverly hidden items to solve the crime and earn your detective badge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-stories-europe-enfrdenl', 'NDS', 'Mystery Stories (Europe) (En,Fr,De,Nl)', '2008', 'Adventure', 'Tivola', '1', 'Mystery Adventure', 'Adventure and puzzle solving.', 'Solve various mysteries across a series of short stories.', 'Collection of investigative adventure tales for Europe.', 'Mystery Stories (Europe) offers a variety of cases to crack. Use your deductive skills and the DS touch screen to examine evidence and interview witnesses in this engaging anthology of portable mysteries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mystery-tales---time-travel-europe-enfrdeesitnl', 'NDS', 'Mystery Tales - Time Travel (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Adventure', 'Big Fish Games', '1', 'Hidden Object', 'Time-traveling hidden object adventure.', 'Solve mysteries across different historical eras.', 'Unique time-traveling puzzle game for Europe.', 'Mystery Tales: Time Travel (Europe) takes you through history. Find hidden objects in the past and future to fix the timeline, featuring beautiful artwork and challenging logic puzzles that span across the ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('n+-usa', 'NDS', 'N+ (USA)', '2008', 'Platformer', 'Metanet Software', '1', 'Precision Platformer', 'Fast-paced 2D platformer with physics mechanics.', 'Reach the exit of each level while avoiding deadly traps.', 'Hardcore precision platformer with minimalist style.', 'N+ (USA) is the ultimate test of reflexes. Control a nimble ninja through hundreds of levels filled with mines, lasers, and robots, utilizing momentum and physics-based movement to survive in this addictive cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nacho-libre-europe-enfrde', 'NDS', 'Nacho Libre (Europe) (En,Fr,De)', '2006', 'Action', 'High Voltage Software', '1', 'Action-Adventure', 'Comedic wrestling and mini-games.', 'Rise through the ranks of Lucha Libre to save the orphanage.', 'Wacky wrestling based on the Jack Black movie.', 'Nacho Libre (Europe) features "Photorealism" style graphics from the film. Engage in over-the-top wrestling matches and hilarious mini-games as Nacho or Esqueleto in this multi-language portable brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nacho-libre-usa', 'NDS', 'Nacho Libre (USA)', '2006', 'Action', 'High Voltage Software', '1', 'Action-Adventure', 'Comedic wrestling and mini-games.', 'Rise through the ranks of Lucha Libre to save the orphanage.', 'North American release of the Lucha Libre game.', 'Experience the quest for glory in Nacho Libre (USA). Use the touch screen to execute signature moves and pin your opponents, featuring local wireless multiplayer to wrestle against your friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nadia---megafun-land-europe-enfr', 'NDS', 'Nadia - Megafun Land (Europe) (En,Fr)', '2005', 'Educational', 'Unknown', '1', 'Educational', 'Mini-game collection and theme park sim.', 'Enjoy a day at the "Megafun Land" with Nadia.', 'Fun and educational theme park adventure.', 'Nadia - Megafun Land (Europe) is designed for young players. Explore a vibrant amusement park and participate in various mini-games that focus on logic, reflexes, and coordination in a bilingual environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nadias-world-europe-enfres', 'NDS', 'Nadia''s World (Europe) (En,Fr,Es)', '2006', 'Educational', 'Unknown', '1', 'Educational', 'Educational exploration and mini-games.', 'Travel the world and learn about different cultures.', 'Cultural exploration and learning game for kids.', 'Nadia''s World (Europe) takes players on a global journey. Learn interesting facts about geography and traditions while completing puzzles and activities guided by Nadia in this multi-language educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakamura-akira-kanshuu---india-shiki-keisan-drill-ds-japan', 'NDS', 'Nakamura Akira Kanshuu - India Shiki Keisan Drill DS (Japan)', '2006', 'Educational', 'Success', '1', 'Educational', 'Educational math drills and logic.', 'Master the "Indian Method" of rapid mental calculation.', 'Intensive mental arithmetic trainer based on Indian math.', 'India Shiki Keisan Drill DS teaches the famous methods of Indian mathematics. Improve your calculation speed and accuracy through daily exercises that focus on multiplication and advanced mental shortcuts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakamura-sumiko-tettei-shidou---shin-toeic-test-1-nichi-1-pun-ds-lesson---1-shuukan-shuuchuu-program-tsuki-japan', 'NDS', 'Nakamura Sumiko Tettei Shidou - Shin TOEIC Test 1-nichi 1-pun DS Lesson - 1-shuukan Shuuchuu Program Tsuki (Japan)', '2007', 'Educational', 'Success', '1', 'Educational', 'Educational TOEIC test preparation.', 'Improve your TOEIC score with "1-minute" daily lessons.', 'Intensive English proficiency trainer for Japan.', 'Nakamura Sumiko Tettei Shidou offers a 1-week concentrated program for TOEIC aspirants. It features quick, high-impact lessons on grammar and listening, perfect for busy professionals on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-all-stars---mezase-gakuen-idol-japan', 'NDS', 'Nakayoshi All-Stars - Mezase Gakuen Idol (Japan)', '2008', 'Adventure', 'Konami', '1', 'Visual Novel', 'Social simulation and RPG.', 'Become the most popular idol at the Nakayoshi Academy.', 'Idol simulation featuring Nakayoshi manga stars.', 'Nakayoshi All-Stars brings together iconic characters from the famous manga magazine. Socialize, participate in school activities, and manage your schedule to rise to the top of the idol rankings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naked-brothers-band-the---the-video-game-usa', 'NDS', 'Naked Brothers Band, The - The Video Game (USA)', '2007', 'Action', 'Backbone Entertainment', '1', 'Action-Adventure', 'Rhythm action and music simulation.', 'Lead the band through a successful world tour.', 'Music game based on the Nickelodeon TV series.', 'The Naked Brothers Band (USA) allows you to play multiple instruments. Follow the rhythm to perform hits, customize the stage, and manage the band’s tour in this fan-focused musical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namanui-collection---girls-style-korea', 'NDS', 'Namanui Collection - Girls Style (Korea)', '2009', 'Simulation', 'Unknown', '1', 'Life Simulation', 'Fashion simulation and boutique management.', 'Run a successful fashion shop and style your customers.', 'Korean version of the popular Girls Style (Style Savvy).', 'Namanui Collection: Girls Style allows Korean players to become fashion moguls. Manage your inventory, coordinate outfits for picky clients, and participate in fashion contests to dominate the industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-ds-europe-enfrdeesit', 'NDS', 'Namco Museum DS (Europe) (En,Fr,De,Es,It)', '2007', 'Compilation', 'Namco', '1', 'Arcade Compilation', 'Arcade classic collection.', 'Play legendary Namco titles like Pac-Man and Galaga.', 'Definitive retro collection for the NDS.', 'Namco Museum DS (Europe) features pixel-perfect ports of arcade classics. It also includes "Pac-Man VS.," a unique multiplayer experience designed by Shigeru Miyamoto that utilizes the DS Download Play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-ds-japan', 'NDS', 'Namco Museum DS (Japan)', '2007', 'Compilation', 'Namco', '1', 'Arcade Compilation', 'Arcade classic collection.', 'Play legendary Namco titles like Pac-Man and Galaga.', 'Japanese release of the iconic Namco compilation.', 'Revisit the golden age of arcades with Namco Museum DS (Japan). Featuring a customizable arcade interface and a library of 7 classic games, it’s a must-have for retro gaming enthusiasts in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-ds-usa', 'NDS', 'Namco Museum DS (USA)', '2007', 'Compilation', 'Namco', '1', 'Arcade Compilation', 'Arcade classic collection.', 'Play legendary Namco titles like Pac-Man and Galaga.', 'North American release of the Namco classics.', 'Namco Museum DS (USA) brings the arcade to your pocket. Master your high scores in Mappy, Dig Dug, and Xevious, and enjoy wireless multiplayer modes with only one game card required.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nana---live-staff-daiboshuu!-shoshinsha-kangei-japan', 'NDS', 'NANA - Live Staff Daiboshuu! Shoshinsha Kangei (Japan)', '2007', 'Adventure', 'Konami', '1', 'Visual Novel', 'Visual novel and social adventure.', 'Work as a live staff member for the band NANA.', 'Adventure game based on the legendary NANA manga.', 'NANA - Live Staff Daiboshuu! immerses you in the punk-rock world of Nana Osaki and Nana Komatsu. Interact with characters, manage concert logistics, and experience a unique story set in the NANA universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanashi-no-geemu-japan', 'NDS', 'Nanashi no Geemu (Japan)', '2008', 'Horror', 'Takuyo', '1', 'Horror Adventure', 'Psychological horror and retro mini-games.', 'Survive a cursed mobile game and uncover the mystery.', 'Terrifying "cursed game" experience from Square Enix.', 'Nanashi no Geemu (The Nameless Game) blends 3D exploration with 8-bit style "cursed" mini-games. Solve the mystery of a game that kills its players in seven days in this chilling Japanese horror title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanashi-no-geemu-me-japan', 'NDS', 'Nanashi no Geemu Me (Japan)', '2009', 'Horror', 'Takuyo', '1', 'Horror Adventure', 'Psychological horror and retro mini-games.', 'Survive the new curse and solve the urban legend.', 'The haunting sequel to Nanashi no Geemu.', 'Nanashi no Geemu Me (The Nameless Game: Eye) expands the horror with a dual-screen focus. Navigate spooky environments while playing corrupted 8-bit RPG segments that bleed into the real world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanatsuiro-drops-ds---touch-de-hajimaru-hatsukoi-monogatari-japan', 'NDS', 'Nanatsuiro Drops DS - Touch de Hajimaru Hatsukoi Monogatari (Japan)', '2007', 'Romance', 'Media Factory', '1', 'Visual Novel', 'Visual novel and dating simulation.', 'Navigate high school life and find your first love.', 'Fantasy-romance visual novel based on the anime.', 'Nanatsuiro Drops DS features the "Touch-based first love story." Use the stylus to interact with characters and make choices that determine the outcome of this magical girl-themed romantic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-deadly-secret-of-olde-world-park-europe-enfrdeesit', 'NDS', 'Nancy Drew - The Deadly Secret of Olde World Park (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Point-and-click adventure and mystery.', 'Investigate strange occurrences at Olde World Park.', 'Nancy Drew''s first mystery adventure on the NDS.', 'Nancy Drew - The Deadly Secret of Olde World Park (Europe) tasks you with finding a missing billionaire. Search for clues, solve puzzles, and use Nancy''s detective skills in this multi-language investigative game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-deadly-secret-of-olde-world-park-usa', 'NDS', 'Nancy Drew - The Deadly Secret of Olde World Park (USA)', '2009', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Point-and-click adventure and mystery.', 'Investigate strange occurrences at Olde World Park.', 'North American release of the Olde World Park mystery.', 'Join Nancy Drew (USA) as she goes undercover to solve a kidnapping. This title emphasizes environmental investigation and logic puzzles, capturing the spirit of the classic book series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-hidden-staircase-usa', 'NDS', 'Nancy Drew - The Hidden Staircase (USA)', '2008', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Point-and-click adventure and mystery.', 'Uncover the secrets of a haunted mansion''s staircase.', 'Detective adventure based on the classic novel.', 'Nancy Drew - The Hidden Staircase (USA) takes the mystery to a spooky old house. Use your stylus to uncover hidden switches, solve riddles, and figure out who is behind the supernatural sightings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-model-mysteries-europe', 'NDS', 'Nancy Drew - The Model Mysteries (Europe)', '2009', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Hidden object and puzzle adventure.', 'Solve mysteries in the high-stakes world of fashion.', 'Fashion-themed Nancy Drew mystery for Europe.', 'Nancy Drew - The Model Mysteries (Europe) finds Nancy investigating sabotage on a reality TV set. Search for hidden objects and complete mini-games to clear the names of innocent models in this stylish mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-model-mysteries-usa', 'NDS', 'Nancy Drew - The Model Mysteries (USA)', '2009', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Hidden object and puzzle adventure.', 'Solve mysteries in the high-stakes world of fashion.', 'North American release of the Model Mysteries.', 'Step onto the runway in Nancy Drew - The Model Mysteries (USA). Balance your detective work with fashion tasks as you track down a culprit in the competitive world of modeling and design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-mystery-of-the-clue-bender-society-europe-enfrde', 'NDS', 'Nancy Drew - The Mystery of the Clue Bender Society (Europe) (En,Fr,De)', '2009', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Point-and-click adventure and mystery.', 'Solve a series of puzzles to join an elite detective society.', 'Puzzling mystery adventure for European players.', 'Nancy Drew - The Mystery of the Clue Bender Society (Europe) features complex logic puzzles and brain teasers. Prove your worth as a top investigator by solving the trials set by a secret organization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---the-mystery-of-the-clue-bender-society-usa', 'NDS', 'Nancy Drew - The Mystery of the Clue Bender Society (USA)', '2009', 'Adventure', 'Her Interactive', '1', 'Adventure', 'Point-and-click adventure and mystery.', 'Solve a series of puzzles to join an elite detective society.', 'North American release of the Clue Bender mystery.', 'Test your wits in Nancy Drew (USA). Travel to diverse locations and use Nancy’s logic to outsmart the Clue Bender Society in this mystery that emphasizes observation and critical thinking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nandas-island-europe-enfrdeesit', 'NDS', 'Nandas Island (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Genius Sonority', '1', 'Life Simulation', 'Puzzle and strategy game.', 'Guide Nanda through various environments to find water.', 'Unique environmental puzzle game for Europe.', 'Nandas Island (Europe) challenges you to manipulate the landscape. Guide the thirsty Nanda through levels by creating paths and solving water-based puzzles in this colorful and creative title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nandoku-kanji-ds---nandoku-yoji-jukugo-koji-kotowaza-japan', 'NDS', 'Nandoku Kanji DS - Nandoku, Yoji Jukugo, Koji Kotowaza (Japan)', '2006', 'Educational', 'Success', '1', 'Educational', 'Educational Kanji dictionary and testing.', 'Master difficult-to-read Kanji and Japanese idioms.', 'Comprehensive advanced Kanji trainer for Japan.', 'Nandoku Kanji DS focuses on the most challenging aspects of the Japanese language. Test your knowledge of rare readings, four-character idioms, and historical proverbs through interactive drills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nangoku-sodachi-ds-japan', 'NDS', 'Nangoku Sodachi DS (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Farming Simulation', 'Pachislot simulation.', 'Win big on the virtual "Nangoku Sodachi" slot machines.', 'Authentic Japanese Pachislot simulator.', 'Nangoku Sodachi DS brings the excitement of the parlor to the NDS. Experience realistic slot mechanics, unlock special animations, and manage your virtual credits in this faithful recreation of the popular machine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanostray-europe-enfrde', 'NDS', 'Nanostray (Europe) (En,Fr,De)', '2005', 'Shooter', 'Shin''en Multimedia', '1', 'Shoot ''em Up', 'Sci-fi shoot ''em up (Shmup).', 'Defeat alien armadas in high-speed 3D environments.', 'Visually stunning sci-fi shooter for Europe.', 'Nanostray (Europe) is a technical powerhouse for the DS. Engage in intense boss battles and navigate through beautifully rendered 3D levels, using various weapon systems to achieve the high score in this multi-language Shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanostray-usa', 'NDS', 'Nanostray (USA)', '2005', 'Shooter', 'Shin''en Multimedia', '1', 'Shoot ''em Up', 'Sci-fi shoot ''em up (Shmup).', 'Defeat alien armadas in high-speed 3D environments.', 'North American release of the acclaimed shooter.', 'Nanostray (USA) offers classic arcade action with a modern twist. Use the touch screen to manage your secondary weapons and track enemy stats while surviving waves of hostile forces in space and over futuristic cities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanostray-2-europe-enfrdeesit', 'NDS', 'Nanostray 2 (Europe) (En,Fr,De,Es,It)', '2008', 'Shooter', 'Shin''en Multimedia', '1', 'Shoot ''em Up', 'Sci-fi shoot ''em up (Shmup).', 'Stop the Nanostray virus across various planets.', 'The expanded and refined sequel to Nanostray.', 'Nanostray 2 (Europe) introduces "Adventure Mode" and improved ship customization. Fight through 12 unique stages with revamped controls and a deeper scoring system in this definitive handheld Shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanostray-2-usa', 'NDS', 'Nanostray 2 (USA)', '2008', 'Shooter', 'Shin''en Multimedia', '1', 'Shoot ''em Up', 'Sci-fi shoot ''em up (Shmup).', 'Stop the Nanostray virus across various planets.', 'North American release of the Shmup sequel.', 'Nanostray 2 (USA) raises the bar for DS shooters. Featuring massive bosses and intense "Challenge" modes, it provides a high-fidelity arcade experience that tests your reflexes and strategic weapon use.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanpure-10000-mon-japan', 'NDS', 'Nanpure 10000 Mon (Japan)', '2006', 'Puzzle', 'Success', '1', 'Number Puzzle', 'Sudoku puzzle collection.', 'Solve 10,000 unique Sudoku grids.', 'Massive Sudoku collection for the Japanese market.', 'Nanpure 10000 Mon is a must-have for puzzle fans. With four difficulty levels and an almost endless supply of grids, it turns the DS into the ultimate portable Sudoku book.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nanpure-vow-japan', 'NDS', 'Nanpure VOW (Japan)', '2007', 'Puzzle', 'Success', '1', 'Number Puzzle', 'Sudoku puzzle collection with a humorous twist.', 'Solve Sudoku grids curated by the "VOW" series.', 'Unique Sudoku collection with quirky trivia.', 'Nanpure VOW combines classic number puzzles with the humor of the VOW trivia series. Enjoy challenging Sudoku stages while reading funny anecdotes and bizarre facts from Japanese pop culture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('napoleon-dynamite---the-game-usa', 'NDS', 'Napoleon Dynamite - The Game (USA)', '2004', 'Action', 'Micro Fun', '1', 'Action-Adventure', 'Mini-game collection and adventure.', 'Help Napoleon achieve his goals through awkward tasks.', 'Quirky mini-game collection based on the cult film.', 'Napoleon Dynamite (USA) features "flippin'' sweet" mini-games. From sweet bike jumps to Liger drawing, experience the unique humor of the movie through a series of stylus-driven challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('narnia-koku-monogatari---lion-to-majo-japan', 'NDS', 'Narnia Koku Monogatari - Lion to Majo (Japan)', '2006', 'Action', 'Unknown', '1', 'Action-Adventure', 'Action-adventure based on the movie.', 'Save Narnia from the White Witch as the Pevensie siblings.', 'Japanese release of The Lion, the Witch and the Wardrobe.', 'Narnia Koku Monogatari takes you through the magic wardrobe. Switch between Peter, Susan, Edmund, and Lucy, each with unique abilities, to solve puzzles and fight the White Witch''s army in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('narnia-koku-monogatari-dai-2-shou---caspian-ouji-no-tsunobue-japan', 'NDS', 'Narnia Koku Monogatari Dai-2 Shou - Caspian Ouji no Tsunobue (Japan)', '2006', 'Action', 'Unknown', '1', 'Action-Adventure', 'Action-adventure based on the movie.', 'Help Prince Caspian reclaim his throne.', 'Japanese release of the Prince Caspian adventure.', 'Explore the world of Narnia hundreds of years later. Narnia Koku Monogatari Dai-2 Shou features expanded combat and more exploration, allowing players to join the Narnian rebellion against the Telmarines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---choegangninja-daegyeoljip-ds-korea', 'NDS', 'Naruto - Choegangninja Daegyeoljip DS (Korea)', '2006', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action and platforming.', 'Defeat enemies and bosses using ninja techniques.', 'Korean version of the Ninja Council series.', 'Naruto: Choegangninja Daegyeoljip DS brings fast-paced shinobi action to Korea. Control Naruto and his friends through hazard-filled levels, utilizing the touch screen to trigger powerful Jutsu and summon support characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-council---european-version-europe-enfrdeesit', 'NDS', 'Naruto - Ninja Council - European Version (Europe) (En,Fr,De,Es,It)', '2006', 'Action', 'Natsume', '1', 'Action Platformer', 'Side-scrolling action and platforming.', 'Complete missions across the Hidden Leaf Village.', 'The first Naruto adventure for DS in Europe.', 'Naruto: Ninja Council (European Version) features classic 2D platforming combat. Battle through the Chunin Exams arc, mastering the Rasengan and other iconic moves while switching between Naruto, Sasuke, and Sakura.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-council-2---european-version-europe-enfrdeesit', 'NDS', 'Naruto - Ninja Council 2 - European Version (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Natsume', '1', 'Action Platformer', 'Side-scrolling action and platforming.', 'Stop the Sound Ninja invasion and save the village.', 'Enhanced 2D action sequel for European fans.', 'Naruto: Ninja Council 2 (Europe) expands the roster and move sets. Explore larger levels and engage in intense multi-plane combat, featuring a variety of support characters and touch-screen mini-games to boost your power.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-council-3-usa', 'NDS', 'Naruto - Ninja Council 3 (USA)', '2007', 'Action', 'Natsume', '1', 'Action Platformer', 'Mission-based side-scrolling action.', 'Complete over 60 challenges and unlock new ninjas.', 'North American release of the tactical action game.', 'Naruto: Ninja Council 3 (USA) focuses on variety. Choose your team of three ninjas and tackle specific mission objectives, from defeating bosses to collecting items, with a huge roster of playable characters from the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-destiny---european-version-europe-enfrdeesit', 'NDS', 'Naruto - Ninja Destiny - European Version (Europe) (En,Fr,De,Es,It)', '2008', 'Fighting', 'Takara Tomy', '2', 'Arena Fighter', '3D arena fighting game.', 'Win 1v1 battles to progress through the story mode.', 'The first 3D Naruto fighter for the DS in Europe.', 'Naruto: Ninja Destiny (Europe) delivers fast-paced 3D combat. Use the touch screen to activate items and power-ups during fights, featuring a cinematic story mode that follows the search for Tsunade arc.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-destiny-usa-enfr', 'NDS', 'Naruto - Ninja Destiny (USA) (En,Fr)', '2008', 'Fighting', 'Takara Tomy', '2', 'Arena Fighter', '3D arena fighting game.', 'Defeat rivals in high-speed 3D ninja combat.', 'North American release of the 3D fighting hit.', 'Enter the arena in Naruto: Ninja Destiny (USA). Master combos and defensive maneuvers in a fully 3D environment, featuring a robust cast of shinobi and several gameplay modes including Arcade and Wireless Battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-destiny-ii---european-version-europe-enfrdeesit', 'NDS', 'Naruto - Ninja Destiny II - European Version (Europe) (En,Fr,De,Es,It)', '2010', 'Fighting', 'Takara Tomy', '2', 'Arena Fighter', '3D arena fighting game.', 'Master new techniques and defeat the Akatsuki.', 'Expanded 3D fighting sequel for Europe.', 'Naruto: Ninja Destiny II (Europe) features an improved roster including Shippuden characters. Experience a brand-new storyline and refined combat mechanics that make every 1v1 duel more strategic and visually impressive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---path-of-the-ninja-usa', 'NDS', 'Naruto - Path of the Ninja (USA)', '2008', 'RPG', 'TOSE', '1', 'Turn-Based RPG', 'Turn-based RPG with grid-based combat.', 'Follow the anime story through tactical battles.', 'The first Naruto RPG released in North America.', 'Naruto: Path of the Ninja (USA) offers a traditional RPG experience. Manage your team''s equipment and stamina, using a unique grid-based battle system where positioning is key to executing powerful team-up attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---path-of-the-ninja-2-usa-enfr', 'NDS', 'Naruto - Path of the Ninja 2 (USA) (En,Fr)', '2010', 'RPG', 'TOSE', '1', 'Turn-Based RPG', 'Turn-based RPG with grid-based combat.', 'Stop a new threat in an original Naruto story.', 'Deep RPG sequel with a massive character roster.', 'Naruto: Path of the Ninja 2 (USA) features over 30 playable characters. Travel across the ninja world in a sprawling adventure that combines classic RPG exploration with intense, tactical turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---saikyou-ninja-daikesshuu-3-for-ds-japan', 'NDS', 'Naruto - Saikyou Ninja Daikesshuu 3 for DS (Japan)', '2006', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action and platforming.', 'Complete the mission as the best ninja.', 'Japanese original of the Ninja Council series.', 'Naruto: Saikyou Ninja Daikesshuu 3 brings high-energy 2D action to the DS. Use the stylus to draw symbols for Jutsu and navigate complex levels filled with rival ninjas and environmental traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---saikyou-ninja-daikesshuu-4-ds-japan', 'NDS', 'Naruto - Saikyou Ninja Daikesshuu 4 DS (Japan)', '2007', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action and platforming.', 'Defeat the Sound Ninja and rescue Sasuke.', 'Fourth installment of the Japanese action series.', 'This title features expanded team mechanics and larger sprites. Coordinate attacks with your allies and use the dual-screen setup to keep track of the map and your health while fighting through iconic anime locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---shinobi-retsuden-japan', 'NDS', 'Naruto - Shinobi Retsuden (Japan)', '2007', 'Action', 'Takara Tomy', '1', 'Action Adventure', '3D arena fighting game.', 'Fight through the ninja ranks in full 3D.', 'The Japanese debut of the Shinobi Retsuden series.', 'Naruto: Shinobi Retsuden is a pioneer of 3D fighting on the DS. It features a unique control scheme optimized for the handheld, allowing for fluid movement and spectacular special moves in a portable 3D arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-jilpungjeon---choegangninja-daegyeoljip-2---gyeokttol!!-naruto-vs-sasuke-korea', 'NDS', 'Naruto Jilpungjeon - Choegangninja Daegyeoljip 2 - Gyeokttol!! Naruto vs Sasuke (Korea)', '2007', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action and platforming.', 'Battle through the start of the Shippuden era.', 'Korean version of the Naruto vs Sasuke action game.', 'Naruto Jilpungjeon: Choegangninja Daegyeoljip 2 features the older, more powerful Naruto. Experience the emotional rivalry with Sasuke through high-stakes 2D combat and refined touch-screen controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-jilpungjeon---daenantu!-geurimja-bunsinsul-korea', 'NDS', 'Naruto Jilpungjeon - Daenantu! Geurimja Bunsinsul (Korea)', '2008', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action with clones.', 'Use shadow clones to defeat massive groups of enemies.', 'Korean version of the Kagebunshin action game.', 'This unique title focuses on Naruto''s signature move. Control dozens of shadow clones simultaneously to solve puzzles and overwhelm enemies in a fast-paced, side-scrolling adventure localized for Korea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-rpg-2---chidori-vs-rasengan-japan', 'NDS', 'Naruto RPG 2 - Chidori vs Rasengan (Japan)', '2005', 'RPG', 'Aspect', '1', 'Turn-Based RPG', 'Turn-based RPG with grid-based combat.', 'Master the clash between Chidori and Rasengan.', 'The second Naruto RPG entry for Japan.', 'Naruto RPG 2 features a deep story covering the Sasuke Retrieval arc. Manage your chakra and health while exploring detailed environments and engaging in strategic battles with beautifully animated sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-rpg-3---reijuu-vs-konoha-shoutai-japan', 'NDS', 'Naruto RPG 3 - Reijuu vs Konoha Shoutai (Japan)', '2006', 'RPG', 'Aspect', '1', 'Turn-Based RPG', 'Turn-based RPG with grid-based combat.', 'Lead the Konoha squad against ancient spirits.', 'The third and final classic Naruto RPG for Japan.', 'Naruto RPG 3 introduces legendary beasts and a massive team-building system. Explore the world of Naruto with unprecedented depth, featuring a refined battle system and dozens of hours of RPG content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuden---naruto-vs-sasuke-europe-frit', 'NDS', 'Naruto Shippuden - Naruto vs Sasuke (Europe) (Fr,It)', '2008', 'Fighting', 'Takara Tomy', '2', 'Arena Fighter', 'Side-scrolling action and platforming.', 'Relive the iconic showdown between Naruto and Sasuke.', 'French/Italian release of the Shippuden action game.', 'Naruto Shippuden: Naruto vs Sasuke (Europe) focuses on the early Shippuden arcs. Play as various members of the Hidden Leaf and the Akatsuki in fast-paced 2D levels designed for fans of high-octane action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuden---naruto-vs-sasuke-usa', 'NDS', 'Naruto Shippuden - Naruto vs Sasuke (USA)', '2008', 'Fighting', 'Takara Tomy', '2', 'Arena Fighter', 'Side-scrolling action and platforming.', 'Relive the iconic showdown between Naruto and Sasuke.', 'North American release of the Shippuden 2D fighter.', 'Battle through intense stages in Naruto Shippuden: Naruto vs Sasuke (USA). Use the touch screen to call in reinforcements and unleash devastating ultimate Jutsu in this faithful adaptation of the hit anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuden---ninja-council-3---european-version-europe-enfrdeesit', 'NDS', 'Naruto Shippuden - Ninja Council 3 - European Version (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'Natsume', '1', 'Action Platformer', 'Mission-based side-scrolling action.', 'Complete missions during the Shippuden era.', 'European release of the third Ninja Council game.', 'This version brings the Shippuden cast to the Ninja Council formula. Featuring localized text for 5 languages, it offers a challenging mission mode and a huge variety of playable characters with unique abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuden---ninja-council-4-usa-enfres', 'NDS', 'Naruto Shippuden - Ninja Council 4 (USA) (En,Fr,Es)', '2009', 'Action', 'Natsume', '1', 'Action Platformer', 'Mission-based side-scrolling action.', 'Stop the Akatsuki and complete secret missions.', 'Fourth North American entry in the Ninja Council series.', 'Naruto Shippuden: Ninja Council 4 (USA) features a revamped combat system and 4-player wireless battles. Navigate massive levels and use the touch screen to perform signature Shippuden-era techniques.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuden---ninja-destiny-2-usa', 'NDS', 'Naruto Shippuden - Ninja Destiny 2 (USA)', '2010', 'Fighting', 'Takara Tomy', '2', 'Arena Fighter', '3D arena fighting game.', 'Battle through the Shippuden storyline in 3D.', 'North American release of the second Destiny title.', 'Naruto Shippuden: Ninja Destiny 2 (USA) features an original storyline alongside the anime plot. Enjoy refined 3D visuals and a roster of 25 characters, each with their own unique fighting style and ultimate moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuu-den---dairansen!-kagebunshin-emaki-japan', 'NDS', 'Naruto Shippuu Den - Dairansen! Kagebunshin Emaki (Japan)', '2008', 'Action', 'Takara Tomy', '1', 'Action Scroll', 'Side-scrolling action with clones.', 'Use shadow clones to defeat massive groups of enemies.', 'The Japanese version of the shadow clone adventure.', 'Naruto Shippuu Den: Dairansen! Kagebunshin Emaki utilizes the DS stylus to command a small army of clones. Solve environmental puzzles and engage in large-scale brawls in this unique and creative action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuu-den---ninjutsu-zenkai!-chaclash!!-japan', 'NDS', 'Naruto Shippuu Den - Ninjutsu Zenkai! Chaclash!! (Japan)', '2009', 'Action', 'Takara Tomy', '1', 'Action Scroll', 'High-speed 2D fighting game.', 'Win 1v1 ninja matches with high-speed combos.', 'Competitive 2D fighter for the Japanese market.', 'This title focuses on pure fighting mechanics. Ninjutsu Zenkai! Chaclash!! features large, detailed character sprites and a complex combo system that rewards precision and timing in every duel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuu-den---saikyou-ninja-daikesshuu---gekitotsu!!-naruto-vs-sasuke-japan', 'NDS', 'Naruto Shippuu Den - Saikyou Ninja Daikesshuu - Gekitotsu!! Naruto vs Sasuke (Japan)', '2009', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action and platforming.', 'Battle through the early Shippuden story.', 'Japanese version of the Naruto vs Sasuke game.', 'Experience the intense 2D action of Saikyou Ninja Daikesshuu. This entry features a massive amount of support characters and secret paths, making it a highly replayable title for Naruto fans in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuu-den---saikyou-ninja-daikesshuu-5---kessen!-akatsuki-japan', 'NDS', 'Naruto Shippuu Den - Saikyou Ninja Daikesshuu 5 - Kessen! ''Akatsuki'' (Japan)', '2010', 'Action', 'TOMY', '1', 'Fighting', 'Side-scrolling action and platforming.', 'Defeat the Akatsuki in the ultimate showdown.', 'The fifth and final 2D action game for Japan.', 'Kessen! ''Akatsuki'' is the culmination of the 2D action series. Play as almost every major hero and villain in the series, featuring spectacular boss fights and a deep, multi-path story mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuu-den---shinobi-retsuden-ii-japan', 'NDS', 'Naruto Shippuu Den - Shinobi Retsuden II (Japan)', '2008', 'Action', 'Takara Tomy', '1', 'Action Adventure', '3D arena fighting game.', 'Master the 3D battlefield with Shippuden characters.', 'The second 3D fighter entry for the Japanese market.', 'Shinobi Retsuden II improves upon every aspect of the first game. With better graphics, a larger roster, and more fluid controls, it’s one of the most solid 3D fighting experiences available on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-shippuu-den---shinobi-retsuden-iii-japan', 'NDS', 'Naruto Shippuu Den - Shinobi Retsuden III (Japan)', '2009', 'Action', 'Takara Tomy', '1', 'Action Adventure', '3D arena fighting game.', 'Win the ultimate ninja tournament in 3D.', 'The third and final 3D fighter for Japan.', 'Shinobi Retsuden III is the definitive version of the 3D series. It features a massive roster including late-Shippuden characters and optimized gameplay that pushes the DS hardware to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nathan-anglais---methode-pratique-france', 'NDS', 'Nathan Anglais - Methode Pratique (France)', '2010', 'Action', 'Takara Tomy', '1', 'Action Adventure', 'Educational English learning.', 'Master English vocabulary and grammar through practice.', 'Practical English learning method for French speakers.', 'Nathan Anglais: Methode Pratique offers a structured curriculum for learning English. Use interactive exercises and audio clips to improve your pronunciation and understanding in this specialized educational tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nathan-entrainement-6e-france', 'NDS', 'Nathan Entrainement 6e (France)', '2008', 'Educational', 'Nathan', '1', 'Language Learning', 'Educational middle school prep.', 'Review key subjects for the 6th grade curriculum.', 'Comprehensive 6th grade educational trainer.', 'Nathan Entrainement 6e is designed to help French students transition to middle school. It covers math, French, and history through thousands of exercises that follow the national school program.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nathan-entrainement-ce1-france', 'NDS', 'Nathan Entrainement CE1 (France)', '2009', 'Educational', 'Nathan', '1', 'Educational', 'Educational elementary school prep.', 'Master basic reading, writing, and arithmetic for CE1.', 'Educational trainer for the second year of primary school.', 'This title provides a fun way for young students to practice their schoolwork. Nathan Entrainement CE1 uses mini-games and rewards to encourage children to master the fundamentals of the French curriculum.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nathan-entrainement-ce2-france', 'NDS', 'Nathan Entrainement CE2 (France)', '2009', 'Educational', 'Nathan', '1', 'Educational', 'Educational elementary school prep.', 'Review the 3rd year primary school curriculum (CE2).', 'Educational trainer for the third year of primary school.', 'Nathan Entrainement CE2 focuses on building a solid foundation in grammar and advanced arithmetic. It tracks student progress and adapts difficulty to ensure a balanced learning experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nathan-entrainement-cm1-france', 'NDS', 'Nathan Entrainement CM1 (France)', '2009', 'Educational', 'Nathan', '1', 'Educational', 'Educational elementary school prep.', 'Master the 4th year primary school subjects (CM1).', 'Educational trainer for the fourth year of primary school.', 'As school gets harder, CM1 helps students keep up. This Nathan trainer provides detailed explanations and interactive drills for complex math problems and French literature for older elementary students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nathan-entrainement-cm2-france', 'NDS', 'Nathan Entrainement CM2 (France)', '2009', 'Educational', 'Nathan', '1', 'Educational', 'Educational elementary school prep.', 'Prepare for the transition to middle school (CM2).', 'Comprehensive 5th year primary school trainer.', 'Nathan Entrainement CM2 is the final step in the elementary series. It ensures students are ready for the next level by reinforcing all key subjects through a series of challenging and engaging digital lessons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('national-geographic---panda-usa-enfr', 'NDS', 'National Geographic - Panda (USA) (En,Fr)', '2008', 'Educational', 'National Geographic', '1', 'Interactive Documentary', 'Panda simulation and education.', 'Care for a panda cub and learn about the species.', 'National Geographic-branded panda simulation.', 'National Geographic: Panda (USA) lets you nurture a panda in a realistic 3D environment. Feed, play, and interact with your cub while accessing exclusive National Geographic photos and educational facts about panda conservation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazonazo-&-quiz---ittou-nyuukon-q-mate!-japan', 'NDS', 'Nazonazo & Quiz - Ittou Nyuukon Q Mate! (Japan)', '2007', 'Puzzle', 'Success', '1', 'Quiz Puzzle', 'Quiz and trivia.', 'Answer puzzles and riddles to win the championship.', 'Competitive quiz and riddle game for Japan.', 'Nazonazo & Quiz - Ittou Nyuukon Q Mate! challenges your brain with thousands of riddles. Compete against AI characters in various quiz formats that test your lateral thinking and general knowledge in this vibrant Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazotte-oboeru---otona-no-kanji-renshuu---kaiteiban-japan', 'NDS', 'Nazotte Oboeru - Otona no Kanji Renshuu - Kaiteiban (Japan)', '2006', 'Educational', 'Success', '1', 'Kanji Training', 'Educational Kanji writing.', 'Master Japanese Kanji through repetitive tracing.', 'Revised edition of the adult Kanji trainer.', 'Nazotte Oboeru - Otona no Kanji Renshuu - Kaiteiban uses the DS touch screen to improve your handwriting. This "Revised" edition features a refined recognition engine and an expanded list of daily-use Kanji for adult learners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazotte-oboeru---otona-no-kanji-renshuu---kanzen-ban-japan', 'NDS', 'Nazotte Oboeru - Otona no Kanji Renshuu - Kanzen Ban (Japan)', '2007', 'Educational', 'Success', '1', 'Kanji Training', 'Educational Kanji writing.', 'Master Japanese Kanji through repetitive tracing.', 'Complete edition of the popular Kanji trainer.', 'The "Kanzen Ban" (Complete Edition) of this series offers the most comprehensive list of characters. Perfect for those looking to master complex Kanji, it includes advanced stroke order guides and evaluation modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazotte-oboeru---otona-no-kanji-renshuu-japan', 'NDS', 'Nazotte Oboeru - Otona no Kanji Renshuu (Japan)', '2006', 'Educational', 'Success', '1', 'Kanji Training', 'Educational Kanji writing.', 'Master Japanese Kanji through repetitive tracing.', 'Tracing-based Kanji learning tool for adults.', 'Practice your penmanship with Nazotte Oboeru. This educational title focuses on "Adult Kanji," teaching not just how to read, but how to elegantly write the characters used in professional and social Japanese life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---most-wanted-europe-enfrdeesit', 'NDS', 'Need for Speed - Most Wanted (Europe) (En,Fr,De,Es,It)', '2005', 'Racing', 'EA Black Box', '4', 'Arcade Racing', 'Arcade street racing.', 'Become the most wanted driver and escape the police.', 'High-speed street racing and police chases.', 'Need for Speed: Most Wanted (Europe) brings the thrill of the chase to the DS. Win illegal street races, customize your performance cars, and evade intense police pursuit across a vast urban landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---most-wanted-usa', 'NDS', 'Need for Speed - Most Wanted (USA)', '2005', 'Racing', 'EA Black Box', '4', 'Arcade Racing', 'Arcade street racing.', 'Become the most wanted driver and escape the police.', 'North American release of the street racing hit.', 'Own the streets in Need for Speed: Most Wanted (USA). Featuring a variety of licensed cars and a "Blacklist" of rivals to defeat, it combines arcade driving with the constant threat of law enforcement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---nitro-europe-enfrdeesitnl', 'NDS', 'Need for Speed - Nitro (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Racing', 'EA Montreal', '4', 'Arcade Racing', 'Arcade racing with stylized graphics.', 'Race through city streets with an emphasis on style.', 'High-octane arcade racer with a vibrant look.', 'Need for Speed: Nitro (Europe) features a unique visual style and accessible handling. Use power-ups, customize your ride with graffiti, and maintain top speeds to dominate your opponents in this fast-paced racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---nitro-japan', 'NDS', 'Need for Speed - Nitro (Japan)', '2009', 'Racing', 'EA Montreal', '4', 'Arcade Racing', 'Arcade racing with stylized graphics.', 'Race through city streets with an emphasis on style.', 'Japanese release of the stylized NFS title.', 'Experience the flash and speed of NFS: Nitro in Japan. This version features the same intense arcade mechanics and deep customization, allowing players to "own" the track by leaving their mark on the city walls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---nitro-usa-enfrdeesitnl', 'NDS', 'Need for Speed - Nitro (USA) (En,Fr,De,Es,It,Nl)', '2009', 'Racing', 'EA Montreal', '4', 'Arcade Racing', 'Arcade racing with stylized graphics.', 'Race through city streets with an emphasis on style.', 'North American release of Need for Speed: Nitro.', 'Speed, style, and strategy collide in NFS: Nitro (USA). Designed specifically for a pick-up-and-play experience, it offers various game modes and a massive selection of cars from supercars to muscle cars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---prostreet-europe-enfrdeesit', 'NDS', 'Need for Speed - ProStreet (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'EA Black Box', '4', 'Simulation Racing', 'Professional circuit racing simulation.', 'Dominate professional racing events across the globe.', 'Shift from street racing to track-based simulation.', 'Need for Speed: ProStreet (Europe) focuses on precision and power. Compete in Drag, Drift, and Grip races, featuring deep engine tuning and a more realistic damage model than previous entries in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---prostreet-korea', 'NDS', 'Need for Speed - ProStreet (Korea)', '2007', 'Racing', 'EA Black Box', '4', 'Simulation Racing', 'Professional circuit racing simulation.', 'Dominate professional racing events across the globe.', 'Korean localized version of ProStreet.', 'Take your racing career to the professional level in Korea. NFS: ProStreet offers a refined control scheme and a career mode that takes you to the most prestigious racing venues in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---prostreet-usa-enfrdeesit', 'NDS', 'Need for Speed - ProStreet (USA) (En,Fr,De,Es,It)', '2007', 'Racing', 'EA Black Box', '4', 'Simulation Racing', 'Professional circuit racing simulation.', 'Dominate professional racing events across the globe.', 'North American release of the track racer.', 'Prove you are the king of the track in NFS: ProStreet (USA). Use the touch screen for fine-tuning your vehicle''s performance and experience the roar of the crowd in high-stakes legal racing events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---undercover-europe-enfrdeesitnl', 'NDS', 'Need for Speed - Undercover (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Racing', 'EA Black Box', '4', 'Arcade Racing', 'Open-world street racing and mission.', 'Go undercover to infiltrate a criminal syndicate.', 'Story-driven street racing with police chases.', 'Need for Speed: Undercover (Europe) features a cinematic narrative. Complete high-speed missions, engage in "Highway Battles," and use your driving skills to bring down a global crime ring from the inside.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---undercover-korea', 'NDS', 'Need for Speed - Undercover (Korea)', '2008', 'Racing', 'EA Black Box', '4', 'Arcade Racing', 'Open-world street racing and mission.', 'Go undercover to infiltrate a criminal syndicate.', 'Korean localized version of Undercover.', 'Experience the drama and speed of Undercover in Korea. With a focus on high-speed chases and car customization, this title delivers a portable open-world experience with a strong narrative focus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---undercover-usa-enfrdeesitnl', 'NDS', 'Need for Speed - Undercover (USA) (En,Fr,De,Es,It,Nl)', '2008', 'Racing', 'EA Black Box', '4', 'Arcade Racing', 'Open-world street racing and mission.', 'Go undercover to infiltrate a criminal syndicate.', 'North American release of NFS: Undercover.', 'Take the wheel in NFS: Undercover (USA). Fight off aggressive police AI and rival gang members in a series of high-stakes missions, featuring a deep garage of licensed vehicles to unlock and upgrade.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---underground-2-europe-enfrdeesit', 'NDS', 'Need for Speed - Underground 2 (Europe) (En,Fr,De,Es,It)', '2004', 'Racing', 'EA Black Box', '4', 'Street Racing', 'Street racing and deep customization.', 'Rise to the top of the underground racing scene.', 'The sequel to the legendary tuner culture game.', 'Need for Speed: Underground 2 (Europe) brings the tuner scene to the DS. Focus on visual and performance upgrades as you win races in a neon-lit city to earn respect and sponsorship deals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---underground-2-usa-enfrdeesit', 'NDS', 'Need for Speed - Underground 2 (USA) (En,Fr,De,Es,It)', '2004', 'Racing', 'EA Black Box', '4', 'Street Racing', 'Street racing and deep customization.', 'Rise to the top of the underground racing scene.', 'North American release of Underground 2.', 'Customize every aspect of your ride in NFS: Underground 2 (USA). This title emphasizes the "bling" and performance of the early 2000s car culture, featuring a variety of race types and a pulse-pounding soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed-carbon---own-the-city-europe-enfrdeesit', 'NDS', 'Need for Speed Carbon - Own the City (Europe) (En,Fr,De,Es,It)', '2006', 'Racing', 'EA Black Box', '4', 'Street Racing', 'Team-based street racing.', 'Take over the city''s territories with your crew.', 'Tactical street racing with a focus on territory.', 'NFS Carbon: Own the City (Europe) introduces crew-based mechanics. Recruit wingmen to help you block rivals or find shortcuts as you fight to control the city''s racing zones in this multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed-carbon---own-the-city-usa', 'NDS', 'Need for Speed Carbon - Own the City (USA)', '2006', 'Racing', 'EA Black Box', '4', 'Street Racing', 'Team-based street racing.', 'Take over the city''s territories with your crew.', 'North American release of the Carbon series.', 'Build your crew and conquer the streets in NFS Carbon: Own the City (USA). Featuring an exclusive story and specialized car classes, it offers a strategic layer to the traditional high-speed racing formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('negima!---chou-mahora-taisen---kattoiin-keiyaku-shikkou-dechaimasuu-japan', 'NDS', 'Negima! - Chou Mahora Taisen - Kattoiin, Keiyaku Shikkou Dechaimasuu (Japan)', '2006', 'Strategy', 'Russell', '1', 'Tactical RPG', 'Tactical RPG and battle simulation.', 'Win the Mahora Festival tournament with your team.', 'Anime-based RPG with tactical card-like combat.', 'Negima! Chou Mahora Taisen brings the popular manga to the DS. Form a team of students from Class 3-A and use specialized "Pactio" cards to unleash powerful spells and combos in grid-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('negima!---chou-mahora-taisen-two---checkiin-zenin-shuugou!---yappari-onsen-kichaimashitaa-japan', 'NDS', 'Negima! - Chou Mahora Taisen Two - Checkiin, Zenin Shuugou! - Yappari Onsen Kichaimashitaa (Japan)', '2007', 'Strategy', 'Russell', '1', 'Tactical RPG', 'Tactical RPG and battle simulation.', 'Enjoy the festival and win hot-spring battles.', 'The expanded sequel to the Negima! RPG.', 'Checkiin, Zenin Shuugou! adds more characters and a new story set during a hot springs trip. Expect more fan-service, refined combat mechanics, and plenty of mini-games featuring the Negima! cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neighbours-from-hell-europe-enfrdeesit', 'NDS', 'Neighbours from Hell (Europe) (En,Fr,De,Es,It)', '2006', 'Strategy', 'Appeal Studios', '1', 'Puzzle Strategy', 'Stealth and puzzle-based prank game.', 'Prank your neighbor without getting caught.', 'Humorous and strategic slapstick puzzle game.', 'Neighbours from Hell (Europe) tasks you with setting traps in your neighbor''s house. Use the stylus to combine items and create chaotic situations for a reality TV show, all while staying hidden.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neko-neko-bakery-ds-japan', 'NDS', 'Neko Neko Bakery DS (Japan)', '2007', 'Simulation', 'Taito', '1', 'Cooking Simulation', 'Management and cooking simulation.', 'Run a successful bakery with cute cats.', 'Adorable cat-themed bakery simulation.', 'Neko Neko Bakery DS allows you to knead dough and bake bread with the help of feline friends. Manage your shop, learn new recipes, and serve happy customers in this charming Japanese management sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neopets-puzzle-adventure-europe-enfrdeesnl', 'NDS', 'Neopets Puzzle Adventure (Europe) (En,Fr,De,Es,Nl)', '2008', 'Puzzle', 'Shaba Games', '1', 'Adventure Puzzle', 'Puzzle-adventure with Neopets characters.', 'Solve "Yooyuball" based puzzles to defeat enemies.', 'Competitive puzzle-board game set in Neopia.', 'Neopets Puzzle Adventure (Europe) uses a "Reversi" style mechanic for combat. Explore a story-driven world, collect "Petpets" to gain special abilities, and solve dozens of puzzles in this multi-language adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neopets-puzzle-adventure-usa', 'NDS', 'Neopets Puzzle Adventure (USA)', '2008', 'Puzzle', 'Shaba Games', '1', 'Adventure Puzzle', 'Puzzle-adventure with Neopets characters.', 'Solve "Yooyuball" based puzzles to defeat enemies.', 'North American release of the Neopets puzzler.', 'Battle your way across Neopia in Neopets Puzzle Adventure (USA). Featuring deep customization and a rewarding progression system, it''s a unique blend of board game strategy and RPG exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neoromance-game---harukanaru-toki-no-naka-de---yume-no-ukihashi-japan', 'NDS', 'Neoromance Game - Harukanaru Toki no Naka de - Yume no Ukihashi (Japan)', '2009', 'Visual Novel', 'Koei', '1', 'Romance Adventure', 'Visual novel and romance.', 'Navigate a dream-like world and find your destiny.', 'Otome romance game from the Harukanaru series.', 'Yume no Ukihashi is a crossover title featuring characters from the first three Harukanaru Toki no Naka de games. Experience romantic interactions and strategic battles in a beautiful Heian-period setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nep-league-ds-japan', 'NDS', 'Nep League DS (Japan)', '2008', 'Party', 'Game Studio', '4', 'Party Game', 'Quiz and trivia based on the TV show.', 'Compete in various language and logic challenges.', 'Popular Japanese TV show adaptation for NDS.', 'Nep League DS brings the excitement of the Fuji TV quiz show to your hands. Compete in "Five League" and "Jet" modes that test your kanji knowledge, vocabulary, and quick thinking under pressure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nervous-brickdown-europe-enfrdeesit', 'NDS', 'Nervous Brickdown (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Creatures', '1', 'Arcade Puzzle', 'Creative brick-breaking action.', 'Clear the screen by bouncing balls against bricks.', 'Innovative and artistic take on the Breakout genre.', 'Nervous Brickdown (Europe) reinvents the classic brick-breaker. Across 10 unique worlds, you''ll use the stylus to draw platforms, blow into the mic to clear smoke, and fight massive bosses in this creative masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nervous-brickdown-usa-enfrdeesit', 'NDS', 'Nervous Brickdown (USA) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Creatures', '1', 'Arcade Puzzle', 'Creative brick-breaking action.', 'Clear the screen by bouncing balls against bricks.', 'North American release of Nervous Brickdown.', 'Experience 135 levels of frantic action in Nervous Brickdown (USA). Each world features a completely different visual style and gameplay mechanic, from retro 8-bit homages to physics-based water levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('net-ghost-pipopa---pipopa-x-ds@daibouken!!!-japan', 'NDS', 'Net Ghost Pipopa - Pipopa x DS@Daibouken!!! (Japan)', '2007', 'Action', 'Konami', '1', 'Action Adventure', 'Action-adventure based on the anime.', 'Save the digital world "Net" with Pipopa.', 'Cyber-world adventure featuring the Net Ghost trio.', 'Net Ghost Pipopa takes you inside the computer. Use the unique abilities of the ghosts Pit, Pot, and Pat to solve puzzles, battle viruses, and explore a colorful digital universe in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nettou!-powerful-koushien-japan', 'NDS', 'Nettou! Powerful Koushien (Japan)', '2006', 'Sports', 'Power Pro Productions', '4', 'Baseball Simulation', 'Baseball management and simulation.', 'Lead your high school baseball team to Koushien glory.', 'High-school baseball sim from the "Powerful" series.', 'Nettou! Powerful Koushien features the iconic big-headed characters. Manage your team''s training, strategy, and roster to win the national championship in this deep and accessible sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neves-europe-enfrdeesit', 'NDS', 'Neves (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Yukes', '1', 'Block Puzzle', 'Tangram-based puzzle game.', 'Fit various shapes into a silhouette before time runs out.', 'Stylized and challenging Tangram puzzle game.', 'Neves (Europe) is a test of spatial reasoning. Rotate and place seven wooden blocks to match hundreds of different outlines, ranging from simple animals to complex geometric patterns in a relaxing multi-language environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neves-usa-enja', 'NDS', 'Neves (USA) (En,Ja)', '2007', 'Puzzle', 'Yukes', '1', 'Block Puzzle', 'Tangram-based puzzle game.', 'Fit various shapes into a silhouette before time runs out.', 'North American release of the puzzle hit Neves.', 'Known as "Seven" (Neves backwards), this title offers a minimalist and addictive experience. With over 300 puzzles and a competitive multiplayer mode, it’s a perfect fit for fans of classic logic games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-carnival---funfair-games-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'New Carnival - Funfair Games (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2011', 'Party', 'GameTek', '4', 'Carnival Minigames', 'Carnival mini-games and attractions.', 'Win tickets and prizes across various fairground games.', 'DSi Enhanced carnival simulation for Europe.', 'New Carnival: Funfair Games (Europe) offers 30+ arcade-style attractions. Use the DSi camera to put yourself in the game and win virtual prizes in classic challenges like Milk Can Toss and Ring Fling in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-carnival-games-usa-enfres-ndsi-enhanced', 'NDS', 'New Carnival Games (USA) (En,Fr,Es) (NDSi Enhanced)', '2011', 'Party', 'GameTek', '4', 'Carnival Minigames', 'Carnival mini-games and attractions.', 'Win tickets and prizes across various fairground games.', 'North American sequel to the hit Carnival Games.', 'New Carnival Games (USA) brings more attractions and DSi-exclusive features. Customize your avatar, explore new themed zones, and enjoy a variety of motion and touch-screen based challenges for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-chuugaku-eitango-target-1800-ds-japan', 'NDS', 'New Chuugaku Eitango Target 1800 DS (Japan)', '2007', 'Educational', 'Banpresto', '1', 'Vocabulary Training', 'English vocabulary training.', 'Master 1800 essential English words for students.', 'Educational English coach for Japanese middle schoolers.', 'New Chuugaku Eitango Target 1800 DS is a specialized learning tool. It uses interactive drills and pronunciation checks to help Japanese students memorize high-frequency English vocabulary for academic success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-eitango-target-1900-ds-japan', 'NDS', 'New Eitango Target 1900 DS (Japan)', '2008', 'Educational', 'Banpresto', '1', 'Vocabulary Training', 'English vocabulary training.', 'Master 1900 advanced English words for exams.', 'Advanced English vocabulary trainer for Japan.', 'Target 1900 DS focuses on high-level English for college entrance exams. It features a streamlined interface and progress tracking to ensure mastery of nearly 2000 advanced words and phrases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-horizon---english-course-1-ds-japan', 'NDS', 'New Horizon - English Course 1 DS (Japan)', '2006', 'Educational', 'Tokyo Shoseki', '1', 'Language Learning', 'Educational language course.', 'Learn English following the 1st-year school curriculum.', 'Interactive English course based on the popular textbook.', 'New Horizon - English Course 1 DS transforms the standard Japanese school textbook into an interactive experience. Practice listening, reading, and writing with audio support to build a strong English foundation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-horizon---english-course-2-ds-japan', 'NDS', 'New Horizon - English Course 2 DS (Japan)', '2007', 'Educational', 'Tokyo Shoseki', '1', 'Language Learning', 'Educational language course.', 'Learn English following the 2nd-year school curriculum.', 'Interactive English course for intermediate students.', 'Building on Course 1, Course 2 follows the Japanese second-year middle school English curriculum. It introduces more complex grammar and expanded vocabulary through engaging digital exercises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-horizon---english-course-3-ds-japan', 'NDS', 'New Horizon - English Course 3 DS (Japan)', '2008', 'Educational', 'Tokyo Shoseki', '1', 'Language Learning', 'Educational language course.', 'Learn English following the 3rd-year school curriculum.', 'Interactive English course for advanced students.', 'Course 3 prepares students for high school entrance exams. It covers the final year of middle school English in Japan, emphasizing reading comprehension and advanced sentence structure through daily practice.');